L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_YOO_MI_NA"
L3_1 = "펜릴 소대의 신입 소대원인 유미나는 펄스 리볼버로 원거리에서 적을 해치우는 공격수입니다.\n때로는 무기에 숨겨진 기능을 이용해 다수의 적을 처치하는 모습도 보여 줍니다. 전투 훈련을 받은 적도 없고, 제반지식도 일반인 수준인 업계 초보이지만 코핀 컴퍼니가 그녀의 세 번째 직장입니다.\n이전 직장에서 상관의 명령에 불복하며 무리하게 전과를 탐내거나, 보수 지급이 미뤄지자 무력 항의를 한 기록이 업계 익명 커뮤니티에 회자되고 있습니다.\n이런 무모한 행보를 보이는 동기는 거액의 가족 입원비로 추정되나, 본인은 사실 여부에 대해 침묵 중입니다. "
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HILDE"
L4_1 = "선봉대인 힐데는 최전선에서 백병전을 펼치면서 강력한 광역 공격으로 전황을 반전시킵니다.\n코핀 컴퍼니 초창기부터 펜릴 소대를 이끌어온 인물로, 제 4종 침식체 「크라켄」을 격퇴하여 회사가 정식 라이선스를 취득하게 만든 일등공신입니다.\n몇 년간 장기 휴직 상태로 행방이 묘연하다가 최근 현장에 복귀했습니다.\n업계에서는 언제나 정면 돌파를 제시하는 과격한 지휘 방침으로 악명 높았습니다.\n당시에는 대원들 개개인의 기량에 힘입어 펜릴 소대가 업계 상위권을 지키는 원동력으로 작용했지만, 소대원들이 대부분 이탈한 지금도 그녀의 지휘 방침이 유효할지는 미지수입니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JOO_SHI_YOON"
L5_1 = "전장 어디서든 나타나 적에게 역공을 가하는 트리키한 공격수입니다. 주무장은 허리에 찬 장도이지만, 평소엔 새끼손톱이 깨질 수 있다는 구실로 단검만 사용합니다.\n늘 주위에 평범한 사원을 자처하고 다니지만 그 말을 믿는 사람은 없습니다.\n소대장이 사라진 뒤에도 펜릴 소대에 남은 유일한 소대원으로, 사내에서는 개점 휴업 상태로 월급만 타기 위해서란 추측이 대세입니다.\n과거 주 52분 근무제 요구 시위나 정비반 만취근무의 주동자들은 사건 발생 직전 그와 대화를 나눈 적이 있다고 주장합니다. 관리부는 주시윤이 합법적인 태업을 위해 이들을 부추겼다고 의심 중입니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_SEO_YOON"
L6_1 = "언더그라운드에서 준수한 활약상을 펼쳐 온 알트 소대의 소대장. 뛰어난 지휘 능력으로 아군의 공세를 강화시켜 주는 공격수입니다.\n언더그라운드는 불법적으로 태스크포스 업무를 대행하는 민간 군사 조직들을 통칭하는 말로, 배신과 협잡이 일상처럼 벌어지는 곳입니다.\n서윤은 그런 아수라장에서 단 한 명의 소대원도 잃지 않고 수 개월만에 10여 건의 의뢰를 완수했습니다.\n데뷔 이전의 행적은 프라이버시를 이유로 공개하지 않았지만, 그간 보여 준 전술적 지식을 감안하면 사관학교에 준하는 군사 교육을 받았을 것으로 추정됩니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_YOO_JIN"
L7_1 = "유진은 적의 공격을 피하면서 적진에 뛰어드는 선봉대입니다.\n동급 카운터 중에서도 뛰어난 신체 능력이 특징이자 자랑으로 아슬아슬한 간격의 육탄전을 선호합니다.\n식사와 싸움이 삶의 낙인 전투광이며, 모든 문제는 싸움으로 풀 수 있다고 생각합니다.\n이터니움과 다이아몬드를 둘 다 예쁜 돌이라고 여길 만큼 단순하지만, 싸움에는 천부적인 재능을 갖고 있습니다.\n언더그라운드에서는 첫 의뢰 때 시비를 건 용병 집단을 초주검으로 만들어서 유해조수로 분류되어 있습니다.\n그럼에도 「사냥개」라는 별명으로 불리는 이유는, 소대장의 지시라면 기꺼이 몸을 던지기 때문일 것입니다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_XIAOLIN"
L8_1 = "소대의 막내인 샤오린은 또래보다 발육이 더디다는 단점을 저격수라는 보직으로 상쇄한 케이스입니다.\n생체 전류 조작 능력을 사용한 정밀  저격은 아무리 빠른 표적도 정확하게 명중시킵니다.\n작전 중에는 정보 수집과 적의 동태를 파악하는 역할을 훌륭히 수행해 냅니다. 알트 소대가 보여 준 높은 의뢰 완수율에는 그녀의 노고도 크게 기여했다고 사료됩니다.\n대물저격총을 주무장으로 사용하는데, 의뢰를 완수할 때마다 부착된 액세서리가 매번 달라집니다. 그녀는 작전 수행능력을 끌어올리기 위해서라고 하지만 실효성 없는 개조도 여러 번 거친 것으로 미루어 보아 비밀스러운 취미 생활로 추정됩니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_KIM_SOBIN"
L9_1 = "화력 지원 담당인 김소빈은 움직임이 굼뜨지만 한 번 자리를 잡으면 무서운 화력을 발휘할 수 있습니다.\n국소적인 아공간 형성 능력으로 대형 수송 차량의 탑재량에 버금가는 군사 물자를 휴대하고 다니기 때문입니다.\n온갖 흉악한 중화기를 사용하지만, 정작 피를 보는 것은 매우 꺼립니다.\n또한 아공간에는 항상 붕대와 소독약 등을 넣어 놓고 다녀서, 생면부지의 부상자라도 기꺼이 응급치료를 해 주곤 합니다.\n이렇듯 용병업과 거리가 먼 인물이 언더그라운드에 뛰어든 동기는 불확실합니다. 현재로서는 소대원들과의 친분 때문에 끌려온 것으로 추정할 따름입니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SL_RIFLE"
L10_1 = "다수로 운용되는 전천후 원거리 공격수.\n대 침식전 표준 장비로 무장한 스틸레인의 일반 병과입니다.\n뛰어난 장점이 없는 대신 눈에 띄는 단점도 없는, 민간 군사기업 소속 보병 부대의 표준이라고 할 수 있습니다.\n주무장인 SL-A2는 1984년부터 배치되기 시작한 정규군 제식 소총의 개량형으로 알려져 있습니다.\n저렴한 인건비와 속성 훈련으로 인원을 빠르게 보충할 수 있는 것이 특징입니다. 긴장한 신입들이 많아 내부에서는 이등병이라는 별명으로 통합니다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SL_SHIELD"
L11_1 = "적을 도발해서 아군을 보호하는 수비대.\n진압방패를 사용하는 일반 병과입니다.\n신규 입사자 중 신체 능력이 뛰어난 인원을 선발합니다.\n적의 진격으로부터 전선을 유지하는 훈련을 받았습니다. 화력은 기대할 수 없지만, 티타늄으로 코팅한 진압방패는 바이터의 발톱을 받아낼 만큼 튼튼합니다.\n결코 물러서지 않는다는 신념 덕분에 업계에서는 신용도가 높으나, 동료 의식이 강해 항상 단체로 사내 매점에 들이닥쳐 재고를 탕진시킨다는 소문이 돕니다."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SL_SNIPER"
L12_1 = "최후방에 머물면서 거리를 이용해 적을 일방적으로 공격하는 저격수.\nSL-S14 저격소총을 운용하는 특화 병과입니다. 정규군에서 저격수 양성 과정을 밟은 경험이 있는 인원으로 편성됩니다.\nSL-S14 저격소총은 높은 신뢰성과 함께, HUD와 자이로스코프의 연동으로 정확한 명중률을 자랑합니다.\n고도의 집중력을 위해 보조 약품까지 사용한다고 하는 이 대원들은, 적들이 코앞에 와도 망설임 없이 방아쇠를 당길 것입니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SL_SHOTGUN"
L13_1 = "범위 지상 공격으로 다수의 적을 밀어내는 선봉대.\nSL-OSG 산탄총을 사용하는 특별한 병과입니다. 배짱과 기민함은 물론, 빠른 상황 판단 능력까지 필요해서 실전 경험이 있는 인원을 우대합니다.\nSL-OSG는 스틸레인의 전신인 대로정밀 주식회사의 민수용 산탄총으로, 대정화 전쟁 중에도 그 저지력을 입증 받았습니다.\n이 총기는 스틸레인의 상징과도 같지만, 정작 대원들 사이에선 평상시의 뺀질거리는 모습탓에 말년병장으로 통합니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_AIR_FIGHTER"
L14_1 = "공중에서 전천후 사격을 지원하는 원거리 공격수. 저공에서 소형 기관포로 화력을 지원하는 전투용 드론입니다.\n퓨처 앳 워 프로젝트의 산물로, 단순한 구조 덕분에 유지 보수가 쉬워 일선 장병들의 사랑을 받았습니다. 오픈 라이선스를 채택해서 지금도 전 세계에서 생산되고 있습니다.\n참새의 생태를 참고한 인공지능이 탑재되어 있습니다. 충분한 시간만 들이면 애완동물처럼 길들일 수도 있다고 하지만, 보통 그전에 격추되므로 진실은 아직 수수께끼로 남아 있습니다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_AIR_BOMBER"
L15_1 = "공중에 머무르면서 지상 범위 공격을 가하는 선봉대. 저공 비행으로 접근해서 적의 머리 위에 폭탄을 투하하는 전투용 드론입니다.\n스패로우의 하드 포인트에 고폭탄 발사대를 장착한 사양입니다. 스틸레인이 스패로우의 화력을 강화해 달라는 시장의 요구에 부응해 처음 선보였습니다.\n스패로우에 탑재되는 인공지능은 전투 알고리즘 수정이 난해했던 탓에, 화재 진압용으로 공개되었던 버전을 일부 개선하여 대신 장착했습니다. 소화탄 대신 고폭탄을 투하한다는 점이 달라졌을 뿐이니까요."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_TANK"
L16_1 = "전방의 적을 밀어내면서 도발하여 아군을 보호하는 수비대.\n스틸레인이 생산하는 표준적인 성능의 3.5세대 민수용 주력전차입니다.\n우수한 험지답파능력 덕분에 이면세계의 가혹한 환경에서도 기동성을 잃지 않습니다. 대규모 군사 작전에 필요한 통합전 대응 전자장비는 선택 사항으로 구매 가능합니다.\n하지만 하운드의 가장 큰 장점은 역시 뛰어난 가성비입니다. 업계 커뮤니티에서 활동하는 컨설턴트들은 소기업이 처음 장만하기 좋은 기갑 병기로 손꼽습니다. \n리베이트를 얼마나 받는 건지 모르겠네요."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_HEAVY_TANK"
L17_1 = "핵심 목표를 대상으로 강력한 공격을 가하는 공성대.\n통상 화력으로는 상대하기 어려운 대형 침식체를 제압하기 위해 스틸레인이 개발한 공성전차입니다.\n압착 공기와 대량의 화약으로 탄봉을 돌출시켜 목표물을 파괴합니다. 위력은 강력하지만 장전에 시간이 오래 걸리고 교전 능력도 전무해서 반드시 호위가 필요합니다.\n본래 전흔 재건 계획에서 구조물 철거와 지형 평탄화에 사용할 목적으로 개발된 중장비였으나, 예상 이상의 위력 덕분에 군사 장비로 용도가 바뀌었다고 합니다. "
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_AIR_HELI"
L18_1 = "공중에 머물면서 지상에 범위 공격을 가하는 원거리 공격수.\n인공지능 탑재를 전제로 설계한 공격 헬기입니다. 공대지 무장인 베인파이어 미사일로 지상 목표를 효율적으로 처리합니다.\n퓨처 앳 워가 강세인 고가 군사 장비 시장에 진입하고자 야심차게 준비했던 차세대 주력 상품입니다. 특히 3세대 보우스트링 FCS는 어떤 악조건 하에서도 명중률을 보장하는 건실한 성능으로 널리 알려졌습니다.\n생산라인 문제로 인한 납품 지연과 어중간한 가격대 탓에 시장의 외면을 받았지만, 안목 좋은 고객들은 호평하는 기종입니다."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_CARGO"
L19_1 = "자신의 체력을 소모하면서 주기적으로 소총병을 배치하는 농성 전력.\n스틸레인이 생산하는 수송용 장갑 차량입니다. 적재함에는 완전 무장한 1개 소대가 탑승할 수 있습니다.\n방탄 차체를 적용하였지만, 자체 전투력은 없습니다. 타 구역에 배치된 보병 전력을 신속하게 실어 나르는 것이 주요 임무입니다. 최근 취약한 침식파 방호능력을 지적 받고 있지만, 스틸레인은 아직 이에 대해 뾰족한 대책을 내놓지 않은 실정입니다.\n일부 스틸레인 보병들이 일과 시간 동안 적재함에 숨어 휴식을 취한다는 제보가 있습니다. 경비원들의 주의가 필요합니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ORCA"
L20_1 = "오르카는 적을 처치할 때마다 부상을 회복하면서 전투를 속행하는 선봉대입니다.\n오르카란 불길한 붉은색으로 빛나는 워치의 이름입니다. 업계에 떠도는 소문에 따르면, 오르카를 손에 넣은 카운터는 죽을 때까지 침식지대를 떠돌면서 침식체를 사냥한다고 전해집니다. 일설에는 오르카에 깃든 이전 주인들의 증오심이 새로운 소유자를 사냥에 집착하게 만든다고 합니다.\n오르카의 소유자를 목격했다는 보고는 관리국 설립 이래 끊이지 않았습니다.\n그중 가장 최근 보고된 소유자는, 놀랍게도 이전 사례들과 달리 사냥 충동을 일정 수준 제어하고 있다는 사실이 확인된 상태입니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_FOX_RIFLE"
L21_1 = "주기적으로 유탄을 발사해서 범위공격을 가하는 원거리 공격수.\n사막전으로 단련되어 어떤 상황에서도 표준적인 전투력을 발휘하는 용병들입니다. 부착식 유탄 발사기로 부족한 화력을  보충하고 있습니다.\n유탄소총병 중에는 자금 사정에 떠밀려서 페넥폭스에 가입한 군 출신들이 많습니다.\n주특기 수행에 편중된 각 병과를 풍부한 작전 경험에 바탕해서 유기적으로 연결해 주기 때문에 없어서는 안 될 존재입니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_FOX_SNIPER"
L22_1 = "사격을 반복할수록 공격 속도가 빨라지는 저격수.\n지정 위치를 사수하면서 적을 요격하는 데 특화된 저격수입니다. 적의 사정거리 밖에 머무르면서 엄호 사격으로 아군이 안전하게 활동할 수 있는 환경을 조성합니다.\n신중하고 지시에 충실한 성격 때문에 한 번 지정 받은 위치는 반드시 지킵니다. 총상을 입어도 꼼짝하지 않아서 적이 사살했다고 착각했다는 일화로 유명합니다.\n말수가 적어 무뚝뚝해 보이지만, 평시에는 부대원들의 기강을 잡는 잔소리 많은 군기반장입니다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_FOX_RPG"
L23_1 = "지상 기갑 병기를 효과적으로 파괴할 수 있는 원거리 공격수.\n대전차 로켓을 전문적으로 운용하는 특화 병과입니다. 이들의 표적에는 장갑차나 전차는 물론 두터운 갑피를 두른 침식체도 포함됩니다.\n사상자가 가장 많은 병과이지만, 경험 많은 상급자들은 위기에 노출되더라도 어떻게든 생환하는 신기한 재능이 있습니다.\n병과 특성상 전투 중 적의 화력에 노출되기 쉬워서 다른 병사들보다 미신에 민감합니다.\n특히 드롭스 사탕은 아예 입에도 대지 않는 편입니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_FOX_STINGER"
L24_1 = "비행체를 파괴하는 데 특화된 저격수.\n지대공 미사일로 부대의 대공 방어를 담당하는 특화 병과입니다. 이 병과에는 내전 중의 폭격, 침식체의 공습 등을 겪은 생존자들이 모여 있습니다.\n아픈 경험 때문에 천장이 있는 실내에서는 오래 머물러 있지 못하고, 대화 중에도 수시로 하늘을 확인합니다.\n대공 경계 태세에 대한 집념은 전용 목적으로 설계한 인공지능 못지 않게 강합니다.\n최근에는 회사 옥상에 숙소 설치를 건의했습니다. "
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_FOX_MORTAR"
L25_1 = "위치를 고정하고 먼 거리에서 높은 화력을 지원하는 농성 전력.\n구형 박격포를 사용하는 병과입니다. 현용 병기에 비해 부족한 화력을 정확성 높은 포격으로 보충합니다.\n구식 무기로 다른 용병들과 대등한 전과를 달성한다는 사실에 굉장한 자부심을 지니고 있습니다.\n항상 2인 내지 3인 1개 조로 행동하며, 조원 간의 유대감이 매우 강합니다.\n부대 내의 궂은 일거리를 도맡아 하는데, 협동심을 연마하기 위해서라고 합니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FOX_HOWITZER"
L26_1 = "초장거리에서 핵심 목표를 집중 공격하는 공성대.\n뛰어난 성능을 지녔지만 생산성 문제가 발목을 잡았던 자주포입니다. 52구경장 155mm 곡사포는 침식체 상대로도 충분한 위력을 발휘합니다.\n페넥폭스의 기반 지역에는 남아 있던 수량도 적은 데다가 한동안 부품 수급 문제로 홍역을 겪어서 뛰어난 성능에도 불구하고 실전에서는 찾아보기 어려웠던 기종입니다.\n페넥폭스는 이 기종의 운용을 포기하려 했지만, 대체할 기갑 병기가 없었기 때문에 결정은 보류된 상태입니다. "
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FOX_ANTIAIR"
L27_1 = "대공 공격에 특화되었지만 전천후 사격이 가능한 원거리 공격수.\n20세기 중반부터 활약해 온 자주 대공포계의 노익장입니다.\n23mm 기관포 4문을 탑재해서 방공 전투뿐만 아니라 지상 표적 파괴에도 유효한 위력을 발휘합니다. 상부에 설치된 레이더는 감시 장비가 열악한 페넥폭스에게 큰 도움이 됩니다.\n차량의 장갑이 취약하기 때문에 단독 교전은 참패를 부를 수 있습니다. 보병 병과와의 혼성 운용을 권장드립니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FOX_ROCKET"
L28_1 = "보병 제압에 특화된 지상 범위 공격을 가하는 저격수.\n다연장 로켓 시스템을 탑재한 중형 전술 차량입니다. 민간 시장이 확대된 지금도 민수용 판매가 제한되어 있는 기종이지만, 전후 버려진 주둔지에 방치되어 있던 수량을 페넥폭스가 점유했습니다.\n다수의 적을 상대로 압도적인 교환비를 선보이기 때문에, 페넥폭스가 유독 애지중지하는 기갑 병기입니다. 유지보수 수단이 제한적이기 때문에 중요한 작전 활동에만 투입됩니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FOX_VEHICLE"
L29_1 = "배치시 적들을 밀어내는 선봉대.\n대정화 전쟁 중에 대량으로 공수되었던 고기동성 다목적 차량입니다. 무장은 단출하지만 전투 지역에 과감하게 돌입해서 적의 진격을 잠시 저지할 수 있습니다.\n상부에 탑재된 기관총으로 제 1종 침식체와 비교적 안전한 교전이 가능했기 때문에, 국제 연합군이 주둔지 일대의 치안 유지 목적으로 사용했습니다.\n바이킹만큼 짜릿한 특유의 승차감은 인공지능 탑재 이후에도 달라지지 않았습니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_TIDE_SUBMACHINEGUN"
L30_1 = "교전이 길어질수록 능력치가 상승하는 원거리 공격수.\n스카우트는 선제 타격으로 위험 요소를 제거하는 초동 전력입니다.\n경량화된 전투복과 서브 머신건만으로 무장한 이 병과는 위험으로 가득찬 현장을 거침없이 헤집고 다니면서 아군의 진입을 돕고 귀중한 정보를 제공해 줍니다\n소위 말하는 촉새들이 많다는 평이지만, 투철한 사명감으로 무장했더라도 긴장감과 두려움을 덜어내기 위해서는 어쩔 수 없는 선택일 것입니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_TIDE_GUNSHIELD"
L31_1 = "이동 중에 전천후 공격이 가능한 수비대.\n스트롱홀드는 시가전의 피해 확대를 막기 위해 투입되는 제압 전력입니다. 중장형 강화복 스트롱홀드는 거의 모든 재래식 개인 화기로부터 생존을 보장합니다.\n은퇴한 경찰들로 이루어져 있는 것이 특징입니다. 이들은 관리실패부터 대정화 전쟁에 이르는 격동기 동안 현장을 지킨 베테랑으로, 권총 한 자루로 기꺼이 적의 주의를 끕니다. 동료를 잃는 것보단 자신이 공격 받는 편이 참을 만하기 때문입니다. "
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_TIDE_GRENADE"
L32_1 = "유탄으로 범위 공격을 가하는 저격수.\n스위퍼는 실내에 진을 친 적을 제압하기 위해 투입되는 타격 전력입니다.\n저격수 출신들이 편성되어 있으며, 조준이 어려운 유탄발사기로도 백발백중의 솜씨를 자랑합니다.\n블랙 타이드에서 가장 괴짜들만 모인 병과라는 평이 중론으로, 뛰어난 사격 실력에 강한 자신감을 가지고 있기 때문인지 늘 여유로운 태도로 일관합니다.\n하지만 도넛을 사랑하고 시민들을 지키려는 사명감은 동료들과 다르지 않습니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_TIDE_SHOTGUN"
L33_1 = "범위 공격으로 적을 밀어내면서 방어력을 감소시키는 선봉대.\n터미네이터는 침식체의 출몰이 확인될 시 투입되는 특무 대원을 의미합니다.\n터미네이터 강화복은 인간 크기의 중장비에 가까운 내구도와 출력을 발휘합니다.\n하지만 작동하려면 중추 신경에 회로를 용접하는 고통스러운 과정을 거쳐야 해서 실전 배치는 제한적으로 이루어졌습니다.\n이 병과는 직무 중에 중도의 육체적 후유증을 얻은 경찰들이 자원 의사를 밝힐 경우에만 엄격한 심사 과정을 거쳐 증원됩니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_TIDE_VEHICLE"
L34_1 = "배치시 적들을 밀어내는 선봉대.\n채리엇은 시가전 중 축성과 급속 진지 구축을 위해 개발된 전투차량입니다. 알루미늄 런플랫 타이어와 두터운 금속 장갑은 전차와 같은 방호성을 제공하기 때문에, 최전방에서도 충분히 활약할 수 있습니다.\n특히 중량이 큰 스트롱홀드, 터미네이터 병과는 공중 수송이 어려워서 채리엇이 그들의 발이 되어 줍니다.\n내부 공간은 각종 장비 때문에 협소하지만, 현장에서 구출한 시민들을 안전한 지역으로 이송할 때에는 유용합니다."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_TIDE_HELI"
L35_1 = "파괴된 지점에 스카우트를 배치하는 원거리 공격수.\n신속한 전력 투입을 위해 개발된 헬기입니다. 저소음 설계를 적용했기 때문에 작전 현장까지 안전하게 도착할 수 있습니다.\n측면에 기관총을 설치해 뒀지만, 교전 능력은 우수하다고 보기 어렵습니다.\n그 대신 블랙테일이 지닌 또다른 장점은 추락시 작동되는 탑승석 사출 장치입니다. 이 장치를 도입한 이후 수송 중인 병력의 생존률은 80퍼센트로 크게 상승했습니다. "
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_TIDE_DRONE"
L36_1 = "범위공격을 쏟아부은 뒤에 이탈하는 1회성 공격수입니다.\n정밀 타격용 UAV로, 시가지에서 피해 확산을 억제하기 위해 운용 중입니다.\n관리가 쉽고 화력이 우수한 덕분에 군에서 재도입을 고려 중입니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_SPIDER"
L37_1 = "아라크네는 퓨처 앳 워 계획의 시가전용 기동병기로서, 메카닉을 상대로 강력한 전천후 원거리 딜러로 설계되었습니다.\n대 테러전의 다양한 변수에 능동적으로 대처하기 위해 「자율사고 인공지능」이 탑재됐으며, 전용 네트워크를 통해 사고와 학습을 공유하기 때문에 아라크네는 분대 단위가 하나의 개체처럼 일사불란하게 행동합니다.\n실험적인 인공지능의 위험성에 대한 지적으로 프로젝트가 폐기되어 양산화 계획은 취소되었지만, 덕분에 본사가 새로운 후원자로서 저렴한 가격에 인수할 수 있었습니다. "
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_TITAN"
L38_1 = "타이탄은 퓨처 앳 워 계획의 시작형 섬멸 병기로, 비용이 높은만큼 강력한 성능을 발휘하는 초대형 메카닉입니다.\n3종 침식체에 단독 대응하는 것을 목표로 제작되었으나, 북극점 작전 성공 후 예산의 방향성이 다소 조정되면서 생산이 중단됐습니다.\n하지만 현재도 다수의 개체가 군이나 방위산업체에서 활약 중이며, 원래 터무니 없는 가격과 유지비 때문에 본사에선 운용이 어려웠으나, 「자율사고 인공지능」이 탑재된 일부 타이탄이 명령권자의 지시를 거부했다는 이유로 특별취급되어 본사가 이를 최근 비교적 간단히 입수하게 되었습니다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_VATICAN_BENEDICT"
L39_1 = "베네딕트 콘스탄틴은 원거리 공격에 대한 내성을 바탕으로 근접전을 벌이면서 적을 기절시키는 데 특화된 수비수입니다.\n기적심의회는 침식 현상으로부터 주님의 어린 양들을 지키기 위해 소집된 기관입니다. 심의회의 일원인 베네딕트는 강철 같은 신앙심과 의표를 찌르는 검술로 최전선에서 활약 중입니다. 그의 헌신적인 자세는 많은 이들에게 귀감이 되고 있습니다.\n하지만 그가 걷는 신앙의 길이 과연 올바른지에 대해서는 의심스러운 정황들이 존재합니다. 심의회의 성직자들은 베네딕트가 시국의 비밀 서고에 출입한 이후부터 교리를 이해하는 관점이 바뀐 것 같다고 불안해 하고 있습니다."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_VATICAN_CINDY"
L40_1 = "신디 루퍼는 스스로 체력을 회복하면서 싸우는 선봉대입니다.\n워치에서 만들어진 전기톱은 톱날에 걸린 적에게서 저항 의지를 앗아갑니다.\n이 자그마한 수녀는 한 폐쇄적인 이단 공동체에서 발견된 유일한 생존자입니다. 발견 당시 그녀는 B급 스플래터 영화가 녹화된 VHS를 다수 소지하고 있었습니다. 이후 조사를 통해 이 VHS들은 신디의 인격 형성에 많은 기여를 했음이 밝혀졌습니다.\n예배는 빠지기 일쑤에 기도문도 잘 외우지 못하지만, 주님의 적들을 해치우는 일에서만큼은 놀라운 기량을 선보입니다.\n그녀는 전기톱의 시동음으로 찬송을 대신한다는 확신에 가득 차 있습니다."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_VATICAN_CLOUDIA"
L41_1 = "클로디아 넬슨은 기도를 통해 다수의 아군을 보호하고 부상을 치료해 주는 지원가입니다.\n클로디아는 사람들에게 봉사하는 것을 기쁨으로 여기는 어린 수녀입니다. 그녀가 기도 중에 워치를 받았다는 소식이 전해졌을 때, 심의회는 이것을 신앙의 기적으로 해석해야 할지 혼란에 빠졌습니다.\n심의회의 활동 외에도 가까운 보육원과 성당에서 일손을 돕는 것이 그녀의 일과입니다. 성직자들은 헌신적인 자세에 감명하면서도 주방 출입만은 엄금하고 있습니다. 클로디아가 만든 요리가 정신적인 후유증을 야기한다는 사실은 그녀만 모르는 공공연한 비밀이기 때문입니다."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_AMY"
L42_1 = "에이미 스트릭랜드는 특수한 요요로 먼 거리에서 광역 공격을 가하는 선봉대입니다.\n전투의 리듬을 탈수록 요요를 다루는 묘기는 더욱 화려하고 빨라집니다.\n에이미는 프리덤 라이더즈의 리더로서 위험을 목격하면 그냥 지나치지 않습니다. 그 바람에 온갖 사건에 휘말리기도 하지만, 꿋꿋이 주변 사람들을 격려해 주면서 함께 위기를 헤쳐 나갑니다.\n자신이 카운터가 된 이유가 다른 사람들을 돕기 위해서라고 믿으며, 주어진 힘을 올바른 곳에 쓰기 위해 언제나 최선을 다합니다. 대가도 바라지 않고 솔선수범하는 모습은 최근 업계에서 보기 어려운 마음가짐입니다."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_KIM_CHEOLSU"
L43_1 = "김철수는 강력한 격투기로 적들의 전열을 무너트리는 수비수입니다.\n과거 평범한 회사원이었던 그는 갑작스레 마주한 침식재난에서 극적으로 카운터로 각성하여 살아남았습니다. 당시 그가 발차기로 침식체를 때려잡는 장면이 포착되어 화제가 되었는데, 그것은 어린 시절에 보았던 격투오락의 기술을 자신도 모르게 구현해 낸 것이라고 합니다.\n그를 격투기영웅으로 추앙하던 여론과는 달리, 김철수 본인은 한동안 재난 트라우마에 시달리며 힘든 시기를 보냈으나, 재활 끝에 다시 일을 시작하기로 결심했습니다.\n이번엔 돈을 버는 평범한 직장이 아닌, 침식체들과 맞서 싸우는 태스크포스에 지원한 것입니다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FREEDOM_KASUMI"
L44_1 = "광역 공격을 가해 적의 시선을 끄는 수비수입니다.\n실험에 따르면, 히로세 아키의 대검은 주인의 의욕에 비례해 중량이 변한다고 합니다. 워치는 죽음을 앞두고 나타나는 강한 생존 의지나 그에 준하는 집념에 반응해 나타난다는 것이 정설입니다.\n그렇다면 히로세 아키가 카운터로 각성한 이유도 설명이 가능합니다. 무위도식을 향한 집념만큼은 누구에게도 지지 않기 때문입니다.\n아키의 궁극적인 소원은 안정적인 수입원입니다. 빠르게 돈을 벌 수 있는 방법은 용병업이겠지만, 일하면 패배라는 생각에 시도해 본 적도 없다고 합니다."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FREEDOM_LEE_MINSEO"
L45_1 = "이민서는 원거리에서 광역 공격을 가해서 적의 행동을 제약하는 지원가입니다.\n게임 신기록을 경신하려고 침식 경보도 무시하다가 봉변을 당했으나, 카운터로 각성해서 극적으로 살아남은 케이스입니다.\n문제는 그렇게 얻은 힘을 마법소녀 코스프레에만 사용하고 있다는 점입니다. 고전 게임인 「네크로노미코」 시리즈의 열렬한 팬으로, 민서가 입은 복장은 이 시리즈에 등장하는 주인공인 네크로노미코의 것입니다.\n하지만 괴물들과 싸우는 네크로노미코와 달리 제 1종 침식체만 봐도 다리가 후들거리는 탓에 용병업계로의 진출은 무리라는 모양입니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FREEDOM_LIN"
L46_1 = "수수께끼의 힘으로 아군의 증원 속도를 빠르게 만드는 공격수입니다.\n전장에서 뿌리고 다니는 돈에는 자신의 얼굴을 인쇄해 놓은 것이라고 합니다.\n시대의 풍운아, 고독한 총잡이를 표방하는 린 시엔은 용병이란 단어와 백만 광년 떨어진 금융계 거물의 외동딸입니다.\n느와르물에 흠뻑 취해 최고의 총잡이가 되겠다면서 가출해 버린 상태로, 측근들은 돌려 보내 줘도 금방 빠져나갈 테니 발견하면 잘 보호해 달라는 코멘트를 남겼습니다.\n린 시엔의 특기는 전투 중에 그럴싸한 대사─여긴 내게 맡겨─를 읊고 쓰러졌다가 어느새 멀쩡하게 돌아오는 것입니다. 놀라운 생존 능력이지만 당사자는 폼이 나지 않는다는 이유로 이에 대해 설명하기를 무척 부끄러워합니다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DELTA_MARIA"
L47_1 = "마리아 안토노프는 아군의 공세를 배가시키면서 휘하 부대를 즉시 전장에 투입하는 공격적인 파수꾼입니다.\n안토노프 중장은 대정화 전쟁의 승리를 이끈 영웅으로 잘 알려져 있습니다. 그녀가 창안한 대 침식전 교리는 현재까지도 태스크포스 업계에서 유용하게 쓰이고 있습니다.\n러시아 망명 3세이자 철저한 원칙주의자로, 군 상층부의 견제를 실력만으로 돌파해 지금의 위치에 이르렀습니다. 일설에는 장성이 된 지금도 현장에서 세계 각지의 주요 비공식 작전들을 직접 지휘하고있다고 합니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DELTA_JAKE"
L48_1 = "제이크 워커는 빠르게 기술을 재사용해서 적을 밀어붙이는 건실한 선봉대입니다.\n워커 대령은 소수 정예를 추구하는 델타 세븐에서도 신뢰 받는 현장 요원입니다.\n그는 영리하고 치밀한 작전을 계획할 시간에 사건의 원흉을 찾아가 때려눕혀 버립니다. 워커 대령의 이런 지나치게 대범한 방식은 지휘부에 항상 논란을 불러 왔습니다.\n하지만 일선의 병사들은 위험을 무릅쓰고 앞장서는 그를 깊이 신뢰하며 따릅니다.\n워커 가문은 많은 전쟁에 참전해 무훈을 세운 집안으로, 부하들을 위해서라면 몸을 아끼지 않는 자세는 가풍에서 비롯되었다고 추정됩니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DELTA_KYLE"
L49_1 = "카일 웡은 주어진 장비를 활용해 적의 공격을 분산시키면서 강력한 지속 피해를 입히는 다재다능한 공격수입니다.\n델타 세븐의 내사과 소속인 그는 연방 정부가 추진한 카운터 양성 계획의 최우수 사례로 꼽힙니다. 양성 과정에서 카운터에 최적화된 신식 훈련을 받았으며, 이를 바탕으로 다양한 카운터용 특수 장비들을 활용해 효율적인 교전을 유도합니다.\n안토노프 중장을 상관으로서 존경하며, 그에 걸맞게 철두철미한 보좌관을 지망하고 있습니다. 불시에 초 단위 스케줄로 순찰하며 기강 해이를 적발하기 때문에 델타 세븐 대원들에겐 두려움의 대상입니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DELTA_SYLVIA"
L50_1 = "실비아 레나 쿠퍼는 아군 기갑 병기를 강화시키면서 광역 공격을 가하는 저격수입니다.\n그녀는 초등학생 때 이미 뛰어난 해킹 솜씨로 모국 정보기관의 데이터베이스 통제권을 탈취해 악명을 떨쳤습니다.\n물론 꼬리가 길면 밟히는 법으로, 현재는 슈퍼맥스급 교도소에서 평생을 보내는 대신 안토노프 중장의 선처를 받아 델타 세븐에서 민간 전자전 고문직에 종사 중입니다.\n별 수 없이 앞뒤 꽉 막힌 군인들과 일하기로 했지만, 방에서 해킹만 하던 시절보다 스릴 넘치는 비밀 작전 쪽이 적성에 맞았는지 아직까지는 큰 사고 없이 현장을 누비고 있습니다."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_STATE_RIFLE"
L51_1 = "주기적으로 범위피해를 주며, 범위피해를 가할 때마다 강해지는 공격수입니다.\n미 합중국 국방력의 기반. 정규군 혁신화 사업으로 개발된 신형 장비 실험을 위해 대 침식전에 종사 중입니다. 곧 침식체도 성조기를 두려워할 날이 올 겁니다."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_STATE_AIRBORNE"
L52_1 = "어디에나 배치할 수 있는 높은 공격력의 전천후 공수부대입니다.\n적 후방에 침투하는 특수병종으로, 적의 증원과 화력 지원을 차단하는 데 능숙합니다. 입은 거칠어도 필요하면 언제든 사지로 뛰어들 준비가 되어 있습니다."
L50_1[1] = L51_1
