L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_STATE_ENGINEER"
L3_1 = "아군 메카닉을 회복하고 강화하는데 특화된 지원형 보병입니다.\n현장에서 기갑병기를 관리하는 병종으로, 고가의 장비들이 전선에 더욱 오래 머물게 해 줍니다. 평시에는 사내 시설을 무상으로 수리해 주기도 합니다."
