L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_STATE_HELI"
L4_1 = "어설트 트루퍼를 투하하는 파수꾼입니다.\n수송에 특화된 군용 헬기로, 적의 요격을 돌파할 수 있는 내구성이 특징입니다. 적진 한복판에 뛰어드는 공수부대원들이 주 승객이라고 합니다. "
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_STATE_TANK"
L5_1 = "지상에 범위피해를 주며 대공능력 또한 뛰어난 공격수입니다.\n대 침식전용으로 개량된 주력전차로서, 전차에 요구되는 모든 성능을 충족하지만, 단독 운용보다 다른 군종과 협조할 때 위력을 발휘합니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_STATE_AIRCRAFT"
L6_1 = "공중전에 특화된 공격수입니다.\n단거리 이륙, 수직 착륙형 사양. 개발 과정에서 우여곡절이 많았던 기체입니다. 리프트 팬을 이용하여 지상군과 지속적인 협동 작전이 가능합니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_STATE_BOMBER"
L7_1 = "맵 전체를 타격하는 1회성 공격수입니다.\n가변익을 장착한 전략 폭격기. 특이한 외형 덕분에 출처 불분명한 별명이 많습니다.\n현재는 긴 체공시간을 이용해 근접 항공 지원기로 쓰입니다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_STATE_GUNSHIP"
L8_1 = "배치지점에 광역버프를 제공하며, 적에게 지속적인 피해를 주는 전술기입니다.\n20세기 중엽 취역한 지원공격기로, 죽음의 천사라는 별명으로도 유명합니다. 120mm 박격포를 탑재하고 작전 지역 상공을 선회하며 화력을 제공합니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_CHARLOTTE"
L9_1 = "처녀자리의 기사, 에스테로사 드 슈발리에는 배리어로 자신을 보호하며 최전선에서 싸우는 선봉대입니다.\n그녀는 기사가문 출신이 아님에도 전임자로부터 조디악 나이츠의 기사단장의 자리를 물려받게 된 이례적인 케이스로, 전통을 중시하는 원로들에게 많은 견제를 받고 있습니다.\n선대를 대신해 자신이 모든 걸 짊어져야 한다는 막중한 책임감 때문에 평소엔 엄격하고 근엄한 기사단장의 행세를 하고 있지만, 사실 그녀의 속내는 누구보다 따뜻하고 여립니다.\n본인은 자신의 이러한 내면을 잘 숨기고 다닌다고 생각하지만, 그녀와 함께 생활하는 단원들은 귀여운 동물만 보면 시선을 떼지 못하거나 악몽을 떠벌리는 잠꼬대로부터 진상을 이미 눈치채고 있습니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_YANG_HANSOL"
L10_1 = "양자리의 기사, 양한솔은 검기로 적을 밀어내는 공격수입니다.\n최근에 능력을 각성하여 조디악 나이츠에 견습단원으로 입단한 그는 부족한 자신도 언젠가 한 사람의 기사 몫을 해내겠다며 매일 죽도 일만 번을 휘두르고 있습니다.\n하지만 기량검사에서 이미 카운터의 평균을 훨씬 웃도는 잠재력이 확인되었으며, 본인만이 이 사실을 자각하지 못하고 있을 뿐입니다.\n그가 힘을 깨닫기 위해 필요한 것은 근력 운동이 아닌 충분한 시간이지만, 굳이 이 사실을 밝혀서 자기계발 의지를 꺾을 필요는 없다고 판단했기 때문에 본인이 자각하기 전까진 사실에 대해 침묵하기로 단원들에게도 동의를 구했습니다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_ARIUS"
L11_1 = "물병자리의 기사, 에리어스 에스퀘데는 의지가 담긴 성수로 아군을 회복하고 보호막을 부여하는 회복형 지원가입니다.\n카운터임에도 불구하고 전반적인 체력평가는 일반인에 미치지 못할 정도인 그녀는 각성 이전엔 외출도 힘겨울 정도로 몸이 불편했었습니다. 조디악 나이츠를 후원하는 재력가의 딸이지만 동시에 기사단을 동경해왔었기에, 힘을 얻게 된 뒤 사람들을 도우며 많은 곳을 모험하고 싶단 생각으로 기사단에 입단을 자처했습니다.\n집안에서 요양할 때는 미처 몰랐던 그녀의 타고난 호기심 때문에 단원들은 자꾸만 어디론가 사라지는 후원자 가문 아가씨의 안위를 늘 걱정합니다. 하지만 그녀는 단원들이 자신을 더 이상 지켜줘야 할 대상이 아닌 한 사람의 같은 기사이자 등을 기댈 수 있는 동료로서 받아들여주길 바랍니다."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_PIONE"
L12_1 = "전갈자리의 기사, 피오네 로웰은 아군의 방어력을 강화시켜주는 지원형 수비수입니다.\n조디악나이츠의 부단장으로서, 군인출신 집안에서 자란 그녀는 규율이 있어야 집단을 올바르게 통제할 수 있다고 생각합니다. 그래서 규칙적인 훈련과 단원 개개인의 성실성을 강조하며, 가벼운 일탈에도 아주 엄격합니다. 단원들은 그녀의 그런 꼿꼿한 성미에 부담을 느끼는 한편, 자신들의 책무가 결코 가볍지 않음을 알기에 그녀의 방식 또한 어느 정도 존중하고 있습니다.\n로웰 가문에선 그녀에게 많은 기대를 걸고 있으며 그녀가 에스테로사를 밀어내고 단장이 되길 원하지만, 당사자는 규율만큼이나 단장을 존중하고 있기 때문에 개의치 않고 부단장의 자리에서 본분을 다할 뿐입니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_LIV"
L13_1 = "천칭자리의 기사, 리브 앨런은 지치지 않는 체력으로 적을 몰아붙이는 선봉대입니다.\n그녀는 항상 놀고 싶어하는 말괄량이처럼 보이며 실제로도 그렇게 행동하지만, 동시에 약자를 남겨두곤 결코 물러서지 않는 정의감 넘치는 기사이기도 합니다.\n앨런 가문의 관계자들은 철저한 내부 교육 지침만이 그녀를 어엿한 기사로 성장시킬 수 있었다고 평하지만, 아이러니하게도 같은 조디악 나이츠의 단원들은 견습생 시절의 그녀가 기사도 교육에 참여하는 모습을 단 한 번도 본적이 없었다고합니다.\n악의가 실려있을수록 무겁게 느껴진다는 천칭의 봉을 깃털처럼 가볍게 휘두르는 그녀의 모습을 보고 있자면, 그녀가 가진 기사도는 천부적인 본성에서 비롯된 것일지도 모릅니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_STREGA_YOO_NA"
L14_1 = "스트레가의 견습마녀, 유나 스프링필드는 집안의 유산인 마녀의 지팡이로 고화력의 마법을 준비하는 원거리 공격수입니다.\n돌아가신 할머니의 유지를 이어받아 마녀가 되기로 결심한 그녀는 무작정 가르침을 받기 위해 정식마녀를 찾아가 스승이 되어달라고 했으나, 어째서인지 제자 교육이란 명목으로 마녀의 카페 종업원 일을 떠맡게 됐습니다.\n청소면 청소, 요리면 요리, 무엇이든 맡기기만 하면 일단 기합을 잔뜩 넣고 시작하지만, 금세 제풀에 지쳐서 쓰러지고 마는 그녀는 의욕만 넘칠 뿐 매사에 진지해지는 법을 모릅니다.\n정식마녀가 되면 무얼 하고 싶으냐는 상담사의 질문에, 그건 정식마녀가 된 다음 생각해보겠다고 답하는 이 철부지 견습마녀의 앞날에 어떻게 많은 이들이 주목하고 있습니다.\n물론 대부분은 실패할 거라는 쪽에 돈을 걸었습니다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_STREGA_LAURA"
L15_1 = "라우라 베아트릭스는 고양이 사역마 플루토를 소환해서 적들이 둔하고 약해지도록 저주를 퍼붓는 방해형 지원가입니다.\n그녀는 카페 스트레가의 점장으로 자신이 컨셉이 아니라 진짜 마녀라고 주장을 펼치고 있습니다.\n운영 중인 카페에선 종업원들이 대놓고 마녀복장을 한 채로 돌아다니며 때론 일을 편하게 하려고 요술을 부리기도 하지만, 손님들은 그게 당연히 코스프레와 마술의 일종이라고 생각합니다. 심지어 그녀의 사역마는 불행을 점쳐주는 고양이란 이름으로 카페의 명물이 되었습니다.\n이렇듯 마녀의 존재를 믿지 않는 사람들에게 불만이 많던 라우라였지만, 생각보다 수익이 점점 좋아지자 최근엔 현실을 받아들이고 새로운 메뉴연구에 몰두 중입니다.\n마녀도 먹고는 살아야 하니, 돈을 벌고 싶어 하는 건 당연한 이치겠죠."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_STREGA_INGRID"
L16_1 = "마녀 잉그리드는 시간의 힘을 이용해 전장의 어디로든 출전할 수 있으며, 높은 회피와 공격속도를 가진 선봉대입니다.\n보통은 미지에 대한 호기심이나 흑마법의 어두운 매력에 심취해 오컬트에 입문하지만, 잉그리드는 남들보다 더 강해지고 싶다는 목적을 갖고 마녀의 길을 선택한 괴짜 승부사입니다.\n넘치는 호승심을 주체하지 못해 언제나 자신보다 강한 상대를 찾아 다니는 그녀가 어울리지 않게 카페의 종업원으로 일하게 된 것도, 가장 강하다는 마녀를 찾아내서 무작정 결투를 신청했다가 처참하게 패배한 뒤 가게를 망가뜨린 빚을 갚겠다는 계약서를 썼기 때문입니다.\n편하게 일하면 몸이 게을러진다는 관념 때문에 물구나무서서 서빙하기 등의 기행을 자주 펼쳐 점장의 주먹을 부르곤 하지만, 오히려 그런 희한한 광경을 보기 위해 일부러 카페를 찾아오는 손님도 적지 않습니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_STREGA_EVELYN"
L17_1 = "마녀 에블린은 빗자루를 타고 날아다니면서 물약으로 아군을 회복시키고 적에겐 지속적인 피해를 주는 회복형 지원가입니다.\n그녀는 마녀카페 스트레가에서 커피담당, 디저트담당, 회계담당을 맡고 있으며 사람의 마음을 움직이는 비법을 알고 있기 때문에 지금의 단골들을 만드는데 가장 큰 기여를 했습니다.\n그런 다재다능한 그녀를 점장인 라우라가 마냥 믿고 맡기지 못하는 건, 그녀가 한눈만 팔았다 하면 음료에 자신이 연구 중인 약물을 타서 손님을 상대로 임상시험을 하기 때문입니다.\n실제로도 종업원이 커피에 이상한 걸 타는 것 같다는 신고가 간혹 접수되긴 하지만, 아직까진 카페를 들르고 나서 원하던 사랑이 이뤄졌다거나 건강이 회복됐다는 긍정적인 평이 대다수이기에 큰 문제는 되고 있지 않습니다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_ROI"
L18_1 = "로이 버넷은 쇠사슬에서 발생시킨 고중력으로 적의 방어를 무너뜨리는 선봉대입니다.\n많고 많은 몰락귀족 출신인 그는 한물 간 불량배 패션과 삐딱한 행동거지 덕분에 웨스트엔드의 명물로 알려져 있습니다.\n아버지가 저지른 바보짓 때문에 프리드웬에 팔려오다시피 해서 신참 요원이 되었는데, 첩보원 같은 일은 제 성미에 도통 맞지 않는 모양입니다.\n수틀리면 주먹부터 지르고 보지만, 그 상대는 평범한 시민들이 분을 삭이며 두고봐야 하는 범죄자나 힘을 믿고 제멋대로 구는 망나니로 국한됩니다. 혼자 있을 때는 차가 다니지 않는 횡단보도에서도 파란불을 기다리는 모범시민이라는 믿기 어려운 소문이 있습니다."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_ELIZABETH"
L19_1 = "엘리자베스 팬드래건은 자유롭게 전장을 누비며 광역 공격을 가하는 공격수입니다.\n프리드웬은 예로부터 소문만 무성한 첩보 기관입니다. 외부에 유포된 이야기 중 진실이 있다면, 프리드웬의 기관장이 대대로 팬드래건이란 성씨를 사용해 왔다는 것 하나뿐입니다.\n명가의 여식인 엘리자베스는 왕실과 국민을 위해 안온한 삶을 버린 노블레스 오블리주의 표본입니다. 이면세계에서 유입된 아티팩트를 처리하는 일은 그리 고상하지 않지만, 귀족답게 업무 중에 맞닥뜨리는 온갖 난제를 우아하게 해결해 냅니다. 그 방식이 근거 없는 자신감에 기반한 것처럼 보이는 것이 흠이라면 흠으로, 기관원들은 이 콧대 높은 아가씨를 예쁜 홍차 폭탄쯤으로 취급하고 있습니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_RYAN"
L20_1 = "수비수인 라이언은 수시로 위치를 바꿔 가며 자신에게 오는 공격을 비껴 보내고, 매서운 철권으로 적을 소탕합니다.\n특수부대 출신인 그는 프리드웬에 온 첫날부터 기관장에게 시대에 뒤떨어진 시설과 장비를 교체해야 한다고 직언해서 집사라는 별명으로 통하게 되었습니다.\n별명에 걸맞게, 직무를 소홀히 하는 기관원들은 정중한 방법으로 계도해 주고 있습니다.\n침식체도 일격에 분쇄하는 철권 앞에 많은 기관원들이 모범적인 근무 태도를 체득했지만, 기관장을 비롯한 카운터 일동은 틈만 나면 문젯거리를 가져 와서 그의 강철 같은 영혼을 시험에 들게 하고 있습니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_THADDEUS"
L21_1 = "새디어스 모건은 후방의 적을 기습하는 데 능숙한 공격수입니다.\n시대가 발전할수록 정보의 가치는 나날이 커지기 마련이며, 특히 프리드웬처럼 어디 있는지 모를 아티팩트를 추격하는 조직에게는 더욱 그렇습니다.\n과거 조국을 위해 활약했던 첩보원인 새디어스 모건은 이제 그 능력을 프리드웬에서 발휘하고 있습니다.\n그의 행보는 최근 공식석상에 스스로 모습을 드러내기 전까지 각국 유수의 정보기관들조차 사망했다고 오해했을 만큼 은밀합니다. 어째서 자신의 생존을 공개했는지는 알 수 없지만, 한 번이라도 새디어스와 함께일해 본 이들은 멋모르고 달려들 과거의 적수들에게 호된 교훈을 주기 위해서가 아닐까 짐작합니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_JIA"
L22_1 = "알파트릭스 이노베이션의 리더인 신지아는 실체가 있는 분신을 불러내 함께 싸우는 공격수입니다.\n그녀는 알파트릭스 그룹 총수의 손녀로, 어릴 때부터 기묘한 천재성을 드러냈습니다. 어떤 분야에서든 남들이 어려워하는 일을 쉽게 해내는 모습은 시간이 지날수록 찬사보다 기피의 대상이 되었습니다.\n애석하게도 사람 사귀는 일에서만큼은 그 재능이 통하지 않았습니다.\n외톨이인 그녀는 총수 사후에 벌어진 경영권 분쟁 속에서 태스크포스 업계로 내몰렸습니다. 형제 자매들은 지아가 어느 이면세계에서 죽어 주길 바랐겠지만, 애석하게도 그 기묘한 천재성은 대 침식전에서도 유감없이 발휘되고 있습니다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_CHOWON"
L23_1 = "알파트릭스 이노베이션 소속의 김초원은 지급 받은 무기에 탑재된 기능을 빠르게 재사용하면서 교전하는 저격수입니다.\n그녀는 사칙연산보다 침식체 사냥법을 먼저 배운 역전의 용병입니다. 사회 바깥에서 오랫동안 비인가 조직들의 채굴 활동을 돕다 보니, 이면세계에 머문 시간이 지금껏 살아온 시간의 절반을 넘습니다. 그러는 동안 온갖 험한 꼴을 겪었기 때문인지, 리더의 터무니없는 작전 개요에도 선뜻 따라 줍니다.\n기업 이미지 관리의 일환으로 학교에 다니고 있지만, 또래들과는 세상 보는 관점이 전혀 달라서 적응에 어려움이 많습니다. 무엇보다 학교에 난입해 소란을 피우던 카운터 범죄자를 맨손으로 제압한 뒤로는 주위의 대우가 노골적으로 정중해졌다고 합니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_CHOI"
L24_1 = "가브리엘 준 더 비셔스 브레이커는 제자리에서 움직이지 않는 독특한 검술로 아군의 회피 능력을 강화시키는 파수꾼입니다.\n세계를 방랑하며 배운 어떤 검술도 성에 차지 않았던 그는 불과 한 달만에 자신에게 어울리는 새로운 검술을 창안했습니다. 사방에서 적이 몰려와도 상대할 수 있게 만들어진 그의 「부동검법」은 지금껏 자신만이 완벽하게 터득했습니다.\n현재 그는 검술을 창안하는 과정에서 깨달은 세상의 균형을 수호하기 위해 파사의 심판자로 활동 중입니다.\n※ 이상의 서술은 교차 검증이 되지 않은 조사 대상의 주장임을 알려드립니다."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_LEEJIN"
L25_1 = "이진은 자기가 안전하다고 착각한 후의 적부터 불태우는 지원가입니다.\n맹렬하게 타오르는 그녀의 불꽃은 적의 사기를 꺾어 공격속도를 감소시킵니다.\n이진은 그룹 총수 집안의 비서로, 장차 요직에 오를 것이 확실시되던 요인이었습니다. 그러나 불행히도 경영권 분쟁 속에서 카운터라는 점이 빌미로 잡히는 바람에 새로 만들어진 프로모션 팀으로 좌천되었습니다.\n괴짜 혹은 사고뭉치들뿐인 팀에서 이진은 초심으로 돌아가, 리더의 완전무결한 보좌관 역할을 이행하는 데 최선을 다하고 있습니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_SEAROM"
L26_1 = "「가면 카운터」라는 특촬물의 열렬한 팬인 오새롬은 기선 제압과 속전속결에 능한 선봉대입니다.\n오새롬의 꿈은 가면 카운터처럼 악당을 쓰러뜨리는 카운터가 되는 것입니다.\n그녀는 멋진 동료들이 있으면 좋겠다는 생각에 집안의 반대도 무릅쓰고 알파트릭스 이노베이션에 지원했습니다.\n물론 현실에는 반드시 쓰러뜨러야 할 악당들이 떡하니 나타나 주지 않기 때문에, 아직까지는 사람들을 위협하는 침식체를 무찌르는 선에서 그치고 있습니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FRONTIER_NINA"
L27_1 = "니나 앤더슨은 유연한 신체로 테크니컬한 전투를 벌이는 선봉대이자, 제 6 난민지구 출신 용병들이 모인 프론티어의 리더입니다.\n스트리트 댄스 그룹에서 공연으로 생계를 잇던 그녀는 추위에 쓰러진 노숙자를 도운 대가로 낡은 시계 하나를 얻었습니다. 그것이 워치라는 사실을 알아차린 것은 고향에서 침식 재난이 일어났을 때였습니다.\n카운터로 각성한 니나는 가난을 청산하기 위해 용병이 되었습니다. 고향 이야기는 아무에게도 꺼내지 않지만, 주변인들은 혼자서 예전에 구상한 안무를 연습하는 모습을 본 적이 여러 번 된다고 말합니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FRONTIER_MAYA"
L28_1 = "대전차 화기와 저격수는 어울리지 않는 궁합 같지만, 마야 헌트는 예외입니다.\n마야 헌트가 워치를 잡은 계기는 더 멋진 폭발을 일으키고 싶다는 소망입니다. 폭발의 규모, 폭발음의 데시벨, 불꽃의 색상은 그녀의 컨디션에 큰 영향을 끼칩니다.\n이 폭발광은 어느날 갑자기 난민지구에 나타나 갱단들을 공격했습니다. 보복에 나선 단원들은 압도적인 화력에 굴복했고, 처음엔 환호하던 주민들마저 나중에는 갱단보다 끔찍한 소음에 괴로워했습니다.\n다행히 프론티어에 영입되면서, 그녀는 자신의 충동을 마음껏 발산할 기회를 얻었습니다. 침식지대에선 아무도 폭발로 불평하지 않기 때문입니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FRONTIER_LEE"
L29_1 = "리 더포는 다수의 적을 상대하는 데 우수한 수비수입니다.\n워치에서 나타난 철갑으로 감싼 오른팔은 그의 방패이자 흉기입니다.\n한때 복싱 유망주였던 그는 갱단의 계획적인 린치에 오른팔을 잃고 카운터로 각성했습니다.\n비록 선수의 꿈은 잃었지만, 새로운 목표를 가지고 프론티어에서 활동 중입니다. 리는 고향에 병원을 지어 자기 같은 피해자가 나오는 걸 막으려고 합니다. 프론티어가 아직 영세한 용병단이란 사실은 문제가 되지 않습니다. 어둡고 낡은 체육관에서도 선수의 꿈을 키웠는데, 든든한 새 팔까지 얻은 지금이라면 뭐든 가능하기 때문입니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_HYUNSOO"
L30_1 = "박현수는 데이마인 채굴 4팀의 팀장으로, 동일 직군과 호흡을 맞춰 싸우는 데 능숙한 선봉대입니다.\n그는 원래 검을 휘두르는 것보단 보고서를 쓰는데 익숙한 현장보조직이었지만, 경기불황과 잦은 구조조정으로부터 살아남기 위해 직접 전투에 기여하기 시작했습니다.\n카운터가 되기 전, 과로로 사경을 헤매본 경험 때문에 팀원들에겐 언제나 정시출퇴근을 권장하며 잔업이 남았을 땐 자신이 모든 책임을 떠안는 편입니다.\n한때는 일이 좋아서, 또 한때는 승진을 위해서 부단히 노력하던 그였지만, 지금은 자신만 믿고 있는 부하직원들을 위해 자릴 지키고 있습니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_GANGSAN"
L31_1 = "최강산은 운동을 사랑하는 남다른 체격의 호청년으로, 적을 도발하고 아군을 지키는 수비수입니다.\n전경시절의 영향을 받아 워치로 구현된 그의 전용방패는 단순한 시위진압용 방패처럼 보이나, 실제론 이터니움 합금보다도 튼튼한 강도를 자랑합니다.\n산책 중인 치와와나 방역차의 연기처럼 일상의 사소한 요소에도 일일이 경계를 세우는 그의 예민한 성격은 살짝 부담스럽긴 하지만, 인명을 구하기 위해서라면 자기 몸도 사리지 않는 정의로운 인물입니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_SOMI"
L32_1 = "데이마인의 열정적인 신입사원, 심소미는 적들의 공격능력을 저하시키는 방해형 지원가입니다.\n콜센터에 근무하던 시절, 이달의 미소상을 한 번도 놓친 적이 없는 그녀는 업종을 태스크포스로 전향한 이후에도 항상 밝은 미소를 잃지 않고 있습니다.\n미숙함 때문에 팀장에게 잦은 꾸중을 듣곤 하지만, 악성고객들로부터 갖은 고초를 겪어봤던 전직 모범상담원은 잠시 주눅들 뿐 금세 털어내고 다시 분발을 위해 노력합니다.\n하지만 그런 열정에 비해 그녀의 목표는 지극히 단순하게도, 집안의 자랑스런 딸이 되고 싶다는 것입니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_ZENA"
L33_1 = "오피셜 서포트의 소대장 제나 버드는 부족한 기본 능력을 기량으로 보충하는 대기만성형 선봉대에 속합니다.\n한 학급의 부반장이었던 제나는 졸업여행지에서 침식 재난에 휘말렸다가 친구들을 지키겠다는 일념으로 워치를 잡았습니다. 위기를 벗어난 이후, 그녀는 자신이 얻은 힘으로 더 많은 사람들을 돕기 위해 오피셜 서포트에 지원했습니다.\n카운터로서도, 지휘관으로서도 미숙한데도 소대장을 맡은 까닭은 귀찮은 책임을 짊어지려는 지원자가 없었기 때문입니다.\n하지만 제나는 부담감에 시달리면서도 자신의 소임에 걸맞은 사람이 되기 위해 오늘도 노력 중입니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_CATHY"
L34_1 = "캐시 웨이드는 국지적인 대기현상을 조작해서 광역 공격을 가하는 공격수입니다.\n그녀는 과거 한 타블로이드지에서 선정적인 기사를 주로 쓰던 기자였습니다. 새 기삿거리를 찾다가 급진적인 환경 단체와 정치권의 유착 관계를 폭로하는 공을 세웠지만, 이를 못마땅하게 여긴 모 조직의 표적이 되고 말았습니다.\n현재 그녀는 계속되는 위협을 피해 관리국의 비호 아래에 들어가 있습니다. 경험이 부족한 소대장을 도와 주며 조용히 지내는 것 같지만, 조사 결과 태스크 플래닛의 특집 기사들 중 상당수는 그녀가 취재한 내용으로 확인되었습니다."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_IRIE"
L35_1 = "재미난 일을 찾아 오피셜 서포트에 지원한 아이리 알포드는 적을 정신없이 밀치고, 넘어뜨려서 접근하지 못하게 하는 수비수입니다.\n아이리의 하루는 장난으로 시작해서 장난으로 끝납니다. 그 장난이 회의실 입구에 설치된 바나나 껍질로 그칠지, 구내 식당 메뉴를 아이스크림 케이크로 통일하는 데에서 그칠지는 오직 그녀 자신만 알고 있습니다.\n그럼에도 지금까지 파견지들에서 받은 성적이 나쁘지 않은 이유는 두 가지입니다. 하나는 그녀의 장난기가 침식체 상대로도 예외 없이 발휘되기 때문이고, 다른 하나는 아이스크림을 다 먹을 동안에는 얌전해서입니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ORCA_EDDIE"
L36_1 = "에디 피셔는 동료 용병들의 능력을 적재적소에 활용하는 공격수입니다.\n업계에서는 「협상가」란 별명으로 더 많이 알려진 인물입니다. 이 별명은 갖은 핑계로 보수를 깎는 악질 고용주들에게서 매번 정당한 대가를 챙겨 가는 모습에서 비롯되었습니다. 고용주들에겐 분통 터질 노릇이지만, 맡은 의뢰는 확실히 해내기 때문에 그를 찾는 곳은 끊이지 않습니다.\n에디의 무기는 총과 폭탄이 아니라 유들유들한 언변과 상황을 냉정하게 보는 판단력입니다. 특히 푼돈에 욕심내다 목숨을 잃는 업계 신참들에게 생존법을 가르쳐 주는 데에는 이만한 현장 교사가 없습니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ORCA_JESSICA"
L37_1 = "제시카 그린은 산탄총으로 근접한 적을 밀어내고 설치형 폭발물을 다루는 선봉대입니다.\n커다란 농장을 꾸리는 집안에서 자란 그녀는 보수적인 집안 분위기와 따분한 시골 생활에 늘 염증을 느껴 왔습니다. 결국 고등학교 졸업식 날 고향을 떠난 뒤로는 가족들과 연락 한 번 하지 않고 세계 각지를 돌아다니며 용병으로 활동 중입니다.\n전문적인 교육은 받지 않았지만, 각종 농기계와 비료를 다루던 경험을 바탕으로 폭발물 사용에 상당한 조예를 갖췄습니다.\n그녀의 유일한 단점은 끓는 점이 낮다는 것으로, 한 번 욱하면 중견 용병들도 기겁할 만큼 거친 말이 쏟아져 나온다고 합니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ORCA_CHARLIE"
L38_1 = "찰리 록우드는 적의 공격을 견디다가 경기관총으로 강력한 반격을 가하는 수비수입니다.\n찰리는 어느 술집에 가면 한 명쯤 있을 법한 수다스러운 용병입니다. 대학 시절에 삼류 미식축구 선수였던 그는 어느날 술집에서 술친구가 된 용병의 모험담을 듣고 그 길로 곧장 기숙사를 뛰쳐나왔습니다. 다행히 고된 트레이닝과 집단 행동을 소화해 낸 찰리에겐 미식축구보다 용병이 적성에 맞은 모양입니다.\n날마다 어디선가 허무맹랑한 돈벌이를 주워듣고 오며, 이미 셀 수 없이 허탕을 쳤습니다. 그럼에도 대박의 꿈은 여전한데, 이는 현장에서 겁먹은 모습을 보이지 않는 면과 관련 있어 보입니다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_LEE_SUYEON"
L39_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n이수연은 높은 체력과 광역 제압 기술로 적의 방어를 무너뜨리는 선봉대입니다.\n스승인 힐데를 맹목적으로 따르는 전대원으로, 가르침에 부응하기 위해 자기 한계를 넘어선 기술을 익히기도 했습니다. 이 기술의 명칭은 본래 아토믹 힐데 퍼니시먼트로 정했다가 당사자의 완강한 거부로 지금과 같이 변경되었습니다.\n실력은 의심의 여지가 없지만, 출격과 적진 한복판에 뛰어드는 행동을 동일하다고 여기기 때문에 상관의 꾸준한 지도와 통솔이 필요합니다. 이에 대해 전대장은 방목이 최선이라고 언급했습니다."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_NA_YUBIN"
L40_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n나유빈은 펜릴 전대의 후방 화력 지원을 전담하는 공격수입니다.\n보통은 관제 임무를 수행하지만, 전투 중엔 강력한 광역 공격으로 전황을 바꿉니다.\n그는 현장 요원으로는 드물게 높은 수준의 대국적인 안목을 갖추고 있습니다.\n항상 전투 이후를 염두에 두고 움직이기 때문에 동료 전대원으로부터 또 딴생각을 하냐는 핀잔을 자주 듣습니다.\n함께 일한 여러 부대로부터 지휘관 양성 과정을 제의 받았지만, 나유빈은 아직 펜릴 전대에서 배워야 할 부분이 많다는 이유로 사양하고 있습니다. 이에 대해 전대장은 교과서적인 방법론에서 벗어나는 것이 우선이라고 언급했습니다."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ADMIN_SWORD"
L41_1 = "높은 회피와 치명률을 가진 선봉대입니다.\n소문만 무성한 구 관리국의 전투 요원으로, 백병전에서 카운터를 보조할 목적으로 양성되었습니다. 모두 생김새가 같은 건 우연이 아닐 겁니다."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ADMIN_RIFLE"
L42_1 = "공격할수록 공격력이 점점 상승하는 공격수입니다.\n구 관리국의 주요 전력. 이들의 제식소총은 보병용 유탄을 상회하는 위력을 발휘하는 것으로 보입니다. 강화복을 착용하고 일상생활이 가능합니다."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ADMIN_SHIELD"
L43_1 = "체력이 낮아졌을 때 배리어를 생성하는 수비수입니다.\n구 관리국의 주요 전력. 중장형 강화복으로 중장비를 능가하는 완력을 발휘합니다.\n그 우수한 방호성 때문에 일선의 지휘관들도 애용했다고 합니다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_ADMIN_MACHINEGUN"
L44_1 = "이동 없이 연사를 유지할 때 강해지는 선봉대입니다.\n구 관리국의 돌파용 기갑병기. 지속 화력을 투사하여 침식체를 무력화시킵니다.\n전용 포신은 예비 수량이 부족하므로 운용에 신중을 기해야 합니다."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_ADMIN_TANK"
L45_1 = "범위 공격을 하며, 출격 시 일정시간 강화되는 공격수입니다.\n구 관리국의 저지용 기갑병기. 고출력 광선포로 대형 침식체를 침묵시킵니다. 탑재된 레이저 모듈은 관리국 주관 하에 각국 방산업체가 연구 중입니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_ADMIN_CANNON"
L46_1 = "초장거리 포격에 특화되어 있으며 전선에 오래 머무를수록 화력이 높아지는 저격수입니다.\n구 관리국의 최종 방어 병기. 초장거리에서 가공할 화력으로 목표를 파괴합니다.\n155mm 입자포는 이론상 4종 침식체 상대로도 효과적입니다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_HB_CHOIENA"
L47_1 = "직접 싸우지 않는 대신 아군 한 명을 대폭 강화해서 스포트라이트가 향하게 만드는 파수꾼입니다.\n최이나는 아직 아이돌이라는 말이 입에 더 익숙한 경영인입니다. 비주류 인플루언서들을 모은 MCN인 내일 엔터테인먼트의 대표로, 프로젝트 하트 베리를 성공시키기 위해 현장에서 매니저 역할을 겸하고 있습니다.\n호칭에 매우 민감해서 자기를 여사님이라고 부른 시청자는 사정없이 채팅 금지를 먹입니다.\n연예계에서는 대표적인 워커홀릭 매니저였습니다. 창업한 계기는 일감 좀 적당히 가져 오라고 말리는 상사와의 불화였는데, 지금은 「귀여운 미소녀 카운터들의 좌충우돌 일상」을 모토로 하트 베리를 매우 알차게 굴리고 있습니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_GAEUN"
L48_1 = "가은은 연쇄 피해를 주는 기술로 모여 있는 적을 단숨에 쓰러뜨리는 공격수입니다.\n하트 베리의 리더 가은은 20년 전부터 내전 중인 나라에서 태어났습니다.\n빵 한 조각에도 목숨을 거는 삶에 익숙해져 갈 즈음, 얼굴도 모르는 은인의 도움으로 세상에 나올 수 있었습니다.\n가은은 자신의 은인─선생님과 다시 만나길 소원합니다. 인터넷 방송이 뭔지 모르면서 하트 베리에 합류한 계기도 바로 「유명해지면 선생님도 널 알아 볼 것」이라는 최이나의 설득 때문이었습니다.\n첫 방송 내내 아무 멘트도 하지 않아 멤버들을 당황케 했으나, 클로징 때 선생님을 떠올려 보라는 최이나의 지시를 받고 지은 미소가 무수한 팬들을 양산했습니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_RUMI"
L49_1 = "하트 베리의 차기 리더를 자칭하는 루미는, 적진을 빠르게 주파해서 핵심 목표를 공격하는 공성대입니다.\n평범한 중산층 출신이면서 코흘리개 때부터 셀럽이 되길 꿈꾸었는데, 어떤 분야에서든 그 옆에는 항상 자기보다 더 빛나는 사람이 있었습니다. 들러리 신세에 넌더리가 난 그녀는 카운터가 되자마자 하트 베리에 자원했습니다. 물론 최고가 되겠다는 야망은 가은이 합류하는 바람에 물거품이 되고 말았습니다.\n시청자들의 관심을 끌 수만 있다면 침식체 군집 속으로도 기꺼이 뛰어들며, 특히 적의 우두머리가 보이면 앞뒤 안 가리고 돌격하고 맙니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_MIYA"
L50_1 = "미야는 공격을 계속할수록 사기충천해서 실력 이상의 성과를 거두는 저격수입니다.\n편집 겸 스트리밍 담당으로, 항상 멤버들의 활약상을 절묘하게 캐치해 줍니다.\n본래 그녀는 낯을 심하게 가려서 혼자 편집 일을 하며 외톨이로 지냈습니다. 그러다 우연한 계기로 방송에 출연한 뒤, 자기를 좋아해 준 소수의 시청자들을 위해 넷튜브 방송을 시작했습니다.\n게임은 젬병에 저격 솜씨도 형편없지만, 잠잘 때 말곤 항상 방송을 틀어서 고정 팬이 많습니다. 초반에는 한 덩치 해서 미고래라고 놀림 받았지만, 방송 강행군으로 체중이 급격히 줄어들어 팬들은 기뻐하는 중입니다.\n시작 멘트인 부장님 유머와 클로징용 자작 노래는 악평 일색으로, 본인은 꿋꿋이 밀고 있습니다."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_BOMI"
L51_1 = "하트 베리의 선봉대인 보미는 도발 능력이 있는 분신으로 적을 농락합니다.\n보미는 몇 년 전까지만 해도 대형 기획사가 내놓은 아이돌 그룹의 일원이었습니다. 하지만 춤출 때를 빼면 꾸벅꾸벅 졸기만 해서, 아이돌 혹사 루머에 시달리던 기획사의 간청으로 그룹을 떠나게 되었습니다.\n본인은 꿈속에서 만든 새로운 안무를 뽐내고 싶어하는데, 정작 미야가 찍은 잠꼬대가 방송을 탄 이후로는 춤 방송보다 잠 방송이 더 인기 있습니다. 넷튜브 통계에 따르면, 하트 베리가 받는 도네이션 중 83%는 보미가 잠들어 있을 때 터집니다."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SOF_JOHN"
L52_1 = "커스텀 드론을 대동하고 싸우면서 아군 기갑 병기를 강화시켜 주는 공격수입니다.\n존 메이슨은 용병들 중 드물게 공학 박사 학위를, 그것도 교수 임용을 권유 받을 만큼 눈 깜짝할 사이에 성취했습니다.\n두뇌파 용병이라는 입버릇도 허언은 아닌 셈입니다.\n그는 자신이 직접 개발한 첨단 장비를 착용하고 홀로 현장을 누빕니다. 일찍이 경험 많은 베테랑에게 돈 문제로 파토가 나기 일쑤인 업계 사정을 배웠는지, 1인 용병 사무소를 고집하고 있는 상태입니다.\n그러나 정작 전용 장비를 만들 때 값비싼 소재만 고집하는 탓에 그의 사무소는 설립 이래 한 번도 흑자를 낸 적이 없습니다."
L50_1[1] = L51_1
