L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SOF_JANE"
L3_1 = "제인 도우는 높은 회피 능력으로 전장에 머무르면서 광역 공격을 가하는 선봉대입니다.\n제인 도우는 영어권에서 신원 미상의 여성을 의미하는 이름이면서 이 여성의 가명이기도 합니다. 본명은 물론 나이와 출신까지 무엇 하나 알려진 적 없는 용병으로, 죽을 위기가 닥쳐도 늘 미소 뒤에 진의를 감추고 있습니다.\n서면으로 그녀에 대해 알 수 있는 사실은 사람 잡는 솜씨가 일류라는 것뿐입니다.\n메이슨 용병 사무소의 이름을 빌리고 있다지만, 이름만 들어도 대표가 치를 떠는 걸로 봐선 일방적인 대여로 추측됩니다."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_HOGSBACK_TOM"
L4_1 = "토미 더 다이하드는 어디든 제압병인 제리, 그리고 소총병인 미키를 끌고 나오는 수비수입니다.\n이 3인조는 업계에서 흔히 보이는 허풍 심한 용병들입니다. 뭉치면 살고 흩어지면 죽는다는 각오 없이, 동네 친구들처럼 술집에서 의기투합해 뭉쳐 다니며 실력은 그저 그렇습니다.\n자기들의 전적을 과장해서 몸값을 부풀리려 하지만, 아직까지 먼저 고용주의 뒤통수를 때린 적이 없다는 점만큼은 다른 용병들보다 약간 나은 편입니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_YG_HARIM"
L5_1 = "양하림은 유기동물을 구조하는 화이트래빗 동아리의 대장으로, 용감한 세 마리의 동물 친구들과 함께 팀원을 지원하는 지원형 카운터입니다.\n관리국에서 지급하는 카운터 지원금을 몽땅 사료값에 쏟아 붓고, 홀로 하수도에 뛰어들어 동물의 울음소릴 쫓아다닐 정도로 동물사랑이 지극합니다. 그녀는 언젠가 주인 없는 동물들이 마음껏 뛰어 놀 수 있는 넓은 목장을 갖는 게 꿈입니다.\n어린 나이에 학교공부와 동물구조를 겸한다는 것이 쉬운 일은 아닐 테지만, 그녀는 오늘도 어김 없이 방과 후 동아리 활동에 나섭니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_YG_SORIM"
L6_1 = "한소림은 전투에 적응할수록 공격속도가 빨라지는 전천후 원거리 딜러입니다.\n동물구조대 화이트래빗의 부대장으로, 운동을 극도로 기피하나, 학습능력만큼은 월등히 뛰어나 어깨너머로 배운 지식만으로 첫 모의훈련에서 병기구 활용능력과 사격 부문에서 병사들 평균을 웃도는 뛰어난 성적을 거뒀습니다.\n팀 리더인 양하림을 대장이라 부르며 따르는 이 학생은 만화 등의 대중 매체를 통해 밀리터리의 마니아가 되었습니다.\n자신이 군인이라는 착각에 빠져 살고 있지만, 긴장하게 되면 소극적인 여자아이의 모습으로 돌아오곤 합니다.\n좋아하는 것에 매진하는 천재이기 때문에 향후의 비전이 밝을 것으로 기대됩니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_YG_HOJIN"
L7_1 = "조호진은 낮은 전투 능력을 행운으로 커버하는 치명 특화 전천후 원거리 딜러입니다.\n곤경에 처해 있으면 두고보지 못하는 타입이라, 그 결과 동물구조대인 화이트래빗과 인연이 닿아, 학업과 구조활동을 병행하는 중 입니다.\n화이트래빗에선 간식담당과 칠칠치 못한 맏언니 역할을 맡고 있습니다.\n인명사고를 백 차례 넘게 막아냈을 정도로 실적은 뛰어난 인물이지만, 어째서 그녀를 중심으로 그렇게나 잦은 사고가 일어나는지는 의문입니다.\n유년시절부터 워치를 얻었지만, 본인이 카운터라는 사실을 자각한 것은 불과 최근의 일입니다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_POLICE_SOYEONG"
L8_1 = "4기동대 소속 강소영은 범죄자를 경찰차로 들이받아 갱생시키는 지원형 원거리 공격수입니다.\n그녀는 카운터 범죄자들을 상대해야 하는 특수부서에서 일하고 있습니다. 순직률 1순위로 꼽히는 곳에서 누구보다 오랫동안 자릴 지켰고 그만큼 많은 사건을 해결해온 비결에는, 우수한 사격실력과 남다른 추리력도 있겠지만, 무엇보다 상식을 벗어난 과감함으로 범죄자들의 뒤통수를 치는 것이 그녀의 특기라고 할 수 있습니다.\n대부분은 왜 그녀가 우수한 실적을 거둠에도 버려진 부서에서 벗어나지 못하는 건지 이해하지 못하지만, 정작 본인은 자신의 처우에 대해 별로 개의치 않습니다.\n어쩌면 허구한 날 차로 모든 걸 때려부수는 탓에 청장의 미움을 받는 걸지도 모릅니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_POLICE_LEE_YUMI"
L9_1 = "4기동대 소속 이유미는 우수한 회피 능력으로 최전선을 누비고 다니는 수비수입니다.\n경찰 신분임에도 불구하고 범죄자에 대한 적개심이 강해서, 수갑 대신 다짜고짜 검을 휘두르곤 합니다.\n때문에 자주 매스컴의 도마 위에 오르곤 하지만, 압도적인 검거율과 경찰청 내의 유일한 카운터라는 점 때문에 상관들도 그녀를 함부로 나무라지 못합니다.\n동료경찰인 강소영 경위는 그녀가 철밥통이란 점을 이용해 은근슬쩍 책임을 떠넘기려고 하며, 그런 식으로 둘은 늘 티격태격하지만, 등을 돌렸다가도 범죄 앞에선 다시 하나로 뭉쳐 싸우는 애증의 관계입니다.\n사건현장을 오가는 바쁜 일상 때문인지, 일대의 제과점에선 그녀의 얼굴을 모르는 업주가 없습니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JOO_SHI_YOON_AP"
L10_1 = "주시영은 적의 기본 공격을 받아치면서 싸우는 트리키한 선봉대입니다. 또한 자신의 회피 능력을 강화해서 많은 적들과 뒤엉켜 싸우는 혼전 양상에 강세를 보입니다.\n「받은 만큼 일한다」를 모토로 삼은 프리랜서 용병으로, 본인이 프로페셔널 마인드의 표본이나 다름없다고 주장합니다.\n출중한 실력과는 별개로 업무를 벗어난 일에는 철저히 선을 긋고, 불필요한 싸움은 일절 무시하는 경향이 있습니다. 이 때문에 특별 관리를 위해 델타 세븐에서 가장 합리적인 인물이 책임자를 맡고 있는 패스파인더 별동대로 배정되었습니다.\n자신이 추억으로만 여기던 물건을 발견하면 금방 심취해 버려서, 임무를 우선시하는 별동대 책임자에게 곧잘 한소리씩 듣고는 합니다. "
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_KYLE_AP"
L11_1 = "카린 웡은 장거리 요격용 특수 화기를 사용해서 공중의 적에게도 효과적인 공격을 가하는 전천후 저격수입니다.\n델타 세븐의 내사과 소속이라는 그녀는 불완전한 카운터 양성 계획의 마지막 기수입니다. 카운터로서 지닌 분석 능력을 개발하는 실험적인 훈련도 우수한 성적으로 통과하여, 정교한 구조로 이루어진 시작형 특수 화기의 성능을 십분 발휘할 수 있게 되었습니다.\n본인이 주장하기로는 델타 세븐에서 가장 유망한 인재였으며 많은 어려운 작전을 성사시켜 왔다고 하지만, 면접실에 동석했던 동료의 표정을 보아 사실과 거리가 먼 것으로 추정됩니다.\n신기술에 민감하여 온갖 첨단 제품을 발견하면 값은 신경 쓰지 않고 손에 넣으려 하기 때문에, 최근 자금 마련에 고심 중이라고 합니다."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_SENHIME"
L12_1 = "나나하라 치후유는 당주의 안위를 지키는 호위무사로서 검술만으로 연합의 적을 격퇴하는 선봉대입니다.\n그녀가 사용하는 검술은 나나하라류라 불리는, 가문내에서도 특별히 선택된 자에게만 배움이 허락되던 검술입니다.\n현대의 고류 무술 전문가들은 그러한 이유가 단지 혈통 문제가 아니라 나나하라류가 카운터만 소화할 수 있는 검술이기 때문이라고 주장합니다.\n치후유는 D등급의 비전투 계열에 속하는 카운터지만, 나나하라류를 극한까지 연마함으로써 고등급 카운터와 대등한 전력으로 인정 받게 되었습니다.\n다만, 검술의 복원에 공을 들여온 가문 연합에선 그녀가 당주 개인을 비호하기 위해 연합의 검술을 사용한다는 사실에 불만을 갖고 있습니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_RYOHEI"
L13_1 = "나유카 미나토는 거리를 유지하면서 강력한 광역 피해를 주는 원거리 공격수입니다.\n나유카 가문은 나나하라를 필두로 조성된 가문 연합의 말석이자, 나나하라 가문의 까마득히 먼 방계입니다.\n그렇기 때문에 미나토 또한 가문 연합과 얽힌 여러 사건들로부터 동떨어진 채 평화로운 일상을 영위하고 있었습니다.\n하지만 조부에게 물려받은 낡은 시계 때문에 카운터로 각성해버리면서, 평범함과는 거리가 멀어져버리고 말았습니다.\n미나토는 자신이 얻은 힘에 사명감을 가지기 보다, 또래들처럼 용돈벌이 아르바이트나 하며 학교를 다니고 싶어합니다.\n현재 가문 연합은 새로운 당주를 선출하는 한편, 봉인 유지를 위한 조직 재건에 공을들이고 있습니다. 연합은 나나하라의 피를 이은 이 소년을 영입하려 할 테지만, 선택은 본인의 몫이겠죠."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_SETSUNA"
L14_1 = "가문의 어린 당주, 나나하라 치나츠는 치유의 기운이 깃든 바람으로 아군의 생존과 적의 격퇴를 동시에 도모하는 지원가입니다.\n전대 당주가 갑작스러운 병환으로 세상을 떠났을 때, 연합에서는 만장일치로 치나츠를 본가의 새로운 당주로 추대하였습니다. 가문의 시조가 지녔다던 바람의 목소리를 듣는 능력이 치나츠에게도 나타났기 때문입니다. 나나하라 가문은 미래를 알려 주고 사람의 마음을 헤아리는 이 신비로운 능력으로 과거의 번영을 이룩했다고 전해집니다.\n아직 힘을 사용하는 데에는 서툴지만, 그 잠재력과 위험성 탓에 치나츠는 가문 안팎으로 그녀를 이용하려는 자들에게 시달려 왔습니다. 그럼에도 치나츠는 당주로서 의연히 활동하는 한편, 이면세계에 맞서 온 가문의 전통을 되살리려 노력 중입니다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_ZENJIROU"
L15_1 = "오오가미 마사키는 자신의 혈맥에 흐르는 검은 불꽃을 통해 활약하는 수비수입니다.\n이 검은 불꽃은 강력한 범위 피해를 가하는 한편, 그 독특한 색채로 적들의 주의를 사로잡습니다.\n오오가미라는 성은 자칭이며, 가문 연합의 흑막으로 군림하겠다는 포부 아래 지었다고 합니다.\n오오가미 흑막조라는 공공연한 비밀 결사의 수장으로, 조직원은 현재까지 마사키 한 명뿐입니다. 흑막조의 대표적인 일과는 음험하게 웃는 연습하기, 어두운 곳에서 무게감 있게 앉아 있기, 모르면서 아는 척하기 등이 있습니다.\n현재 마사키는 흑막조의 새로운 조직원을 물색하고 있습니다. 가문 연합의 대부분은 그를 내놓은 자식으로 취급하지만, 카운터로서의 전투력을 감안하면 연합주 선출에 어떤 영향을 끼칠지는 미지수입니다. "
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_CHIHIRO"
L16_1 = "하야미 사나에는 아군의 후방에서 강력한 광역 포격을 지원하는 저격수입니다.\n하야미 가문은 과거 가문연합 방계 중 하나로, 연합에 큰 피해를 입힌 후 사라졌다고 알려져 있습니다. 그러나 당시 실종되었던 사나에는 몇 년이 지나 거대한 중화기─본인이 부르길 다리미를 짊어지고 다시 나타났으며, 현재는 가문 연합주의 묵인 아래 본가의 시녀로 일하는 중입니다.\n청소와 요리 등 가사는 물론 저택 관리에 이르기까지 집안의 모든 살림을 살뜰히 챙기고 있어서, 이제 그녀 없이는 본가가 제대로 돌아가지 않는다는 이야기도 심심치 않게 나옵니다.\n하지만 많은 이들은 사나에가 다시 한 번 가문연합에 누를 끼치진 않을지 경계하고 있습니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FALLEN_ROSARIA"
L17_1 = "로자리아 르 프리데는 공중에서 강력한 범위 공격을 가하는 전천후 원거리 공격수입니다.\n실종자 수색에 도가 튼 폴른 호크 탐정 사무소의 오너로, 의뢰를 위해 방문했던 사람들 중 상당수가 직원들을 하인처럼 부리는 모습을 목격한 바 있습니다. 본인의 표현을 빌리면, 이는 미물들에게 삶의 보람을 느끼도록 베풀어 주는 은혜라고 합니다.\n인간의 자기파멸적이고 불합리한 행동을 관찰하는 것이 취미로, 아침 드라마 감상에 푹 빠져 있습니다. 특히 살벌한 치정극으로 널리 알려진 「유혹의 함교」 시즌 6의 애청자이기도 합니다. 사건 조사에 직원들과 동행하는 경우도 있지만, 그때마다 항상 원인을 알 수 없는 국지적인 파괴가 발생한 바 있습니다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FALLEN_DOMA"
L18_1 = "프레데릭 도마는 적의 전투 능력을 봉쇄해서 천천히 고사시키는 원거리 공격수입니다.\n수상쩍은 탐정 사무소의 수상쩍은 접수원인 그는 의뢰를 위해 찾아온 방문객을 신사적인 화술로 구슬리는 데 매우 능숙합니다.\n다만, 본인의 지나치게 화려한 용모와 특유의 말투가 오히려 방문객을 경계하게 만든다는 것에 대한 자각은 없는 듯합니다.\n이처럼 비열해 보인다는 선입견을 주는 인상과 달리, 업계에서는 공정함을 추구하는 승부사로 널리 알려져 있습니다.\n같은 조건을 맞춰 주면서 자신을 가지고 논다는 느낌을 받는 것은 대결에 임하는 상대방뿐이지만요."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FALLEN_YUMA"
L19_1 = "프레데릭 유마는 적진으로 돌입해서 난전을 벌이는 데 특화된 선봉대입니다.\n탐정 사무소에선 배달음식 가격도 제대로 계산하지 못할 만큼 어리숙하지만, 주먹이 필요한 순간에는 누구보다 먼저 판에 뛰어드는 호전적인 싸움꾼 기질을 갖췄습니다.\n유마는 적이 강하든 약하든 가리지 않습니다. 덕분에 그녀가 자주 출몰하는 슬럼가의 갱단들은 신참들을 교육할 때 유마에게 트집 잡히지 않도록 눈이 마주치면 바로 고개 숙이는 법부터 가르치는 상황입니다.\n이렇게 남들에게는 언제 터질지 모르는 위험한 폭탄처럼 취급 받지만, 유독 남매인 도마의 상냥한 부탁 앞에서는 순한 강아지처럼 쩔쩔매는 약점이 있다고 합니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DELTA_KING"
L20_1 = "도미닉 킹 레지날드는 자신의 체력이 감소할수록 보다 뛰어난 전투력을 발휘하는 수비수입니다.\n레지날드 준장은 전쟁기에 안토노프 중장을 보좌했습니다. 대중들에게 널리 알려지지는 않았지만, 부대원들의 증언에 따르면 외골수 기질인 안토노프 중장에게 향했던 여러 정치적인 견제와 공격을 보이지 않는 곳에서 무마시켰던 인물입니다. 어떤 전쟁사 연구자들은 그가 부관이 아니었다면 안토노프 중장도 전선에서 오래 활동할 수는 없었다고 평합니다. 이는 비단 정치의 영역에만 국한된 이야기가 아니라, 실전으로 익힌 격투술을 통해 안토노프 중장의 오른팔로서 많은 무훈을 세우기도 했습니다.\n그 자신은 첫인상에서 느낄 수 있는 것처럼 강직한 군인입니다. 그러나 국제 연합군의 보고서에서는 지나치게 확고한 신념을 지녔기 때문에 새로운 문제를 야기할 수 있다고 우려하는 구절도 존재합니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_BALLISTA"
L21_1 = "발리스타는 자체적으로 생성한 보호막이 유지되는 동안 높은 공격력으로 전열의 적을 저지하는 파수꾼입니다.\n지상 투하를 전제로 개발된 전술형 이동 포탑이지만, 강력한 화력이 호평을 받아 함선의 방어 무장으로 쓰이는 모습도 흔히 보입니다.\n다소 실험적인 인공지능 인격을 탑재했기 때문에 유사시 감정적으로 돌변할 수 있습니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ESPR_SHADOW"
L22_1 = "에델 마이트너는 그림자 속에 도사리는 이형의 존재들을 사역해서 범위 공격을 가하는 저격수입니다. 이형의 존재들은 솔저와 침식체에게 특히 높은 피해를 가합니다.\n에크하르트 초월지식 학회의 신임 학회장이자 한계를 모르는 대식가로서, 침식체마저도 식재료로 취급합니다. 다른 사람들과 달리 그녀는 대 침식전을 즐거운 만찬 정도로 인식하는 모양입니다. 태스크포스의 대 침식전에 얼굴을 비추게 된 계기 역시 식단에 까탈스러운 차기 학회장을 피해서 허기를 채우기 위한 것으로 파악됐습니다.\n상식적으로는 이해하기 어려우나, 그녀의 식사는 생존을 위해서가 아닌 지식을 축적하기 위한 행위라고 합니다.\n카운터로 분류한 것은 행정적인 편의를 위함입니다. 그녀를 따르는 개체들이 무엇인지는 아직까지 확실히 밝혀진 바 없습니다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ESPR_PILE"
L23_1 = "리벳은 거대한 지원화기로 적을 공격하는 원거리 공격수입니다. 여러 격전지를 경험했을 만큼 생존력이 뛰어나면서, 카운터와 침식체도 능숙하게 상대합니다.\n언더그라운드에는 개인적 사정으로 떳떳하게 활동할 수 없는 실력자부터 독특한 정신세계를 가진 별종도 모여 있습니다. 그리고 리벳은 그 양극단을 모두 아우르는 무법자입니다.\n스릴을 만끽하기 위해 용병업에 뛰어들었다는 말처럼, 그녀가 주로 목격되던 곳은 고심도 이면세계나 강도 높은 분쟁지역이었습니다. 위기가 없으면 적을 끌어 들여서라도 만들기에, 언더그라운드에서는 신참들이 상종해서는 안 될 괴인으로 경계 받아 왔습니다.\n오랜 시간 종적을 감췄을 때도, 사람들은 분명 스스로 죽음을 자초한 게 분명하다고 여겼습니다.\n하지만 최근 그녀가 학회에 가담했다는 사실이 확인되었습니다. 이유는 불확실하지만, 가는 곳마다 위기를 초래하는 요주의 인물이므로 지속적인 관찰이 필요합니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ESPR_FROZEN"
L24_1 = "레지나 맥크레디는 얼음의 벽을 불러내 적의 공격 능력을 감소시키는 데 특화된 지원가입니다. 그녀가 일으키는 냉기는 메카닉 유닛을 상대로 더욱 뛰어난 효과를 발휘합니다.\n맥크레디 가문이 대물림해 온 워치는 냉기 조작에 특화되어 있습니다. 사용자에 따라서는 얼음을 만드는 수준에서 그치지 않고 국가적인 이상 기변도 야기합니다.\n문제는 현 소유자인 레지나가 워치에 깃든 강대한 힘을 제대로 다루지 못한다는 점입니다. 의식적으로 제어하지 않으면 자기 자신도 추위에 시달리기 때문에, 푹신한 담요와 커피가 좋은 선물이 될 것으로 보입니다.\n맥크레디 가문은 에크하르트 초월지식 학회의 학회장직을 역임해 왔던 집안이지만, 레지나는 전부터 이 전통을 달갑지 않게 여겼습니다. 어떻게든 워치를 제어하려고 애쓰게된 까닭은 그 힘으로 가문의 구습을 타파하기 위해서인지도 모릅니다.\n혹은 그저 추위를 타기 지긋지긋해서라거나."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CA_HILDE"
L25_1 = "테크 레벨 5의 버스터 코어를 장비한 힐데는 적을 밀어내며 보호막과 높은 방어능력으로 장기전을 버텨내는 수비수입니다.\n드래곤 버스터 레긴과 파프닐은 오로지 그녀가 가진 클리포트 인자의 힘을 견뎌내기 위해 만들어졌습니다.\n이들은 기록상 오랜 기간 동면상태에 머물러 있었으며, 최근에 벌어진 리플레이서와의 전투에서 재기동이 이루어졌습니다.\n이 한 쌍의 장비는 각각이 가속기능과 방출기능을 분담하고 있습니다. 그리고 두 개체가 짝을 이룰 때 성능이 가장 극대화되도록 설계되었습니다.\n이론상으론 출력에 한계가 없어서 무한대의 가능성을 품고 있긴 하지만, 오직 힐데가 가진 특수 인자만을 시동의 매개로 삼기 때문에 평범한 카운터에겐 그저 쇳덩어리나 마찬가지라고 합니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SIXWING_LEE_JISOO"
L26_1 = "이지수는 회복력 감소를 비롯한 여러가지 저주로 적을 방해하는 근접형 지원가입니다.\n육익이라는 단체의 일원으로, 좀처럼 모습을 드러내지 않는 다른 조직원들과 다르게 리더인 나유빈을 호위하는 모습이 자주 관찰됩니다.\n그녀는 칼 한 자루로 관리국의 경계망을 돌파한 적이 여러 차례 있는 위험인물입니다.\n카운터로서의 능력은 강력한 저주의 형태로 나타나며, 이 주술적인 힘을 검술과 접목시켜 적을 제압합니다.\n현재는 관공서에서 위장 신분으로 근무 중이나, 직원들에게는 원망의 대상입니다. 유능한 인재임이 분명한 그녀가 직무 적성을 의심 받는 점으로 보아, 의심을 피하기 위해 서 혼신을 다해 연기하는 것이 아닐지 의심됩니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SCHOOL_PRESIDENT"
L27_1 = "옌 싱 란체스터는 카운터 육성 아카데미의 총학생회 회장이자, 소도술을 이용해 적의 이로운 효과를 날려버리는 쾌검의 달인입니다.\n옌 싱은 아카데미 내에서 엄격한 선배로 알려져있지만, 사실 본인은 학생들 모두가 자신을 편한 친구로서 대해주길 원합니다.\n그녀를 감싼 엄중한 카리스마와 무게 잡힌 태도는 자라온 환경에서 비롯된 버릇일 뿐이며, 속내는 아이와 동물을 좋아하는 지극히 평범한 소녀일 뿐이란 것이죠.\n다만 교내에 떠도는 오해와 추측 사이에서도 그녀가 리더에 어울리는 뛰어난 성품을 가졌다는 이야긴 분명한 사실입니다. 전통무예의 대가로서 많은 재벌가 자녀들을 가르치며 모은 재산의 대부분을 아카데미와 사회에 환원하고 있으며, 어떤 학생도 편견으로 쉽게 차별하지 않는다는 게 그 증거죠.\n그녀는 서로의 다름을 받아들이는 것이 완벽한 조화를 이루는 데 있어 반드시 필요하다고 믿고 있습니다.\n개성 넘치는 현 학생회 임원들이 매일 같이 티격태격하면서도 지금껏 아카데미를 문제없이 잘 끌어온 걸 보면 그녀의 주장이 허울만 좋은 이상론은 아닌 것 같습니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SCHOOL_CHAIR"
L28_1 = "경호의자 J.O.U.R는 탑승자의 안락한 숙면을 보장하는 긴 사거리를 가진 파수꾼입니다.\n하지만 일정량의 피해를 받아 잠든 이디스 트윈즈가 깨어나게 될 경우 공중으로 날아오르며 매우 공격적으로 돌변합니다.\nJ.O.U.R의 설계자인 이디스 트윈즈는 아카데미 학생회 임원이자 최근 퓨처 앳 워에 소속된 명예 수석 연구원이기도 합니다.\n어릴 적 SF와 만화에 빠져 집안 가구를 멋대로 개조해오던 그녀는 어느덧 천재 공학자로 명성을 떨치게 되었습니다.\n하지만 주변의 기대가 커질수록 좋아하는 낮잠을 잘 수 없다는 현실에 부딪히게 되자, 그녀는 미뤄오던 아카데미 입학을 받아들이고 연구소를 떠나 D급 카운터 학생으로서의 삶을 살기로 결정했습니다.\n지금도 취미로 변신 로봇을 디자인하며 퓨처 앳 워를 돕고 있긴 하지만, 그녀가 낮잠을 포기하고 오로지 연구에 전념했더라면 우리의 삶은 지금보다 혁신적인 변화를 맞이했을 지도 모릅니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CA_YOO_MI_NA"
L29_1 = "클리포트 인자를 각성한 유미나는 제약이 있던 검을 자유롭게 휘두를 수 있게 된 강력한 선봉대입니다.\n리플레이서와의 결전 이후, 태스크포스 활동을 지속해오던 그녀는 우왕좌왕하던 신출내기에서 어느덧 대원들을 이끄는 능숙한 베테랑으로 성장했습니다.\n마음을 닫은 채 소속감 없이 행동하던 입사때와는 달리, 지금은 베테랑다운 면모와 호의적인 태도로 대원들의 신뢰와 지지를 얻고 있습니다.\n다만, 입사 이래 한 번도 자발적으로 휴가계를 쓰지 않았고, 매일 편의점에서 혼자 끼니를 때우는 등 지출에 민감한 성향은 예전과 다름없어 보입니다.\n그런 자신의 면모를 부끄러워 하는 경향이 있으므로 동전지갑에 대한 지적은 지양해주시기 바랍니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_HARPY"
L30_1 = "야누스는 공중에서 원거리 공격을 하다 일정 피해를 입으면 재니터 모드로 전환하여 지상 최전방에서 수비수 역할을 수행하는 가변형 전투기입니다.\n실험적인 기술로 유명한 퓨처 앳 워에서 개발한 최신예 변형 로봇의 프로토타입 모델이며, 그 이름이 세간에 알려지기 전에도 비밀리의 활동으로 실전 데이터를 축적해왔다는 소문이 있습니다.\n클라이언트들은 시연을 통해 야누스의 안정성이 입증되었다고 말하지만, 정작 개발을 주도한 연구원은 여전히 야누스의 완벽성을 부정하며 양산화를 반대하고 있다고 합니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_GREATSWORD"
L31_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n메이즈 전대의 부전대장 알렉스는 플라즈마 포의 포신을 개조한 대검으로 난투를 벌이는 선봉대입니다. 파동을 제어하는 능력으로 근접한 적에게 큰 피해를 입히며, 그 위력은 한계에 몰릴수록 강해집니다.\n관리국의 외부 적대세력이 만든 복제인간 중 하나로, 실패작 취급을 받아 버려졌다가 관리국에 구출되었습니다. 부족한 신체 능력 탓에 장거리 포격이 주 임무인 메이즈 전대에 배치됐지만, 무기의 출력을 자유자재로 조절하는 능력 활용법을 터득하면서 두각을 드러내기 시작했습니다.\n부대 임무에 부적합하다는 지적을 여러 차례 받았으나, 전대장의 강력한 요청과 비상시 근접전력의 필요성이 인정되어 잔류할 수 있었습니다.\n최악의 상황에서 대원들을 지킬 마지막 보루인 그녀는, 부대에서 높은 인망을 얻고 있습니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_ARTILLERY"
L32_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n류드밀라는 함포를 운용해 전천후 포격을 가하면서, 아군의 빈자리를 채워 주는 저격수입니다. 관리국에서도 보기 드문 강력한 염동력은 포화를 뚫고 접근하는 적들을 요격하는 데 빛을 발합니다.\n관제사를 지망했던 인물로, 본래는 피만 보면 졸도할 만큼 유약한 심성 때문에 함교 근무도 보류된 바 있습니다. 그러나 친우인 이수연의 권유 아닌 권유를 듣고 현장요원에 지원한 뒤에는 부대 운용 및 작전능력 방면에서 천부적인 소질을 지녔다는 사실이 드러났습니다.\n이례적으로 어린 나이부터 포격 전대 메이즈의 전대장직을 수행하기 시작했으며, 근접교전을 억제한 채 장거리 화력투사로 적을 분쇄하길 지향하는 전투 방식은 전대원뿐만 아니라 다른 부대에게도 지지를 받고 있습니다.\n전대원들이 꼽은 단점은 궤멸적인 손재주로, 직접 만든 액세서리를 선물로 받은 아이들이 울음을 터뜨렸다는 기록도 다수 존재합니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CA_ADMIN_LEE_SUYEON"
L33_1 = "새로운 장비와 함께 전선으로 복귀한 이수연은 공중의 적들을 휩쓸며 등장해 단신으로 상공을 장악하는 강력한 원거리 공격수입니다.\n그녀는 코핀 컴퍼니의 부사장으로 활동하며 S급 카운터로서 오랜 기간동안 평가가 부재되어 왔습니다.\n하지만 최근 비공식 출전을 통해 과거 실적을 월등히 뛰어넘는 기록을 세우면서 전성기가 계속되고 있음을 증명했습니다.\n복귀 이후에도 돈에 민감한 성향과 철저히 사무적인 태도는 여전하지만 전투에 임할 때만큼은 전장의 에이스다운 면모를 보여주며 타의 귀감이 되고 있습니다.\n그녀는 자신의 능력에 확고한 자부심을 갖고 있으나 어째서인지 과거 시절의 전투스타일에 대해선 설명을 꺼려합니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_RAS_TOWER"
L34_1 = "시그마는 특성 조작을 통해 클래스 간의 상성을 상쇄하거나 극대화해 아군을 지원하고, 출격 자원을 회복하는 지원형 파수꾼입니다.\n시그마는 관리국 기술의 산물이라고 알려져 있으나 그 정확한 정체는 불명입니다.\n나노 입자 홀로그램으로 이뤄진 육체를 통해 활동할 수 있으며, 타 기계의 취약점을 파악하고 방어하는 분야에선 최고의 성능을 발휘합니다.\n하지만 시그마의 성격은 오버 테크놀로지의 집약체다운 성능과는 다소 거리감이 있습니다.\n동화책에 이상하리만치 집착하며 타인에게 뽐내고 인정받는 걸 즐기는 성격은 기계라기보단 마치 어린아이를 닮아있습니다.\n다만 그녀의 순수하고 낯가림 없는 성격은 회사를 돌아다니며 낡은 기기를 고쳐주는 행동과 맞물려 직원들에게 오히려 좋은 인상을 심어주었습니다.\n사장님의 딸이라는 소문이 퍼진 뒤론 다들 대하기 어려워하고 있지만요."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CA_STREGA_YOO_NA"
L35_1 = "태양의 마도서, 솔라 코덱스의 힘을 받아들인 유나 스프링필드는 화염 마법으로 적을 무찌르는 선봉대입니다. 혼자서는 강력한 열기를 제어하지 못해 적은 물론 자신마저 불사르지만, 마도서의 제어 유닛인 레일리의 도움으로 그 화염을 자신의 힘으로 바꿔 싸울 수 있습니다.\n자긍심 강한 레일리는 미숙한 유나에게 항상 잔소리를 하지만 유나가 위험에 처할 때는 누구보다 든든한 보호자로서 그녀의 힘이 되어 줍니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SIXWING_NA_YUBIN"
L36_1 = "나유빈은 적을 지켜주는 배리어와 파수꾼을 처리하는데 특화된 수비수입니다.\n그는 아직 목적을 알 수 없는 육익이라는 단체의 리더로서 뜻이 맞는 조직원들을 모아 은밀하게 활동 중입니다.\n확실한 증거는 없지만 지금까지 여러 미제 사건들에 관련되어 있다고 알려져 있으며 접촉 시 각별한 주의가 필요한 위험인물입니다.\n현재 신분을 숨기기 위해 모처의 공공기관에서 근무 중이라는 정보를 입수하였으나 정확한 사실은 불명입니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_S_LEADER"
L37_1 = "플로라 메이드 서비스의 메이드장, 베로니카는 전투 중에 죽음을 앞두더라도 주인에 대한 충성심으로 마지막까지 남아서 적을 저지하는 스트라이커입니다.\n주인에게 문자 그대로 혼신을 다하는 자세는 다른 메이드들의 귀감인 한편, 고용주에게는 매력적인 인재로 비춰집니다.\n인원 확충 이후에도 그녀는 여러 고용주들의 장기 계약 제안을 거절하고 있습니다. 주인의 부름에 언제든 응답하기 위해서라고 하지만, 주인의 신분에 대해 묻는 사람들에게는 항상 수수께끼 같은 미소로 답할 뿐입니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_SPEAR"
L38_1 = "주방 담당인 리코리스는 창에서 뿜어져 나오는 충격파로 멀리 있는 적을 공격하는 스나이퍼입니다.\n플로라 메이드 서비스에 새롭게 합류한 리코리스는 유별나게 매운맛 요리를 좋아하는 것과 솔직하지 못한 성격을 제외하면 여느 또래와 다른 점이 없습니다.\n고용주들과 요리 철학으로 몇 차례 갈등을 빚어 올해의 고객만족 우수상을 수상 못한 데에 상당한 지분을 차지한다고 평가 받지만, 당사자는 완강하게 부인하고 있습니다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_TONFA"
L39_1 = "모네는 적의 전열을 밀어내거나 스킬을 봉인하는 데 탁월한 디펜더입니다.\n가난한 어촌 출신인 그녀는 마을 어르신들의 귀여움을 한몸에 받고 자랐습니다. 어느 날 베로니카를 만나 그녀와 함께 플로라 메이드 서비스를 세웠으며, 지금은 막내 메이드로서 열심히 일을 배우는 중입니다.\n계획 없이 의욕만 앞서서 사고를 치는 통에 릴리에게 사고뭉치로 낙인 찍혔지만, 주인을 따르는 마음 하나만큼은 다른 메이드들 못지않습니다."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_MASK"
L40_1 = "릴리는 후열의 적을 잠재워 피해를 입기 전까지 행동 불가로 만들거나, 클래스 간의 상성을 상쇄할 수 있는 서포터입니다.\n그녀는 자장가나 침구류 정비뿐만 아니라, 필요하다면 즉효성 수면제와 총포류 등을 동원해서라도 주인의 꿈자리를 사납게 만드는 적들을 처리합니다. 물론 당사자는 지금은 아로마 테라피처럼 온건한 방법만 쓰고 있다고 주장합니다.\n모네와 리코리스의 엄격한 선배지만, 한편으로는 메이드장의 응원에 힘입어 사회 적응에 필요한 지식들을 꼼꼼하게 공부 중입니다."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_MILITIA_SEONGTAE"
L41_1 = "강민우는 아군 솔저가 카운터에게 받는 피해를 감소시키는 디펜더입니다.\n또한 카운터 범죄자들을 사냥하는 민병대를 이끄는 리더이기도 합니다.\n그는 카운터에게 한없이 관대한 사회의 행보에 환멸을 품고 범죄자가 되었습니다.\n타깃을 처리하기 위해서라면 수단과 방법을 가리지 않기로 악명 높지만, 일부 시민들은 그가 나약한 일반인을 대신해 카운터 범죄와 맞서는 대변자라며 지지하고 있습니다.\n실제로도 민병대가 무장하지 않은 일반인을 공격한 적이 없는 것은 사실이지만 무질서를 유도하는 극단주의 세력의 인물이므로 접촉에 주의가 필요합니다."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_MILITIA_YURI"
L42_1 = "이유리는 카운터에게 치명적인 피해를 가하는 레인저입니다.\n또한 카운터 범죄자들을 사냥하는 민병대 조직의 일원이기도 합니다.\n과거, 가족의 죽음을 목격한 충격으로 기억을 잃은 채 방황하던 그녀는 악몽 속에서 들리는 목소리의 주인을 찾기 위해 악의로 가득찬 범죄의 길에 뛰어들었습니다.\n신입답지 않은 대담함과 빠른 적응력으로 거친 싸움에서 살아남았지만, 그녀는 아직 눈앞의 죽음을 초연하게 받아들일 정도로 냉정하진 못합니다.\n자신의 선택을 후회하지 않기 위해 복수의 감정을 불태우며 견디고 있을 뿐이죠."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_MILITIA_JIHUN"
L43_1 = "최지훈은 아군을 강화하며 주기적으로 적 후열을 노리는 스나이퍼입니다.\n또한 카운터 범죄자들을 사냥하는 민병대 조직의 일원이기도 합니다.\n과거에 훈련된 군인이자, 저격수였던 그는 자신의 장기를 십분 발휘해 민병대의 신입에게 사격술을 가르치는 교관 역할을 맡고 있으며, 표현은 직설적이고 거칠지만 대원들의 경솔한 판단을 바로 잡아주는 유능한 조언자이기도 합니다.\n하지만 그런 노력에도 불구하고, 민병대엔 이제 소수의 인원 밖에 남지 않았습니다. 동료가 죽어가는 비참한 현실의 벽 앞에서도 그가 아직 정신적으로 무너지지 않는 건, 아직 살아있는 대원들을 지켜야 하기 때문입니다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALT_CA_SEO_YOON"
L44_1 = "얼터그레시브 인자를 통해 능력을 각성한 서윤은 염동력으로 총기와 창 미스틸테인을 자유롭게 다루는 레인저입니다.\n그녀는 리플레이서와의 전투 이후, 그 공로를 인정 받아 더 이상 언더그라운드가 아닌 정식 라이선스 팀의 소대장이 되었습니다.\n그런 그녀의 활약은 많은 언더그라운드 카운터들의 시기와 경외를 얻고 있습니다.\n다만 주체성이 강하기로 유명한 그녀가 어째서 그런 성공을 거둔 뒤에도 영세한 규모의 태스크포스 업체에 직원으로 남아있는 것인지는 언더그라운드에서 풀리지 않는 미스테리입니다."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BARCODE_C_CHILDREN"
L45_1 = "아인&츠바이는 둘이 함께 전장에 있는 동안 특별한 능력을 얻는 스트라이커입니다. 아인과 츠바이는 장비를 포함해 모든 능력치가 동일합니다.\n두 아이는 서로 티격태격하다가도 금방 화해하는 사이 좋은 단짝친구이자, 여덟 명의 동생들에게는 아는 것 많고 믿음직스러운 언니들입니다.\n제프티 바이오테크는 이 아이들을 카운터 복제의 성공작으로 포장해 제공하려 했지만, 실제로는 카운터 워치를 공유할 뿐이라는 치명적인 결점을 지적 받아 보류 중인 상태입니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_PUPPET_C_WHIP"
L46_1 = "하랍은 적을 공격할수록 강해지는 서포터로, 소환된 유닛을 혼란에 빠뜨려 자신의 아군을 공격하게 만듭니다.\n크로넨워스 인형극단은 실감 나는 인형극으로 유명합니다. 공연에 몰입한 나머지, 인형이 정말 눈물을 흘렸다고 주장하는 관객도 드물지 않습니다.\n하랍 크로넨워스는 전쟁 이후 전 세계를 돌아다니며 그 놀라운 공연을 무상으로 제공해 왔습니다. 어째서 이런 일을 하느냐는 질문에는 소중한 인형을 찾고 있다는 대답만 할 뿐이었습니다.\n하지만 최근 공연을 보고 온 관객들은 그녀가 어딘지 다른 사람처럼 변한 것 같다고 입을 모아 말합니다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_PUPPET_C_BLIND"
L47_1 = "세라펠은 주변 아군이 받아야 할 피해 중 일부를 자신이 받는 디펜더입니다.\n최초의 인형인 세라펠은 어느 이야기 속 여인을 본따 만들었다고 전해집니다.\n먼 옛날, 하늘이 내린 듯 아리따운 여인이 있었습니다. 그녀는 모두의 사랑을 받으며 자란 탓에 아무리 사치와 향락을 누려도 만족하지 못했습니다.\n추종자들은 여인을 만족시키기 위해 온갖 악행을 저질렀고, 결국 여인은 자신을 증오하게 된 이들의 손에 처형됐습니다. 그러나 여인은 평생 모르고 지낸 고통과 증오로부터 처음으로 전율이란 것을 느꼈다고 합니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_CA_KING"
L48_1 = "리플레이서 킹은 다수의 병력을 소환하면서 조건부로 제한 없는 광역 공격이 가능한 디펜더입니다.\n리플레이서 신디케이트를 창설한 인물로, 조직의 핵심 구성원 중 상당수는 그가 설파한 이상에 이끌려 가담하였습니다. 이탈한 인원들은 조직 내에서 그를 선각자처럼 바라보고 있었다고 증언합니다.\n각국 정보 기관의 견제 속에서도 정체를 드러내지 않고 활동했기 때문에, 일각에서는 전직 정보 요원이거나 첩보 훈련을 받은 비합법 군사 조직 출신이란 추측도 나오고 있습니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_CA_QUEEN"
L49_1 = "리플레이서 퀸은 상태 이상으로 적을 제압하면서 범위 공격을 통해 자신을 지속적으로 강화해 나가는 스나이퍼입니다.\n현재 리플레이서 킹 대신 실질적으로 조직을 운영 중인 최고 간부이며, 제 4종 침식체와 동급의 위험 요소로 평가됩니다.\n그녀가 내부에 침투한 정보원들을 철저하게 축출하고 있기 때문에 리플레이서 신디케이트와 관련된 자료는 공급이 부족한 실정입니다.\n리플레이서 킹의 열렬한 추종자로 알려져 있으나, 막상 그의 이상에는 관심이 없는 것으로 보입니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_C_KNIGHT"
L50_1 = "리플레이서 나이트는 전장 어디로든 출격해서 적 진형을 무너뜨릴 수 있는 공격적인 디펜더입니다.\n세계 각국에 지명수배된 국제적 범죄자로서, 출몰한 현장을 초토화시키는 것으로 악명 높습니다. 이렇게 과격한 행동양식이 극단적인 선민사상과 맞물려 부하들에게도 기피되는 인물입니다.\n유출된 연구 자료들을 참고했을 때, 리플레이서 신디케이트의 연구진은 강압적인 훈련과 실험 후보들 간의 경쟁을 통해 의도적으로 공격성과 선민사상을 주입 내지 자극했다고 추정됩니다. 해당 인물과의 대면시 참고해 주시기 바랍니다."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_C_BISHOP"
L51_1 = "리플레이서 비숍은 은신 상태를 통해 적의 표적이 되지 않고 전장을 누비는 스트라이커입니다.\n리플레이서 신디케이트의 연구진들은 리플레이서 인자를 연구하던 중 손상된 신체를 수복하는 작용을 밝혀냈습니다. 이후 신디케이트에 합류한 구성원들 중에는 기존 의료기관에서 회복불가 판정을 받았다가 리플레이서 인자로 새로운 삶을 얻은 자들이 급증했습니다.\n내부 정보에 따르면 리플레이서 비숍은 그들의 대표자격으로 추정됩니다. 침식 재난에 휘말려 중상을 입은 것이라는 확인하기 어려운 증언이 존재하며, 착용한 장비들도 인자에 의존하는 불완전한 신체를 지탱하기 위한 것이라고 합니다. 직책이 간부인 반면, 활동은 극히 미온적이기에 정보기관들은 그녀를 특수임무에 투입되는 해결사로 보고 있습니다."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HORIZON_C_STAND"
L52_1 = "리타 아르세니코는 분신인 오메르타로 적을 격퇴하는 서포터입니다. 그녀의 금속조작 능력은 메카닉 유닛에게 매우 위협적입니다.\n본인은 인정하지 않지만, 피도 눈물도 없다는 호라이즌 파이낸스의 악명을 드높이는 데 큰 공헌을 하고 있습니다.\n특히 위압적인 눈빛과 거친 말투는 채무자의 자발적인 협력을 이끌어내는 데 유용합니다. 단골 술집의 바텐더는 리타를 찾아 온 손님들이 험악한 범죄자들부터 법조계 종사자에 이르기까지 다양했다며, 그녀의 과거 이력에 의구심을 드러냈습니다."
