L1_1 = {}
L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HORIZON_C_SCYTHE"
L3_1 = "대시는 원거리에서 예리한 바람을 방출해 적의 방어력을 감소시키는 스나이퍼입니다.\n소지한 낫은 휘두를 때마다 강풍을 만들어내는 기능이 탑재되어 있습니다.\n대시는 호라이즌 파이낸스에서 맡은 담보이자 수습 사원입니다. 지금은 부모가 진 빚을 갚기 위해 일하고 있습니다. 리타에게 사고만 치는 망할 꼬맹이라고 구박 받기 일쑤지만, 대표인 호라이즌은 삭막한 사무실 분위기를 누그러뜨리는 인테리어로 평가하고 있습니다."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CORRUPTED_C_SHADOW"
L4_1 = "데몬 타입 침식체인 스피라는 체력이 감소하면 적진으로 난입해 후방을 유린하는 스트라이커입니다.\n이 개체는 비교적 최근에 그림자로 변이한 것으로 추정되는데, 신체에서 관찰할 수 있는 부자연스러운 접합부는 변이에 저항하면서 생긴 상흔으로 보입니다.\n현실로 돌아가고 싶다는 집착이 강하며, 네임드 데몬인 미니스트라와 함께 출몰하는 빈도가 높기 때문에 일종의 사냥개 목적으로 종속시킨 개체일 가능성이 있다고 여겨집니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CORRUPTED_CA_MINISTRA"
L5_1 = "데몬 타입 침식체인 미니스트라는 광역 디버프로 적의 전력을 약화시키는 데 특화된 레인저입니다.\n그녀가 사망한 적을 재조립해 만들어낸 산물은 주위에 공포와 무력감을 퍼뜨립니다. 이면세계를 떠돌며 만들어내는 또다른 그림자, 통칭 자매들은 모두 스피라와 유사한 외견을 지녔습니다. 이는 스피라란 개체와 어느 시점에 맺었던 강한 유대 관계의 흔적으로 보입니다.\n고립시킨 사냥감이 고사해 가는 모습을 즐기는 가학 성향은 희생자의 말로를 짐작하게 해 줍니다. 이 때문에 관리국으로부터는 극히 위험한 개체로 지목된 바 있습니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ACADEMY_S_HANDGUN"
L6_1 = "브라우니 무어는 아군 솔저 유닛이 받은 디버프를 해제하고, 적이 주는 피해량을 일시적으로 경감시키는 서포터입니다.\n본래 그녀는 홀로 위험천만한 이면세계를 넘나들며 유적을 탐험하는 모험가였습니다. 한때 맨VS다이브란 인기 다큐멘터리의 호스트로 일했는데, 이면세계를 낭만적인 여행지로 그린다는 비판이 많았습니다.\n비판에 지친 그녀는 마침 아카데미 학생회장의 제안으로 교사가 되었습니다. 멋대로 휴강을 하고 돌연 사라지는 것이 일상이지만, 흥미진진한 모험담을 끝없이 풀어 놓는 그녀를 싫어하는 학생은 없습니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ACADEMY_C_TWINTAIL"
L7_1 = "나이엘 블루스틸은 건방진 행태로 아군을 공격성을 자극하는 스트라이커입니다.\n그녀는 아카데미 전투 평가를 항상 최고 등급을 놓친 적 없는 엘리트입니다.\n어릴 적부터 함께한 부하들과 팀을 꾸려 대장 행세를 하고, 약한 열등생은 무작정 깔보기로 악명 높았습니다.\n그런데 자신보다 강력한 라이벌이 나타난 뒤, 불안한 모습을 보이기 시작하더니 어떤 사고를 기점으로 말버릇이 이상하게 바뀌었습니다.\n지금도 여전히 남을 깔보는 태도엔 변함이 없지만, 자신을 당당히 쓰레기라고 외치는 점과 들리는 소문을 종합해보면, 그녀는 일종의 자기 암시에 걸린 것으로 추정됩니다.\n학생회의 전문가 소견에 따르면, 그녀만큼 쉽게 최면에 빠져드는 사람은 정말 보기 드물다고 하는군요."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JUNIOR_C_RULER"
L8_1 = "스카이 레이필드는 아군을 강화하고 적을 약화시키는 서포터입니다.\n그녀는 아카데미 초등부 출신의 카운터입니다.\n오랫동안 홀로 지내온 그녀는 공을 차거나 상상친구와 노는 게 익숙했습니다.\n카운터가 되고 아카데미에 입학한 뒤로도 한동안은 그런 생활을 보냈습니다.\n하지만 히어로 특별육성반에 가입한 뒤부터 많은 변화가 생겼습니다.\n지금은 또래 친구들을 사귀게 됐고, 그런 친구를 지키기 위해 동아리장에게 히어로 훈련도 받는 중 입니다.\n공과 상상친구는 이제 진짜 친구를 지켜주는 무기가 되어주었죠.\n소녀는 과연 더 많은 친구를 사귈 수 있을까요?"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JUNIOR_C_POLEARM"
L9_1 = "케이시 빈즈는 적을 공격할수록 성장하며 강해지는 디펜더입니다.\n그녀는 식물을 사랑하는 아카데미 초등부 학생입니다.\n카운터지만 카운터 기피증세를 보이는 특이 케이스로, 친절하고 배려심 깊은 성격에도 친구가 별로 없습니다.\n꽃꽂이를 좋아해 관련 동아리를 만들기도 했으며 식물에 대한 지식이 해박하지만, 정작 카운터로서의 능력 발휘는 학습이 아닌 본능에 맡기는 편입니다.\n그럼에도 케이시는 순수한 힘만으로는 아카데미 최고 서열에 속하기 때문에 히어로 특별육성반에서는 항상 그녀를 주시하고 있습니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JUNIOR_C_SPEAKER"
L10_1 = "아르티 라나는 카운터를 상대로 더 많은 도움을 주는 스나이퍼입니다.\n그녀는 나이를 비롯해 아카데미 초등부 이전의 행적이 밝혀지지 않은 학생입니다.\n비과학적인 것은 싫어하지만 히어로 만화는 좋아합니다.\n카운터를 관찰하고 자료를 수집하는 것이 취미이자 일상이며, 이 연구의 궁극적인 목표는 최강의 히어로에 어울리는 조수가 되겠다는 꿈을 이루는 겁니다.\n이 꿈을 위한 초석으로서 그녀는 히어로 특별육성반을 만들어 또래의 아이들을 연구 중입니다. 기성 카운터들과 달리, 요즘 어린 신세대 카운터들은 남다른 능력을 가진 케이스가 많기 때문이죠.\n다른 사람들에겐 그냥 세 친구가 재미있게 노는 소꿉동아리처럼 보일 뿐이지만요."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SIXWING_AMY"
L11_1 = "에이미 퍼스트윙은 적을 실로 베고 살아남는 자는 묶어서 조종하는 스나이퍼입니다.\n그녀의 독특한 복장과 기형적 행동은 모두 명백한 특정성이 있지만, 정작 행방을 아는 사람은 없습니다.\n정확히는, 그녀를 조사하던 인물들이 모두 사라졌다는 기록만 남아있을 뿐입니다.\n치밀하지 못한 성급함과 경박한 말투, 반사회적인 태도 등...\n증언에선 집단의 체제에 어울리기 힘들어보이는 성격으로 일관되게 묘사됩니다.\n하지만 실제로 그녀가 보여준 행적은 뒤처리가 치밀한 전문가의 면모를 보여주고 있죠.\n과연 어떤 가면이 그녀의 진짜 모습일까요."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCHOOL_C_PENCIL"
L12_1 = "미카★스타는 신비한 눈속임으로 적들을 괴롭혀 약화시키는 서포터입니다.\n세기의 대마술사를 꿈꾸는 그녀는 아카데미의 비전투주의 카운터들을 대표하고 있습니다.\n각자의 꿈은 존중 받을 가치가 있으며, 카운터라고 해서 반드시 전투 실력만 갈고 닦을 필요는 없다고 주장하고 있죠.\n조화를 추구하는 학생회장이 그녀를 학생회 임원으로 선별한 것도 그런 이유에서일 것입니다.\n하지만 비전투주의라고 해서 약하다는 뜻은 아닙니다.\n과감할수록 멋지다는 일념으로 혹독한 연습을 거쳐온 그녀의 마술은 무대라는 안전장치가 사라지는 순간, 치명적인 마법이 되니까요."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_S_MAY"
L13_1 = "메이는 자신의 준수한 체력과 보조 능력을 통해 주변 아군의 생존력을 끌어올리는 서포터입니다.\n전쟁고아로서 젤리피시 쾌적단의 일원이 된 그녀는 작고 여린 생김새와 달리 닻을 마음대로 휘두르는 괴력과 해양생물을 불러내는 법력을 타고났습니다. 어려운 생각을 하기 전에 먼저 행동하는 것이 신조이며, 그 활발한 행동력에 쾌적단의 동료들이 휘둘릴 때도 많습니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_S_MILLIA"
L14_1 = "밀리아 레이지는 뛰어난 지속공격 능력으로 피해제한이 있는 디펜더를 상대하는 레인저입니다. 또한 충격파를 발생시켜 인접한 적을 밀어낼 수도 있습니다.\n밀리아는 암살조직 출신으로서, 현재는 세계 최대의 첩보기관을 이끄는 인물입니다. 그녀의 머리카락은 「금주」라고 하는, 사용이 금지된 법술이 심어져 있기 때문에 형태와 강성 등을 자유자재로 조종할 수 있습니다.\n말수가 적고 냉철하지만 무작정 이해득실만으로 판단하지 않고 충분한 배려와 동정심을 발휘할 수 있기에, 시뮬레이션에서는 훈련을 감독하는 교관으로서 활동하게 되었습니다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_C_SOL"
L15_1 = "솔 배드가이는 공격 횟수에 따라 일정 시간 자신을 강화하고 주변의 적을 무력화시키는 디펜더입니다.\n스스로를 현상금 사냥꾼이라고 지칭하지만 주된 표적은 생체병기인 기어로서, 세상 곳곳을 떠돌면서 기어들을 말살해 왔습니다. 테크닉 없이 막강한 힘만으로 적을 파괴하는 거친 전투 방식은 사실 그가 기어로 개조된 인간이기에 가능한 것입니다.\n시뮬레이션을 통해 구현된 그는 원본과 같이 늘 퉁명스럽고 주위의 일에 수수방관하는 인물로 보입니다. 그러나 그 안에는, 굴곡 많은 삶을 헤쳐 나오면서 형성된 인간적인 면모가 분명 존재할 겁니다."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_C_RAMLETHAL"
L16_1 = "램리썰 밸런타인은 근거리에서 강력한 연계공격으로 적을 쓰러뜨리는 스트라이커입니다.\n램리썰은 인간을 본따 만들어진 생명체 중 하나입니다. 「밸런타인」으로 불리는 이들에게 주어진 사명은 인류를 근절시키는 것이었습니다. 램리썰 역시 자신이 받은 명령을 기계적으로 수행했지만, 한 인물과의 순수한 커뮤니케이션 끝에 감정을 이해하고 인류의 편에 서게 되었습니다.\n아이처럼 순수한 시선으로 세상을 바라보는 그녀는 사회성이 부족한 사원들의 좋은 친구가 되어 줄 수 있을 겁니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_M_INO"
L17_1 = "이노는 원거리에서 범위 공격을 하는 스나이퍼입니다. 자신에게 접근한 적을 날려 버리는 방어 능력을 갖추고 있으며, 비행형 유닛에게 강한 모습을 보입니다.\n친근하게 접근하고 친근하게 말을 걸며, 흥미가 있는 것은 스스럼없이 끼어들기에 얼핏 사교성 좋은 사람으로 착각하기 쉽습니다. 그러나 사실 그 이면에 협조성이란 없고, 모든 인간을 깔보고 있으며, 그녀가 본능적으로 경계하는 인물에 대해서는 매우 성질이 거칠어집니다.\n시뮬레이션의 엔트리에 포함되어 있지만, 남의 약점을 쥐고 흔들면서 조롱하기를 즐기는 성향 탓에 동료로 삼는다는 것은 요원한 인물입니다. 그녀의 정체는 마기로 성전 당시 희망을 원했던 자들의 의지가 깃든 반(半)생명체입니다. 이런 이면이 시뮬레이션을 통해 카운터/메카닉으로 구현되었습니다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_CA_JACKO"
L18_1 = "잭 오는 어떤 목적을 위해 만들어진 인공생명체입니다. 솔의 연인인 아리아의 영혼의 절반과 기억을 가진 그녀는, 평소에는 성숙한 어른처럼 이지적이지만 가끔씩 장난기 가득한 어린애처럼 행동할 때가 있습니다. 현재는 현상금 사냥꾼인 솔의 파트너로 일하며 자신이 존재하는 의미를 찾고 있습니다."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCAVENGER_S_CUTLASS"
L19_1 = "글리치는 은신 상태로 전장에 투입되는 스트라이커입니다. \n스캐빈저 약탈조 페네오의 전투원인 이들은 다른 스캐빈저들처럼 약탈을 일삼습니다. 하지만 평소에는 기계를 정비하고 이면세계 기술을 연구하고 탐닉하는 엔지니어이기도 합니다. \n그들이 일하는 연구시설은 인체 개조가 쉽게 이뤄지며, 항상 불활성 기체와 비명소리가 끊이지 않습니다. 그런 윤리적 제약을 받지 않는 실험 환경과 질 좋은 이면세계 유물들 덕분에 태스크포스와도 정면으로 맞설 수 있는 기술력을 갖게 된 것입니다. \n비록 그 기술이 다소 불안정하고 어그러진 형태더라도 말이죠."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCAVENGER_S_HAMMER"
L20_1 = "오버플로는 넉백에 저항하며 적을 몰아붙이는 돌격형 디펜더입니다. \n 스캐빈저 돌파조 피카도르의 전투원인 그는 약탈 타깃이 정해지면 제일 앞장서서 길을 뚫습니다. 약탈할만한 가치가 있는 것들은 언제나 튼튼한 방벽의 보호를 받고 있기 때문이죠. \n요즘 시대에 보기 힘든 이 냉병기는 힘을 증폭시키는 강화복과 함께 시너지를 일으키며 그 어떤 보안 시스템도 단숨에 찌그러트립니다. 물론, 길을 가로막는 것이라면 사람이나 전투 병기도 예외는 아닙니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCAVENGER_MA_EVOLVE"
L21_1 = "이볼브 원은 아군 메카닉을 희생시켜 강해지는 공격적인 원거리 디펜더입니다. \n범죄조직 스캐빈저를 이끄는 이 기계 우두머리는 단순히 침식되어 폭주하는 로봇들과 달리 스스로 명확한 의사와 목적을 갖고 파괴활동을 벌입니다. \n그것은 진화에 집착하며, 인간을 비롯한 모든 것이 진화의 소모품일 뿐이라는 뒤틀린 관념을 가지고 있습니다. \n야생에 빗댄다면 그것은 먹이사슬의 정점에 있는 포식자에 가깝습니다. 기계가 기계를 파괴하고 그 잔해를 먹어치우듯 흡수하는 이 전례없는 기행은 게걸스런 육식동물을 연상케 합니다. \n발톱과 이빨 대신 융합탄과 중화기로 무장하고 있다는 점은 다르겠지만 말이죠."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ETC_S_DOCTOR"
L22_1 = "악당 론 리는 적들에게 치명타 피해량 감소를 비롯한 여러 디버프를 부여하는 서포터입니다.\n과거, 그녀는 그저 침식학에 조예가 깊은 음침한 과학도일 뿐이었습니다. 하지만 사랑을 깨우치고 실연의 아픔을 느끼면서 모든 커플들을 부숴버리겠다는 뒤틀린 증오를 품게 되었습니다.\n그녀는 관리국 산하의 연구소 직원이 되어 몰래 침식체를 연구하면서 음모를 꾸몄습니다. 하지만 중요한 순간에 계획이 틀어지며 감옥에 갇히고 말았죠.\n탈옥에 성공한 지금은 그녀가 어떤 음모를 꾸미고 있는지 알 수 없습니다. 하지만 커플을 타도하겠다는 집착을 버린 채, 한 사람만을 위해 일하게 된 것은 분명한 사실입니다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCAVENGER_C_COLLECT"
L23_1 = "기계수집가는 기생충을 이용해 아군을 강화하고 적의 버프를 해제하며 메카닉에겐 추가적인 효과를 부가하는 서포터입니다. \n그녀는 블랙네트워크에서 가장 악명 높은 해적입니다. 특히 기갑 병기를 개발하는 기업들 사이에서 기계수집가란 이름은 경쟁 업체들보다도 경계 대상 1순위로 꼽힙니다. 손가락 한 번만 튕기면 그녀가 조종하는 기생충들이 모든 기계들의 통제권을 빼앗아버리기 때문이죠. \n그녀는 이름처럼 기계를 수집하지만, 또한 기계의 한계를 시험하는 개조를 즐깁니다. 때문에 그녀의 눈에 띈 수집품들은 얼마 못가 망가지고 맙니다. 그녀의 가혹한 취미를 견딜 수 있는 기계가 나타나지 않는 한, 그녀의 수집 활동은 끝나지 않겠죠."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_EXPRESS_C_LALA"
L24_1 = "라라 예거는 지정한 위치를 완전회피 상태로 선회하면서 범위 내에 접근한 적을 공격하는 타워입니다.\n플라티나 익스프레스의 플래티넘 랭크는 단 한 명의 배달부에게만 허용되는 명예입니다. 그리고 라라 예거는 입사 이래 플래티넘 랭크를 놓친 적이 없습니다.\n모든 배달부가 신속, 정확, 안전을 기치로 삼은 가운데, 라라 예거에게는 또다른 특별한 목표가 있습니다. 그것은 바로 배송이 제때 도착했을 때 볼 수 있는 고객의 미소입니다.\n비록 전투 경험은 없지만, 주행 중인 그녀에게서 배송 상품을 빼앗으려고 덤벼든 자들은 이제까지 단 한 명도 없었습니다."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BARCODE_C_SISTER"
L25_1 = "루시드는 2기의 침식체가 한계 이상의 힘을 내도록 강화해 주는 스나이퍼입니다.\n그녀는 제프티 바이오테크가 진행해 온 가혹한 실험의 생존자로서, 대상의 사고를 읽을 수 있는 정신감응 능력을 지니고 있습니다. 나나하라 가문 연합이 지닌 「바람의 목소리를 듣는 능력」에 비하면 불완전하지만, 침식체를 군사적으로 활용할 수 있다는 우려가 존재합니다.\n의료진에 따르면, 알 수 없는 이유로 신체가 급격하게 쇠약해지고 있어 기대 수명이 매우 짧을 것이라고 합니다. 실험의 후유증이라고 단정하기에는 의학적으로 불분명한 상황입니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CA_JOO_SHI_YOON"
L26_1 = "오랜 번뇌의 사슬을 끊고 스스로를 완성시킨 자, 주시윤은 구도자의 혈맥에 전해져 내려온 검인 용아와 칼집 연화를 이용해 적의 특수기와 기본 공격을 받아치는 스트라이커입니다.\n그는 항상 주위로부터 속내를 알 수 없다고 평가받아왔습니다. 그뿐 아니라 그 스스로도 자신이 원하는 것이 무엇인지 깨닫지 못했습니다.\n복수를 해야 하지만 그러길 원하지 않았고, 용서하고 싶지만 그 이유를 찾지 못한 채 방황해 온 것입니다.\n그러나 삶과 죽음의 경계에서 자신의 번뇌를 솔직히 받아들였을 때, 긴 방황은 끝이 났습니다. 오랫동안 되풀이됐던 고통에서 벗어나 깨달음의 경지에 이른 것입니다.\n이제 그는 더 이상 어머니에게서 물려받은 검을 뽑아들 때마다 번민하지 않습니다. 이전처럼 현장에서 은근슬쩍 사라지는 대신, 가장 위험한 순간에 최전방에서 적을 막아서기도 하죠.\n물론 그 자신은 그다지 달라진 것이 없다고 주장하지만 말입니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_KNIGHT_C_HOLY"
L27_1 = "루크레시아는 아군을 축복하여 불사 상태로 만들고 적에겐 부정의 기운을 투사하는 공중 레인저입니다.\n그녀는 구원기사단의 주축 멤버로서, 구원자라는 인물을 따르는 충실한 신봉자입니다.\n축복이라는 이름의 힘을 사용하며 성녀라고도 불립니다. 하지만 그녀가 말하는 자비와 안식을 표현 그대로 받아들여서는 위험합니다.\n그녀가 염원하는 구원은 단 하나입니다. 그리고 그녀는 그 구원을 이루기 위한 과정에서 치러지는 모든 희생을 축복이자 자비라고 생각하고 있습니다.\n위험한 사상과 그것을 현실로 만드는 힘을 가지고 있는 인물이므로 교류에 있어 각별한 주의가 요구됩니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HORIZON_M_LOAN"
L28_1 = "호라이즌은 지속적인 배리어 생성과 면역 효과로 자신을 보호하고 흉기로 적들을 날려버리는 저돌적인 디펜더입니다. \n그녀는 피도 눈물도 없기로 유명한 호라이즌 파이낸스의 수금업자입니다. 하지만 높은 금리와 악명에 비해 사무실 재정은 항상 제자리 걸음입니다. 수익의 대부분이 공공기물 파손으로 인한 변제로 나가기 때문이죠. 많은 채무자들이 이 작은 수금업자를 꼬마라 비웃으며 행동으로 보여주기 전까지 주머니를 열지 않으니까요. \n주위에서 보기에도 호라이즌은 금융업에 전혀 재능이 없다는 걸 알지만, 정작 본인은 개선할 필요성을 느끼지 않습니다. 그녀는 오히려 돈을 버는 것보다 수금 과정에서 마주치는 인간들을 관찰하는 것에 더 관심있어 보입니다. \n호라이즌의 행패에 당한 채무자들은 그녀가 자신의 힘을 과시하고 반응을 즐기는 것이라 주장하지만, 다른 목적이 있는 것인지는 좀 더 지켜봐야할 것 같습니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_C_VIOLIN"
L29_1 = "셰나는 치명타 발생에 비례해 생성되는 음표로 범위 피해를 입히는 근접형 스나이퍼입니다.\n제프티 바이오테크의 경호실장이지만, 대외적으로는 모습을 드러낸 적이 없습니다. 오히려 VIP들을 초청한 자리에서 즉석 연주회로 존재감을 드러냈다는 증언이 대다수입니다.\n그녀가 언급한 엘리시움 필하모닉은 관리실패 직전까지 구 관리국을 적대해 온 요주의 조직으로서, 당시 건재했던 전대들의 활약으로 최고 지휘자를 잃고 와해된 바 있습니다.\n과거 엘리시움 필하모닉이 건재하던 시절, 셰나는 잔혹한 공연의 서막을 장식하는 역할이었습니다. 그녀가 등장한 것이 조직의 재부상을 뜻하는지, 혹은 현실에 잔류한 패잔병에 불과한지는 속단할 수 없습니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_XIAOLIN_RA"
L30_1 = "샤오린은 훈련을 통해 정밀 저격에 사용했던 생체 전류 조작 능력을 발달시켰습니다.\n전류로 조종하는 4기의 서포트 드론은 샤오린의 표적에게 시간차 없는 일제 사격을 퍼부어 최소한의 생존 가능성까지 완벽하게 차단합니다.\n서포트 드론과의 상호 간섭으로 증폭된 도어 노커는 고착 상태에 놓인 전선을 타파해 줄 훌륭한 공성 수단입니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_XIAOLIN_RB"
L31_1 = "연구진들은 샤오린이 기술실증 단계의 드론 캐리어인 팰콘 네스트를 시범 운용하는 데 있어 가장 적합한 인재라고 판단했습니다.\n거점 수비용으로 설계된 이 드론 캐리어는 날렵한 소형 드론을 출격시켜 후방의 적을 우선 제압합니다.\n연구진은 샤오린과 팰콘 네스트의 연계가 전장 장악에 큰 성과를 보여 줄 것으로 기대하고 있습니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_YOO_MI_NA_RA"
L32_1 = "유미나는 코핀 컴퍼니에서 쌓은 경험을 바탕으로 이전만큼 과감하면서도 더욱 효율적인 작전활동을 수행할 수 있게 되었습니다.\n고유무장 울브즈베인은 오랜 침묵을 깨고 새로운 사용자의 힘을 받아들이기 시작했습니다.\n특수한 장비의 보조 없이 전력을 개방하는 것은 아직 어렵지만, 이전보다 힘의 제약이 약해진 것은 틀림없습니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_IRIE_RA"
L33_1 = "새로운 장난거리를 찾던 아이리에게 번뜩이는 아이디어가 떠올랐습니다.\n몸을 고무공처럼 가볍고 탄력 있게 만들어 주던 CRF를 똘똘 뭉치자 멋진 방패로 변한 것입니다.\n이 방패는 뛰어난 탄력을 지녀서 달려드는 적을 튕겨내거나 넓게 펼쳐 아군을 지킬 수도 있습니다.\n아이리는 자신의 기특한 성과로 어떤 새로운 장난을 칠 수 있을지 기대 중입니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FUTURE_MA_LOAN"
L34_1 = "「엠버 박사의 일지를 번안한 내용입니다.」\n전투 형태로 재기동한 호라이즌은 공중에서 적의 체력에 비례한 피해를 입히는 스트라이커입니다.\n신뢰할 수 있는 연구진의 분석 결과, 콜드 케이스 137번은 단독 공간도약 및 성간항행이 가능하게 설계된 호위기로 추정됩니다. 교전에 필요한 무장은 시무르그 실루엣이라는 플랫폼을 통해 조달하며, 따라서 비전투 상태에서 발생시키는 역장은 항행 중 손상을 막기 위한 보호 수단일 가능성이 높습니다.\n이번 분석으로 안드로이드에 관련되어 큰 소득을 얻었습니다. 다만 이 프레임이 전략병기로 악용될 우려에 연구진 전원이 동의하였기에, 활용 불가로 판정 후 봉인 조치할 계획입니다. \n부디, 내 걱정보다 이로운 곳에 쓰일 수 있길."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SHARKS_C_CLAW"
L35_1 = "드라코는 표적으로 지목한 적 한 명을 끝까지 추격하는 스트라이커입니다. 표적이 멀어지면 닻을 걸어 빠르게 접근할 수 있습니다.\n「드레이크 선장」은 본래 상선만을 노리던 교활한 침식체의 별명이었습니다. 드레이크 선장을 매번 간발의 차로 놓쳤던 프론트 베이의 용병들은 당당히 사냥에 성공한 어린 소녀에게 그 별명을 넘겨 주었습니다.\n물론 프론트 베이 샤크스는 아직 새내기 태스크포스입니다. 심지어 최근에는 방벽 건축제에서 다른 회사와 시비가 붙었다가 귀중한 배를 날려 먹기도 했습니다.\n드라코는 자신의 실력으로 사소한 손해 따위 금방 메꿀 수 있다고 믿어 의심치 않습니다. 그 자신감이 프론트 베이 샤크스에 바람 잘 날 없는 이유이기도 하지만 말입니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_S_KUNOICHI"
L36_1 = "하야미 카나데는 회피를 통해 스탠스를 강화하며 변칙적인 전투를 벌이는 스트라이커입니다.\n호위무사 가문 출신인 그녀는 어린 시절부터 '집안일'에 두각을 드러내며 나나하라 당주의 호위역을 맡게 됐습니다.\n냉철하고 고지식하던 어린 무사는 온화한 성품의 주인을 섬기게 되면서 점차 변해갔습니다. 주인의 곁을 지키는 것 외에도, 가족을 꾸려 행복해지라는 명을 받들어 행복한 삶을 누렸습니다.\n비록 카운터는 아니지만, 관리국에 종사하며 주요한 임무와 함께 무장을 수여받기도 했습니다.\n아무도 그 충성스럽고 강한 무사의 불명예스런 최후를 예상하지 못했습니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_C_OROCHI"
L37_1 = "오로치는 뱀의 분신을 부려 한 상대를 집요하게 공격하는 레인저입니다.\n세상이 오랜 대흉년에 시달릴 때, 만물의 소리를 듣는 여인이 가뭄으로부터 외로움을 듣고 달래어 풍요를 되찾았습니다. \n여인은 오랫동안 풍요를 모시며 무녀로 추앙받았습니다. \n하지만 풍요에 만족하지 못한 인간들은 영생을 탐했고, 기어이 손에 무녀의 피를 묻히고 말았습니다. \n풍요는 비와, 번개와, 산을 덮는 여덟 머리의 뱀으로 변해 인간을 벌했습니다. 많은 인간들의 희생 끝에 결국 그녀는 봉인됐습니다. \n하지만 인간에게 욕망이 존재하는 한, 그녀는 인간들에게 영생을 속삭이며 다시 깨어나게 될 겁니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_ELIZABETH_RA"
L38_1 = "긍지높은 귀족 가문의 영애. 그 외에 엘리자베스에 대해 알려진 정보는 제한되어 있습니다. 프리드웬의 기관장이란 지위를 통해 그녀가 단순히 콧대만 높은 귀족 아가씨는 아니라고 추측할 뿐입니다.\n하늘에서 쏟아지는 그녀의 검을 목격한 사람들은 강철 날개를 펼친 천사가 내려왔다고 표현합니다. 등에 돋친 날개는 그녀가 본연의 힘을 사용할 때 드러나는 CRF 발현의 흔적일 뿐이라고 하지만, 진실은 베일에 싸여 있습니다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_CHARLOTTE_RA"
L39_1 = "조디악 나이츠의 전승은 버고 소드를 쥔 역대 기사단장들의 무훈에 대해 이야기합니다. 별의 가호 아래 지치지도, 쓰러지지도 않고 강적을 무찔렀다는 내용은 신화에 등장하는 초월적인 존재를 연상케 합니다.\n불의한 적이 나타난다면, 당대 버고 소드의 계승자인 에스테로사는 기꺼이 그 힘을 사용할 준비가 되어 있습니다. 그리고 단원들은 치열한 전쟁터에서도 그 위용이 찬란하게 빛날 것이리라 믿어 의심치 않습니다."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_STREGA_LAURA_RA"
L40_1 = "잠든 마녀가 깨어나는 시간. 관이 열리며 소리 없이 절규하는 망령들이 쏟아져 나옵니다. 잠에서 깬 마녀는 눈을 비비며 사역마를 부르죠. 사역마는 제멋대로 흩어진 망령들을 이끌며 마녀의 부름에 충실히 응답… 해야 하는데. 망령들과 함께 몰려 다니며 이리저리 사고치기 바쁘네요.\n망령들과 사역마가 이렇게 장난꾸러기인 줄 알았다면, 마녀도 그녀의 포근한 잠자리 한 켠을 내주지는 않았을 겁니다."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_YOO_JIN_RB"
L41_1 = "연이어 강적들과 맞닥뜨리면서, 유진은 막무가내로 싸우는 것에 한계를 느꼈습니다.\n그리고 그 고민은 과거 연구진들이 일깨우는 데 실패했던 야수성의 일부를 끌어냈습니다. 환상종의 것으로 추정되는 이 힘은, 적의 약점을 포착하는 예리한 후각과 함께 한정된 영역의 물리법칙을 왜곡시킵니다.\n이제 유진은 사냥개처럼 사각으로 파고드는 총탄과 풍부한 실전 경험을 통해 조금 거친 방식이 필요한 골칫거리들을 해결해 나갑니다."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_CA_JAKE"
L42_1 = "테크레벨 5 장비, 스톰 브링거를 착용한 제이크 워커 대령은 자신의 영역 내에 들어선 적을 약화시키는 데 특화된 디펜더입니다.\n워커 대령의 CRF 출력은 한마디로 요약해 이례적이라고 할 수 있습니다. 그 위력이 지나친 나머지, 종래에는 출력을 높일 경우 심각한 부상을 입을 우려까지 존재했습니다.\n하지만 스톰 브링거를 투입하면서 이러한 우려는 종식되었습니다. 스톰 브링거는 워커 대령의 힘을 축적해 적을 분쇄하는 강력한 전기장 형태로 방출합니다. 더 이상 힘을 억누를 필요가 사라진 워커 대령은 자신을 부르는 곳이면 어디든 갈 준비가 되어 있습니다."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_KNIGHT_C_FLAG"
L43_1 = "샬롯은 깃발을 꽂아 생성하는 범위 버프로 아군의 생존력을 보조하는 지원형 디펜더입니다.\n그녀는 최전방에서 구원 기사단의 진격로를 만들어 온 선봉장입니다. 평소에 보여 주는 조용한 모습과 달리, 깃발을 들고 선봉에 선 늠름한 모습은 어린 소녀에게 향하던 기사단원들의 의심 어린 시선을 거두게 하기에 충분했습니다.\n하지만 샬롯에게 단원들의 반응은 중요하지 않습니다. 마르티네즈 백작가는 그녀를 오직 가문의 영광만을 위해 헌신하는, 가장 완벽한 기사로 만들었기 때문입니다. "
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_C_QUEEN"
L44_1 = "제이나 크로펠은 자체 회복을 통해 안정성을 확보한 스나이퍼로, 기본 공격 시전을 통해서만 스킬 게이지를 충전할 수 있습니다.\n슈퍼맥스급 교도소에 수감 중이던 제이나는 그 존재가 대내외에 철저하게 기밀 정보로 취급되어 왔습니다.\n기억을 잃어 버린 그녀에게 리플레이서 퀸은 어디까지나 타인에 불과합니다. 외부의 자극으로 떠오르는 리플레이서 퀸의 기억에 대해서도 항상 불안과 거부감을 표현합니다. 하지만 국제 여론이 그녀의 상태를 이해해 줄지는 미지수입니다.\n한 가지 확실한 사실은, 제이나의 머릿속에 잠들어 있는 기억들이 몇몇 야심가에게는 아주 위험하면서도 매력적인 무기로 보일 수 있다는 것입니다."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BAR_C_CEO"
L45_1 = "그레모리는 알콩달콩한 기운을 사방에 퍼트려 출격과 동시에 적들을 잠재우는 서포터입니다.\n한때 그녀는 암흑가에서 사람의 운명을 바꿔주는 예언자로 유명했지만, 지금은 과거를 청산하고 작은 바를 열었습니다. 남의 사랑 고민을 듣고 조언을 해주는 사랑 해결사로 활동 중이죠.\n언제나 독한 술을 곁에 두고 순정만화를 즐기는 그녀에게 있어 주점 밖 세상 돌아가는 일은 관심거리가 아닙니다. 처음 온 손님의 애정운을 점치거나, 서로 미워하는 사람들을 사랑에 빠지게 하고 구경하는 것을 취미로 삼습니다. \n다만 그녀가 모든 유형의 사랑을 즐기진 않습니다. 특히 불륜처럼 불순한 사랑을 목격하는 날엔 가게가 한바탕 뒤집어지곤 하니까요."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ORCA_RA"
L46_1 = "불길한 붉은색으로 빛나는 워치, 오르카에는 항상 침식체를 향한 증오심이 넘실거립니다.\n워치로부터 흘러넘친 증오심은 본래라면 불행한 결과를 초래했을지도 모르지만, 현 소유자의 손 안에서 그 이름에 걸맞은 새로운 형태를 얻었습니다. 수면에서, 지면에서, 그리고 그림자 밑에서 도사리다가 소유자와 함께 적을 물어뜯는 짐승은 침식체에게 실로 치명적인 존재입니다. 그 위험성이 침식체에게 국한되는 까닭은, 아마도 소유자와 워치 안에 깃들어 있는 의지 간의 고요한 유대 덕분일 것입니다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BAR_S_BARTENDER"
L47_1 = "성황청으로부터 재능을 인정받은 그녀는 비교적 젊은 나이에 정식 퇴마사가 되었습니다. \n구마회의 샛별이 되어 아티팩트까지 받은 그녀에겐 밝은 미래만이 있는 것 같았습니다. \n그녀는 종단의 기대에 부응하기 위해 수천 권에 달하는 책을 읽고, 속세의 사람들과 어울리기 위한 공부를 하며 자신의 사명에 대비했습니다. \n그리고 이내 그녀는 사람들 속에 숨어있는 악마를 찾는다는 성무를 맡게 됐죠. \n그날 신부가 그녀의 손에 쥐어준 것은 그레모리의 바라고 적힌 명함 한 장이 전부였습니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_CA_JIA"
L48_1 = "싱귤러리티 신지아는 입자화된 CRF로 적을 무력화하는 동시에 아군에게 유리한 효과를 부여하는 서포터입니다.\n그녀는 자신의 상상력에 기반해 물질을 생성할 수 있는, 무궁무진한 가능성을 지닌 존재입니다. 혹자가 평가한 대로 인류라는 종의 특이점에 도달한 결과물일지도 모릅니다. 하지만 태생적으로 불완전하다는 한계를 가지고 있기에, 그 힘은 사용하면 사용할수록 인간성을 마모시켜 무기물에 가까운 존재로 만들 위험이 존재합니다. 그렇기에 역으로 인간성을 추구하는 그녀에게 주어진 결과 상상의 날개라는 형태를 이루게 되었는지도 모릅니다. 한 사람의 비틀린 두려움이 낳은 산물 중에서 가장 올바른 결과를 맞이한 존재는, 오늘도 더 나은 세상을 위해 사람들 곁에 존재합니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_C_SPEAR"
L49_1 = "라파엘라 주리 더 에빌 체이서는 악을 감시하는 타워 「감시자 모드」와 악을 추적하는 스트라이커 「추적자 모드」, 두 가지 클래스를 가진 하이브리드형 공격수입니다.\n자신을 두고 떠난 쌍둥이의 비밀노트를 보게 된 라파엘라는 불과 한 달만에 자신에게 어울리는 새로운 창술을 고안했습니다.\n더 많은 악과 대적할 수록 강한 공격을 할 수 있게되는 그녀의 「추적 창법」은 지금껏 자신만이 완벽하게 터득했습니다.\n파사의 추적자로 활동 중인 그녀는 현재 자신의 가치를 알아 본 알파트릭스에 입사. 그 활동을 지원받고 있습니다.\n※이상의 서술은 조사 대상이 알파트릭스에 제출한 이력서의 요약임을 알려드립니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_M_SIEGE"
L50_1 = "골리앗은 가로막는 적의 보호막을 부수고, 느리지만 강력한 포격을 선사하는 시즈입니다.\n골리앗은 외부의 간섭에 배타적이고 폐쇄적인 북방 합의체가 독자적으로 생산한 군용 병기입니다.\n적대적 함선을 단독으로 요격하기 위해 개발된 이것은 해적이 탈취한 태스크포스의 중장갑함이 합의체의 영공을 가로지를 때, 단 일격에 그것을 추락시킴으로써 실전성을 입증했습니다.\n해당 개체는 단순한 명령 복종이 아닌 충성심이라는 특수한 인공지능 알고리즘을 탑재했습니다.\n그것이 정말 설계자들이 뜻하는 대로 작용하는지는 알 수 없지만요."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_MIYA_RA"
L51_1 = "하트베리에서 방송 경험을 쌓으면서, 미야의 개인 방송도 숨어 있던 잠재력이 발휘되기 시작했습니다. 루미가 쇼핑 투어 컨텐츠에서 골라 줬던 대담한 방송 의상을 멋지게 소화해낸 것이 대표 사례겠죠.\n기존 팬들은 미야가 실수할 때마다 내성적인 성격이 여전하다거나 미고래는 전혀 성장하지 않았다는 도네이션 단골 멘트로 놀리기 일쑤입니다. 하지만 허둥거리던 미야가 기합을 넣고 방송을 이어가려 하면 열렬히 호응해 주니, 조금 짓궂은 장난들은 그들만의 응원 방식일지도 모릅니다."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_OZ_S_RUNNER"
L52_1 = "도로시는 적들을 무력화시키고 아군의 전투를 보조하는 지원형 스나이퍼 입니다. 의족으로 고속 기동을 하여 적에게 원거리 공격을 가합니다.\n 과거 육상부 선수를 꿈꿨던 소녀는 불의의 사고로 꿈을 잃게 되었습니다. 그런 소녀에게 새로운 다리가 되어 준 것은 「구두」라는 별명의 의족이었습니다.\n이 실험적인 기계장치는 뛰어난 고속 기동 능력과 도약력을 지니고 있지만, 통제하기 어려운 야생마와 같았습니다. 소녀가 구두를 다룰 수 있었던 것은 다시 달리고 싶다는 염원이 고삐가 되었기 때문일지도 모릅니다.\n한편, 이와 같은 기술을 다루는 곳은 극소수이기에 소녀에게 구두를 제공해 준 조직에 대해서도 의문점이 남는 상황입니다."
L50_1[1] = L51_1
L50_1[2] = L52_1
