L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_OZ_C_SWORD"
L3_1 = "리온은 체력이 약한 유닛에게 유독 강한 근접 범위 딜링형 스트라이커입니다. 소유자 본인의 의지가 아니라 기생체의 의지로 능동적으로 움직이며 적에게 공격을 가합니다.\n평소 카운터를 동경하던 겁쟁이 소녀는 불의의 사고로 「악마의 파편」이라 불리는 기생체와 이어지면서 카운터가 되었습니다. 하지만 어쩐지 꿈꿔왔던 삶과는 사뭇 달랐습니다. 기생체 때문일까요?\n그럼에도 소녀는 기생체에게 「토토」라는 이름을 붙여 주고, 맛있는 음식을 주며 그를 이해하기 위해 힘썼습니다. 이제는 토토의 힘으로 친구들을 지켜줄 수 있게 되어 다행이라고 생각합니다."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_POLICE_SOYEONG_RA"
L4_1 = "제 4 특별기동수사대가 주목할 만한 몇 가지 성과를 올리자, 미온적이던 상부에서도 이들을 지원하자는 목소리가 점차 커지기 시작했습니다.\n함께 출동하게 된 경찰헬기들은 교통 관제와 용의자 추격을 겸해 신속한 체포를 가능케 합니다. 최신 사양으로 교체된 신형 경찰차는 어떤 도로 위에서든 운전자의 실력을 고스란히 발휘하게 해 주죠. 물론 열악한 환경에서도 활약해 온 강소영 경위에게는 튼튼한 개인 장비만으로도 충분하겠지만요."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CORRUPTED_M_ARMOR"
L5_1 = "모르스는 아군이 사망할 때마다 체력과 방어력이 영구적으로 증가하는 디펜더입니다.\n구 관리국 시절, 모르스는 일반 대원들에게 그림자의 위험성을 대표하는 존재였습니다. 기록 영상에 남아 있는 그것의 모습이 매우 흉포하고 불길하게 여겨졌기 때문입니다. 마에스트로에 필적할 만큼 오래된 침식체이며, 대화가 가능하다고 해도 많은 그림자가 그렇듯 실질적인 소통이 이루어지는지는 확신할 길이 없습니다.\n드물게도 침식체에게 공격성을 드러내는 개체이지만, 소통의 문제에서 나타나듯 행동 양식은 파악되지 않은 부분이 많아 주의가 필요합니다. "
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_CA_CONDUCT"
L6_1 = "마에스트로 네퀴티아는 적에게 점차 강력해지는 약화 효과를 부여하면서 자신의 단원들을 지원하는 타워입니다.\n마에스트로는 엘리시움 필하모닉의 최고 지휘자로서 구 관리국과 적대해 온 존재입니다. 비록 구 관리국의 전대들이 요격에 성공했지만, 그 이후의 종적은 관리실패로 인해 추적이 중단되었습니다.\n마에스트로의 세계, 통칭 엘리시온은 파동을 이용한 기술체계가 기형적으로 발전한 문명이었습니다. 그녀가 구 관리국에 위협이 되었던 까닭은 멘탈 프린팅의 창안자라는 점과 더불어, 그 불안정한 기술을 단독으로 구사할 수 있다는 면이 큽니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SECURITY_S_AGENT"
L7_1 = "레버넌트는 아군 솔저 다중 유닛을 지원하는 데 특화된 서포터입니다.\n본명은 레아 슈나이더로, 그로니아의 국내 • 외 첩보 활동을 총괄하는 그로니아 보안국의 1급 공작원입니다. 단독으로도 우수한 능력을 발휘하지만, 그 진가는 무장도 훈련도 부족한 병력들을 최정예 부대처럼 싸울 수 있게 만드는 현장 지휘 역량입니다. 그녀는 국제 수배자인 리플레이서 나이트의 계획을 저지한 것을 비롯해 외부에 알려져선 안 될 경이로운 성과를 여럿 달성했습니다.\n역동적인 하드 록을 사랑하고 바이크 투어를 즐기기에 자유분방한 인물으로 오해하기 쉽지만, 보안국 수뇌부에서는 전시임에도 반군을 향한 그녀의 적개심이 지나칠 정도라고 우려를 표한 바 있습니다. "
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_C_BASS"
L8_1 = "카르멘은 치명타가 발생할 때마다 아군을 치유하는 서포터입니다. 카르멘이 생성하는 음표는 아군의 해로운 효과를 제거하면서 체력을 회복시킵니다.\n그녀는 엘리시움 필하모닉에서 콘트라베이스를 연주하는 단원들의 대표입니다. 차분하고 구슬픈 선율은 침식체에게 힘을, 적에게는 깊은 좌절을 불러일으킵니다.\n오래 전부터 카르멘은 싸움으로 자신의 손을 더럽히는 대신 인간들과의 공존을 추구해 왔습니다. 하지만 그 방법은 그림자라는 근본적인 한계에서 벗어나지 못했고, 구 관리국과의 교전 중에 핵이 파괴되는 치명상을 입은 끝에 오랜 시간 자취를 감췄습니다.\n다시 나타난 카르멘은 인간들을 다루는 데 보다 능숙해졌고, 그만큼 더욱 위험한 존재로 거듭났습니다. 그녀의 친절에 속아서는 안 됩니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
