L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_CA_MARIA"
L9_1 = "가르강튀아를 기동시킨 마리아 안토노프는 아군을 전방에 빠르게 이동시키거나 적을 기절시키는 능력으로 전선 유지에 능한 레인저입니다.\n강습형 시공 가속기, 가르강튀아는 마리아 안토노프가 지닌 전이 능력과 연계해 그 위력을 극대화시켜 주는 전략 병기입니다.\n하지만 근본적인 설계 결함을 간직하고 있기 때문에, 사용자는 가르강튀아가 기동하는 동안 큰 부하를 짊어져야 합니다. 이를 상쇄하기 위해 연구진은 마리아가 전달한 생명공학 기술을 차용, 육체의 연령대를 변경함으로써 대응하였습니다.\n젊은 시절의 모습으로 나타난 마리아는 병사들에게 현대전의 여신으로 비춰지기에 충분합니다."
L7_1[1] = L8_1
