L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_KNIGHT_C_EMPEROR"
L10_1 = "클라레스 엘 아르카데나는 높은 기본 능력치를 바탕으로 다수 전투에서 두각을 드러내는 스트라이커입니다.\n\n용혈을 이은 아르카데나 제국의 황태자이자, 구원 기사단의 일원인 그는 문무를 겸비한 실력자였습니다. 일견 오만해 보일 수 있는 성격은, 쇠약한 황제를 대신해 정무를 돌보면서 고려할 필요 없는 부분임이 밝혀졌습니다. 백성들 역시 그의 통치 아래 제국이 어느 때보다 큰 번영을 이룰 것이라고 확신했습니다.\n하지만 제국의 역사는, 클라레스에게 평화의 시대를 이룩하도록 허락하지 않았습니다."
