L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DELTA_SYLVIA_RB"
L11_1 = "기기의 발전에 따라, 최근 프리랜서로 살아가는 해커와 크래커들은 발로 뛰어다니는 것이 트렌드입니다. 컴퓨터 앞에 가만히 엉덩이를 붙이고 있다간 삽시간에 창밖에서 총알이 날아들기 때문이죠.\n실비아에게도 마찬가지입니다. \n델타 세븐의 작전을 도울 때는 훈련 받은 정예 병력들과 각종 군수 자원 등 풍부한 지원이 이루어지지만, 개인적으로 몰래 활동할 때는 얘기가 다릅니다. 후드를 푹 눌러쓰고 네온사인의 불빛 속으로 사라져야죠.\n물론 그 뒷모습을 놓친 상대는 자신의 요새가 무너지는 꼴을 봐야 할 겁니다."
