L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_M_RAILGUN"
L12_1 = "그렌델은 배리어로 보호 받는 적에게 강력한 위력을 발휘하는 스나이퍼입니다.\n병기 개발국이 개발한 「심판의 망치」는 일부 침식체들이 형성하는 방어 역장을 파훼하기 위해 산악지대에 설치된 레일건이었습니다. 하지만 북방 합의체는 이 막강한 화력을 보다 다양한 국면에서 활용하길 바랐고, 그 기대에 부응한 산물이 바로 그렌델입니다.\n이 투박한 외형의 다족 보행 병기는 심판의 망치를 운용하기 위한 플랫폼으로서 설계되었습니다. 한계로 지적 받던 전력 소모 문제를 에너지 실린더로 극복한 이후, 그렌델은 국경을 지키는 감시자 역할을 훌륭하게 수행하고 있습니다."
