L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DREAM_C_NIGHTMARE"
L13_1 = "루루 나이트메어는 적의 버프를 해제하고, 다수의 유닛에게 수면을 거는 서포터입니다.\n악몽 속에서 떨고 있는 꿈의 주인을 구해주는 건 다름 아닌 한 소녀입니다. 루루는 매일 밤 사람들이 꾸는 악몽 속으로 들어가 악몽을 거둬 갑니다.\n본래 악몽 그 자체인 그녀는 악몽의 힘을 강하게 만드는 대신 직접 거두며 사람들이 편안히 자도록 돕습니다. 그것이 호의가 아닌 참회라고 믿으면서요. 오랜 기간 홀로 떠돈 덕분에 세상 물정 모르는 순진한 면모를 보이면서도, 마음 넓고 인자하게 주변 사람들을 챙겨주곤 합니다.\n한편, 많은 인간을 희생시켰던 한 존재가 다시 깨어남과 동시에 정신을 잃었던 일은 그녀의 존재에 의문을 품게 만듭니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
