L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_VATICAN_C_BOOK"
L14_1 = "종이를 자유자재로 다루는 비블리데 루체는 기본 공격에 충실한 레인저입니다.\n한때 기적심의회의 일원이었던 그녀는 모종의 이유로 성황청 도서관 사서직에 지원했습니다. 함께 일했던 사서들은 그녀가 독서에 몰두하는 이유가 촉매로 쓸 책을 찾기 위해서라고 확신합니다.\n낡은 종이도 새것처럼 만들 수 있는 능력과 방대한 지식은 고서 관리가 주된 업무인 성황청 도서관에게 반가운 재능이었습니다.\n주위에서는 심의회 시절부터 이어진 엄격하고 냉정한 성품 탓에 어울리기 힘든 사람이라고 평가하기도 합니다. 하지만 한편으로는 사비를 털어 보육원에 그림책을 기부하거나, 집안 사정으로 학교에 가지 못한 아이들을 가르쳐 주는 등 배움에 목마른 이들을 외면하지 않는 일면도 존재합니다.\n최근 성황청에서 벌어졌던 사건을 계기로, 은퇴를 번복하고 심의회에 복귀하였다는 첩보를 확보하였습니다."
