L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_YG_SORIM_RA"
L15_1 = "관리국 카운터 아카데미는 매년 외부인 입장이 가능한 축제를 개최합니다. 카운터에 대한 인식을 보다 긍정적으로 개선하기 위해, 축제 중에는 학생들의 능력을 활용해서 화려한 공연이 펼쳐집니다.\n올해 주목 받는 공연은 「강하하라! 애니멀 레스큐 스페셜 포스!」입니다. 베테랑 요원 「심판의 방아쇠」와 터프한 「스미스 병장」의 화약 냄새 물씬 풍기는 활약극을 기대해 주세요.\n주연 토끼 대원들의 연기는 고등부의 염동력 능력자 학생들이 기꺼이 협조해 주었습니다. 스미스 병장이 물구나무 선 채로 전사하는 장면에서는 진심으로 애도를 표했다더군요. "
