L16_1 = "큐리안은 병사들과 함께 출격하여 지휘전술로 아군을 이끄는 공격적인 스나이퍼입니다. \n총사대는 강력한 카운터들로 구성된 노르드나빅의 왕실 특무 조직입니다. 그들은 각자 자신만의 별동부대를 이끌며 왕실의 명령을 수행했고, 제라드 큐리안도 그 중 한 명이었습니다. \n침식의 날 이후 실종된 것으로 알려졌던 그는 최근 다시 왕립군의 일원으로 활동하며 국가의 최전선을 지키고 있습니다."
