L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BORDER_S_HUNTER"
L17_1 = "워든은 적에게 높은 피해를 주는 동시에 방패 전술로 생존력을 높인 스나이퍼입니다.\n노르드나빅 왕실의 명령을 따르는 이 사격부대는 대형 침식체로부터 방어선을 지키기 위해 만들어졌습니다. \n경량형 파비스와 함께 사용하는 신비한 총 청동 가지는 특정 아티팩트를 모방한 레플리카에 불과하지만, 고등급 침식체에게도 유효한 피해를 줍니다. \n다수가 하나의 약점을 집중적으로 공략하는 일제사격 전술을 주로 사용합니다."
