L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BORDER_C_BOWGUN"
L18_1 = "엘라는 CRF로 충격을 흡수하고 그 힘을 광자로 전환시키는 반격형 스트라이커입니다.\n엘라는 노르드나빅 남부 국경수비대의 군인입니다. 그리고 부대에서 유일한 카운터이자 하나뿐인 의사이기도 합니다. \n그녀는 전투를 제외한 대부분의 여가시간을 화살을 깎으면서 보냅니다. 말수가 적고 규율에 엄격하며 항상 무뚝뚝한 표정을 짓고 있어서 대하기 어렵게 느껴집니다. 함께 일하는 대원들조차 그녀가 웃는 모습은 거의 본 적이 없습니다. \n하지만 대원들은 그녀가 차가운 사람이라 생각하지 않습니다. 위기에 처한 사람을 보면 뛰어들고 보는 헌신, 배고픈 이에게 베푸는 정성 어린 감자 요리가 그녀의 미소를 대변하고 있으니까요."
