L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_TITAN_RA"
L19_1 = "젊은 과학도들은 퓨처 앳 워 프로젝트를 학문의 이상향처럼 여깁니다. 하지만 전시 상황이란 배경과 각국의 이해관계가 얽힌 가운데, 출신도 배경도 다른 사람들이 모여 편하게 연구에만 집중할 수 있었을 리는 없습니다.\n주피터 파일은 퓨처 앳 워의 연구진이 여러 현실적인 제약으로 포기해야 했던 시제안들입니다. 그 중 3종은 모두 주요 무인 병기들의 전력 강화를 위해 입안되었습니다.\n트리아이나 플랜은 타이탄의 성능을 원본에 보다 근접하게 만드는 개량안입니다. 증설된 복합 장갑과 캐니스터식 대공포탄은 다양한 상황에 대처 가능하며, 포화를 뚫고 접근한 적에게는 치명적인 위력의 능동 방호 체계가 기다리고 있습니다. 계획 수립에 관여했던 세르게이 체르노프 교수는 자신의 연구 노트에 다음과 같은 메모를 남긴 바 있습니다.\n─「우리의 아이들은 전쟁을 모르는 시대에 살길 바라며.」"
L17_1[1] = L18_1
L17_1[2] = L19_1
