L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_RAS_MA_TOWER"
L21_1 = "시그마는 무지 강력한 펀치와 멋지고 화려한 빔으로 적을 제압하는 스트라이커야! \n안녕! 난 시그마! 여기에 자기소개를 적으면 되는 거지? 시그마는 아빠가 만든 굉장한 딸이야. 그리고 풀파워를 사용할 수 있는 지금은 굉장히 세고 멋진 딸이라구.\n테라브레인의 출력에는 한계가 없어! 엄청나게 많은 일을 처리하도록 만들어져서 전력공급만 있으면 얼마든지 강해질 수 있단 말씀! \n...초기형 모델만 리미트를 고려하지 않고 만들어져서 그런 거라고? 아, 미안! 내 기능 설명서를 잠깐 살펴봤어. 어쨌든 시그마는 지금 존재하는 테라브레인 친구들 중에서도 가장 대책없이 강하대! 자기소개 끝! 이제 아빠랑 놀아달라고 하러 가야지!"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_OZ_M_PUPPET"
L22_1 = "허수아는 적 디버프를 통해 아군을 도우며 지속적인 공격으로 자신을 강화하는 레인저입니다.\n소녀는 과거 불의의 사고에 휘말려 식물 인간이 되었습니다. 다행히 AI 「Nic. Chopper 001」를 기반으로 한 뇌 보조 장치를 제공받아 이전처럼 친구를 포옥 안아 줄 수 있게 되었죠.\n뇌의 기억에 의지해 움직이기 때문에 감정 표현에 있어 어색한 모습을 보여주기도 합니다. 그래도 괜찮습니다. 친구들은 디스플레이에 뜬 이모지를 보고 무슨 생각을 하는지 알아챌 수 있으니까요.\n그게 누구의 감정인지는 조금 더 지켜볼 필요가 있겠지만요."
