L22_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_C_CHESS"
L23_1 = "갬블러는 적을 약화 시키는 방해형 서포터입니다. 일정 확률에 따라 약화 효과는 더욱 증가합니다.\n언더그라운드 카지노의 유명 인사인 갬블러는 승부에서 이기기 위해서라면 수단과 방법을 가리지 않습니다. 그래서 그녀가 벌이는 승부에는 항상 구경꾼이 꼬이곤 합니다. 이번에는 무엇을 걸지, 결국 누구에게 패하게 될 지 궁금해 하면서 말이죠.\n그녀의 정체에 대해서는 밝혀진 바가 없습니다. 부잣집 규수 같은 외모로 막대한 돈을 휘두르는 그녀가 카지노에 모습을 보이기 시작한 시점이 알파트릭스 회장의 사망 시점과 맞아 떨어져, 어쩌면 경영권 분쟁에서 밀려난 신씨 일가의 일원일지도 모른다는 소문만이 무성할 뿐입니다.\n비밀 루트를 통해, 그녀가 최근 세실리아 신이라는 위장 신분으로 베타트릭스 컴퍼니라는 유령회사를 설립하였다는 사실이 확인되었습니다. 그녀가 어떤 목적으로 회사를 설립하였는지, 누구의 도움을 받았는지는 분명하지 않습니다.\n다만, 자신만의 갬블에서 승리를 취하기 위해 그녀가 펼친 오프닝인 것은 틀림없습니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_GREATSWORD_RB"
L24_1 = "실패의 기준은 목표를 달성했는지에 따라 달라집니다. 연구자들이 갈구했던 가장 이상적인 결과물에 부합하지는 않았겠지만, 그들 역시 목표에 눈이 먼 나머지 인간이 성장하면서 변화한다는 당연한 사실을 간과했습니다. 처음부터 완벽한 존재는 없으니까요.\n알렉스의 전투 기술은 적을 쓰러뜨리기보다 동료들을 지키기 위한 방향으로 발전하고 있고, 앞으로도 발전할 겁니다. 섬세한 손끝이 자아내는 소리가 피보라를 일으키지 않아도 될 그날까지 말이죠."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GEASS_MA_SEITEN"
L25_1 = "코우즈키 카렌과 그녀의 홍련 성천팔극식은 복사파동을 사용하여 적의 생존력을 약화시키는 스트라이커입니다.\n카렌은 브리타니아인과 일본인의 혼혈이지만 스스로를 일본인, 코우즈키 카렌이라고 생각합니다.\n일본 독립을 위해 반란군 활동을 하던 카렌은 제로와 만나, 그녀의 뛰어난 능력을 인정 받고 흑의 기사단의 에이스로서 활약하게 됩니다.\n홍련 성천팔극식은 제9세대 나이트메어 프레임으로 노획된 홍련 가상식을 브리타니아의 과학자, 로이드와 세실에 의해 일반인은 다룰 수 없을 정도의 뛰어난 스펙의 기체로 개조되었습니다.\n강화된 철갑포격의 오른팔에서는 다채로운 복사파동 공격이 가능하며, 공방일체의 비행장치인 에너지 윙으로 전장을 지배합니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GEASS_C_LELOUCH_RA"
L26_1 = "를르슈 람페르지는 아군의 스킬 충전 속도를 지원하고 적들의 스킬을 봉인하는 서포터입니다.\n신성 브리타니아 제국의 제 11황자인 를르슈는 스스로의 복수를 위해 가면으로 정체를 숨기고 제로로서 조국에 반역을 일으켰습니다.\n그는 어떤 상대에게든 명령을 내릴 수 있는 초능력, 절대복종의 기아스와 브리타니아와 대등한 무력을 가진 흑의 기사단을 이끌며, 브리타니아와의 싸움을 시작했습니다.\n그가 천재적인 전략과 뛰어난 지휘능력 그리고 임기 응변을 통해, 수많은 승리를 거둔 것은 사랑하는 여동생 나나리가 안심하고 지낼 수 있는 세상을 만들기 위함이었습니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GEASS_M_LANCELOT_RA"
L27_1 = "C.C.와 랜슬롯 프론티어는 치명타 피해에 특화되어 지속적인 피해를 가하는 레인저입니다.\n의문의 소녀, C.C.는 를르슈와 계약하여 그에게 기아스라는 능력을 주었습니다.\n그녀가 를르슈와 계약한 목적은 알 수 없습니다.\n하지만 스스로를 공범자라 칭하며 를르슈의 반역에 가담하는 것을 보면, 무언가 중요한 이유가 있는 것이 분명합니다.\n랜슬롯 프론티어는 랜슬롯의 예비부품을 장착한 C.C.의 전용 나이트메어 프레임입니다.\n본 기체는 랜슬롯의 기본 무장을 충실히 계승한 한편, 콕핏의 사출 기능이 추가되어 파일럿의 생존성을 보장합니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SECURITY_C_SERGEANT"
L28_1 = "크리스는 적과 거리를 상시 유지하는 것으로 생존력을 확보한 지원형 레인저입니다. 궁극기를 사용함으로써 범위 내 적들에게 불규칙한 피해를 가하며 코스트를 회복할 수 있습니다.\n크리스티나 브레히트 중사는 그로니아가 건국된 이래 살아서 무공훈장을 받은 유일한 사례입니다. 비록 징집병 신분으로 훈련도 제대로 못 받고 최전방에 투입되었지만, 어떤 치열한 전투에서도 생환하여 상관들을 경악하게 했습니다. 특히 정부군에게 악몽 같았던 춘계 전투 중 중사에게 구조된 부상자들 중에는 고위 장교들도 있었습니다.\n정부군은 소녀를 전쟁사에 남을 영웅으로 선전하면서 병사들의 사기 진작을 꾀했습니다. 그리고 보안국으로 임시 배속된 현재, 그 선전은 노골적인 프로파간다 이상의 의미를 지니게 되었습니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_C_SNIPER"
L29_1 = "아그네스 아비게일은 기본 공격으로 적의 능력치를 영구히 감소시키는 표식을 부여하는 스나이퍼입니다.\n발렌티누스 수도원의 명맥을 잇는 아그네스는 불경한 목적으로 수도원에 침입한 자들을 처단해 온 파수꾼이었습니다. 한편으로는 비밀스러운 의식에 바칠 희생양을 선별하는 사냥꾼이기도 했습니다.\n그리고 침입자에게서 지켜야 할 수도자들도, 산제물을 필요로 하는 의식도 시간의 안개 저편으로 사라진 지금. 아그네스는 수도원에 남아 항상 누군가를 기다리고 있습니다. 그 누군가란 수도원에 잠든 금지된 지식을 노리는 자일 수도 있고, 에그타르트를 대접해 주고 싶은 손님일지도 모릅니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ESPR_PILE_RA"
L30_1 = "학회에는 무언가에 미쳐 있는 인간들이 많습니다. 그런 측면에서 리벳은 학회와 놀랍도록 잘 어울리는 인물입니다. 스릴을 위해서라면 어떤 위험 속으로도 기꺼이 뛰어들고, 현실에 안주하는 대신 매번 새로운 스릴을 찾아 나서기 때문이죠.\n리벳의 출신은 학회에 온 뒤에도 여전히 베일에 싸여 있습니다. 이따금 풀어 놓는 인생 역경은 하나같이 기상천외한 것들뿐이므로 평가에 도움이 되지는 않을 것입니다. 경영학부는 이 때문에 그녀에게 맡겨진 고유무장을 회수하길 강력하게 주장했으나, 결국 학회장 선에서 반려되었습니다.\n학회에서 수수께끼의 인물이란 잠재적인 위협이 아니라 새로운 탐구 소재이니 말입니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_S_DOCTOR"
L31_1 = "애콜라이트는 자신의 체력을 소모해 아군을 회복해 주면서, 사망 시 적에게 해로운 영향을 끼치는 서포터입니다.\n애콜라이트란 학회의 최전선에서 새로운 지식을 탐색하는 연구자들이요, 지식의 탐구를 방해하는 무지한 자들을 내쫓기 위한 비밀스러운 창칼입니다. 복식은 여느 학회원과 동일하나, 가면 너머에는 더욱 위험하고 신비로운 실체가 숨겨져 있습니다.\n이들을 제공하는 책무는 의학부에 있습니다. 의학부는 주로 영지의 주민들이나 학회에 헌신하길 원하는 외부인들 중에서 지원자를 차출됩니다. 헌신을 거부하는 이들도 호수의 파편과 접촉하면 어김없이 자신의 뜻을 되돌리고는 합니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_CA_FROZEN"
L32_1 = "종신 학회장 레지나 맥크레디는 적을 빙결시킨 후 영구적으로 증가한 공격력으로 치명적인 공격을 가하는 레인저입니다.\n에크하르트 초월지식 학회는 오랜 세월에 걸쳐 세력을 확장해 온 음모론적 조직입니다. 호수에 대한 광기로 수많은 적을 만들었고, 그럼에도 역사 속에서 여러 이름 뒤에 숨어 끈질기게 명맥을 이어 왔습니다.\n그리고 이제, 학회는 새로운 지도자와 새로운 시대를 앞두고 있습니다. 변화를 몰고 올 폭풍은 살을 에듯 차고 고통스러울지 모르나, 결국 누구도 거부할 수 없게 될 것입니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_C_TRUMPET"
L33_1 = "루나는 전장에 있는 아군들의 피해를 대신 흡수하고 배리어를 생성해 주는 공중 디펜더입니다. \n그녀는 엘리시움 필하모닉의 금관악기를 담당하는 대표 단원입니다. 처음엔 빈자리를 급히 채우기 위한 임시 단원이었으나, 뜻밖의 연주 실력을 뽐낸 덕에 지휘자의 인정을 받았습니다.\n유달리 자주 죽는 탓에 힘을 비축할 여력이 없는 최약체 그림자임에도 최고 단원 자리를 지킬 수 있었던 이유는 그 자릴 지켜서 살아남겠다는 일념 덕분입니다.\n그녀는 살기 위해 인간들 앞에 무릎 꿇는 행위도 서슴지 않습니다. 음식에 남다른 애착을 가지는 것 또한 그녀가 그림자로서 무엇에 집착하는지 쉽게 알아챌 수 있는 대목입니다.\n인간을 쉽게 증오하지 못하고 갈팡질팡하는 이유도 거기에 있을 겁니다. "
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_KIM_CHEOLSU_RA"
L34_1 = "가정의 안녕과 평화를 수호하는 월급쟁이 히어로, 샐러리맨X!\n사실, 그의 정체가 평범한 중소기업의 만년 과장이었다고!?\n우연한 사고에 휘말려 카운터로 각성해버린 그는 지금 히어로 활동과 회사 생활을 병행 중! 그의 마스크와 무장은 그가 손수 제작한 것으로 별다른 기능은 없지만 가족들의 신변을 보호하기 위해 자신의 정체를 감추기 위해 사용한다.\n그에게는 막대한 부도, 막강한 초능력도 없지만 이 시대를 살아가는 모든 가장이야말로 영웅이 될 수 있다는 것을 증명하기 위해 오늘도 묵묵히 그만의 출근길에 오른다.\n※이상의 서술은 「카운터즈 사가」에 동봉된 설정집에서 발췌하였습니다."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GAMECIRCLE_C_STAR"
L35_1 = "빠샤! 미리네는 각각 다른 효과의 무기들을 바꿔가며 싸우는 스트라이커라구요!\n본작의 주인공인 천진만만한 여고생! 어느 날 이런저런 이유로 카운터로 각성해버린 미리네는 세 가지 무기, 불꽃으로 베는 플레임 소드, 냉기를 뿜는 블리자드 액스 그리고 번개를 뿌리는 스톰 해머를 자유자재로 다루며 스타라이트의 가호를 받은 마스터 소드를 찾기 위한 여정길에 오르게 되는데……!\n어딘가 어설픈 구석도 있지만, 친구들을 소중히 생각하는 마음과 선생님을 좋아하는 마음, 그리고 꿈을 이루기 위한 열정은 누구에게도 지지 않는다고요!\n※이상의 서술은 「카운터즈 사가」에 동봉된 설정집에서 발췌하였습니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_SETSUNA_RA"
L36_1 = "자기 세계를 잃은 신은 뒤틀리고 맙니다. 돌아갈 곳을 잃은 인간도 예외는 아닙니다. \n하지만 때로는, 아무도 눈여겨보지 않은 한 떨기의 벚꽃이 새로운 나무를 싹 틔우기도 합니다. \n나나하라 치나츠는 신의 혈통이 가진 힘을 통해 꽃을 피워내고 생명을 치유합니다. 죽어가는 존재를 되살리고 주어진 운명의 순환을 바꿉니다. \n지키고자 하는 작은 세계를 위해, 그녀는 자신이 가진 가능성의 시험을 두려워하지 않을 것입니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
