L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_CA_SENHIME"
L37_1 = "역신베기의 나나하라 치후유는 적을 약화시키고 피해를 받을수록 강력해지는 스트라이커입니다. \n나나하라류는 검의 달인이었던 명부신의 검술을 모방하여 만들어진 비기입니다. \n가문연합의 선조들은 모방이라는 한계를 넘어 검술을 완성하기 위해 오랫동안 노력했지만 결실을 맺지 못했습니다. \n누구보다 빠르고 강하며, 죽음조차 두려워하지 않는 존재를 한낱 평범한 운명의 인간이 따라잡는다는 것은 불가능해 보였습니다. 선조들은 역신베기라 불리는 신기를 완성할 수만 있다면, 그것이 해답이 되리라 믿었습니다. \n시련 끝에 신의 검을 손에 쥔 그녀는 종말이라는 운명을 베고 나아갑니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FALLEN_CA_ROSARIA"
L38_1 = "아스모데우스 로자리아 르 프리데는 단일 대상에게 더욱 압도적인 피해를 입히는 스나이퍼 입니다.\n그녀는 과거 무자비하고 과격한 성향으로 자신을 방해하는 자들을 모두 잿더미로 만들었습니다. 잿가루와 함께 무성한 소문으로 퍼져나간 그녀의 존재는 온 세상에 악명을 떨쳤습니다. 북의 폭군, 잿더미의 여왕 같은 이명으로 불리며 수많은 이들의 도전을 받았지만, 고작 검 한 자루를 쥔 그녀를 적대한 자들은 모두 살아남지 못했습니다.\n이윽고 자신을 위협하는 자들이 사라지자 그녀는 자신의 왕좌에서 일어나, 자취를 감췄다고 전해집니다. 분명 자신을 만족시켜 줄 수 있는 강한 상대를 직접 찾아 나선 것이겠죠."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_KNIGHT_CA_SAVIOR"
L39_1 = "네헤모트 레이는 자신과 후열 아군이 받는 공격을 반격하여 아군 보호에 특화된 디펜더입니다.\n머나먼 과거, 제국의 평민 출신이었던 한 소년은 우연한 계기로 구원자가 되어 기사단과 함께 세상을 구원하기 위한 여정을 떠났습니다. 제국의 신민들은 그와 기사단이 세상을 구할 것을 의심치 않았고, 소년 또한 구원을 자신의 책무로 삼았습니다.\n오랜 시간이 지난 후, 결국 제국은 멸망하였고 그가 구할 신민조차 더는 남지 않게 되었지만, 소년은 세상을 구하려는 여정을 포기할 수 없었습니다. 자신에게 구원을 바랐던 이들의 기대를 결코 헛되이 할 수 없었기에.\n그리고 또다시 오랜 시간이 지난 지금, 한때 구원자라 칭송받던 상냥한 소년은 마침내 깨닫고 말았습니다. 구원을 향한 여정의 끝은 스스로 침략자가 되어 다른 세계를 멸망시켜버리는 것뿐이라는 것을."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_GAEUN_RA"
L40_1 = "처음에는 한 사람을 만나기 위해서 시작한 방송일 뿐이었을지도 모릅니다. 하지만 하트베리에서의 방송 활동을 통해 가은은 점점 리더로서의 재능을 드러내기 시작했습니다.\n루미의 넘치는 자신감과 보미의 느긋한 여유로움, 그리고 미야의 오랜 방송 경험…. 각자 개성 강한 맴버들 사이에서 그들의 매력을 아우를 수 있는 카리스마를 얻게 된 것이죠.\n방송에서도, 그리고 무대 위에서도 가은의 리드는 자신이 앞에 서지 않더라도, 맴버들 각자의 능력을 최대한 끌어냅니다.\n덕분에 최근 하트베리는 메이저에서 주목할만한 아이돌 그룹으로 스텝 업 했다는 평가를 받고 있죠.\n아직 다른 맴버들에 비해 춤과 노래는 서툰 편이지만, 이제 가은은 스포트라이트를 받으며 오늘도 팬들을 향해 환한 미소 지을 수 있습니다.\n언제, 어디서든 자신의 가장 큰 팬인 선생님이 지켜봐 주신다는 걸 알고 있으니까요."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GAMECIRCLE_C_VIOLET"
L41_1 = "방해해요, 적의 스킬. 그리고... 전열 유닛을 견제하는 스나이퍼에요... 저는요.\n미리네가 마스터 소드를 찾기 위한 여정에서 만난 두 번째 친구. 진보라는 카운터즈 사가의 엔딩을 보고 난 뒤 2회차 플레이부터 해금되는 플레이어블 캐릭터에요.\n느긋하고, 앞뒤를 잘라먹는 말버릇 때문에 4차원이라고 오해받지만, 사실은 전파를 다루는 능력 때문에 남들보다 훨씬 예민한 감각을 지니고 있어요. 이 능력을 활용하여 보라는 직접 튜닝한 기타로 전파를 증폭시켜 선생님과 친구들을 전력으로 서포트해요.\n평소에는 무심한 듯 자기주장을 내세우지 않는 보라지만, 한편으로는 미리네를 경쟁 상대로 의식하고 있어서 승부를 걸어오면 절대 물러서지 않는다고요!\n※이상의 서술은 「카운터즈 사가」에 동봉된 설정집에서 발췌하였습니다."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JUNIOR_C_POLEARM_RA"
L42_1 = "한때 명랑하고 밝았던 소녀는 어느날 예고없이 주어진 힘 때문에 힘든 시기를 겪어야했습니다. 자신의 힘 때문에 누군가 다칠까봐 친구사귀기를 멀리했고, 힘을 억누르기 위해 혼자서 식물을 가꾸며 스스로를 화원에 가뒀습니다. 하지만 그 힘이 곤경에 처한 사람들을 구하고, 친구를 도울 수 있다는 사실을 알게 됐을 때, 소녀는 그 힘을 더 이상 숨기지 않기로 했습니다. 아직 진짜 히어로는 아니지만, 사람들이 원하는 사람이 되고 싶으니까요."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FENRIR_C_INTERN"
L43_1 = "노엘은 관통 공격을 가하는 투사체를 조종하여 변수를 만드는 스나이퍼입니다.\n펜릴 소대에 새롭게 입대한 직원으로, 공중에서 자유자재로 움직이는 바즈라라는 무기를 활용해 적과 싸웁니다. 상급자는 노엘이 -2만큼, 바즈라가 12만큼 쓸모가 있다고 평가했습니다.\n넷튜브 영상을 보고 펜릴 소대의 열렬한 팬이 되었으며, 소대에 대한 애정만큼은 어느 누구에게도 지지 않습니다. 월급은 대부분 절판된 펜릴 소대 굿즈를 구입하는 데 사용하고 있다고 합니다. 낭비벽이 우려되므로 상급자의 각별한 지도가 필요합니다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_CA_ARTILLERY"
L44_1 = "크레스니크 류드밀라는 적의 스킬 사용을 방해하는 데 능숙한 서포터입니다.\n아티팩트를 통해 특수한 조정을 거친 그림자이자, 공식적으로는 최초로 인류와 연대한 침식체입니다. 그 본질에 걸맞게, 전투복처럼 보이는 외장 역시 침식파에 의해 정착된 일종의 갑피라고 할 수 있습니다.\n데모고르곤으로 추정되는 그림자로 거듭나면서 본래 활용하던 아공간은 이전보다 규모와 활용성이 확장되었습니다. 이 아공간은 고유한 섭리를 지닌 별개의 세계처럼 기능하여 적에게 치명적인 환경을 조성합니다.\n크레스니크라는 별칭은 민담 속의 흡혈귀 사냥꾼에서 비롯되었습니다. 그들은 흡혈귀와 태생이 동일하지만 아주 작은 차이로 인해 흡혈귀의 적수로 거듭난다고 전해집니다. 그것은 류드밀라 자신의 바람인 동시에, 그녀를 신뢰하는 이들의 바람이기도 합니다. "
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CANARY_S_SHIELD"
L45_1 = "펠리세트는 에어본을 통해 적을 무력화시키며, 라이카와 시너지를 내는 디펜더입니다.\n카나리아 스쿼드를 이끄는 작지만 믿음직스러운 소대장입니다. 어린 나이에도 무거운 방패를 자유자재로 다룰 만큼 실력이 뛰어난 대신, 성질머리도 그만큼 앙칼집니다.\n자신의 신체적인 한계를 잘 알고 있기 때문에, 밤낮으로 체력 단련과 훈련에 매진하는 모습이 자주 보입니다. 수면 시간이 부족하면 성장에 지장이 올 수 있으므로, 보호자의 각별한 주의가 필요합니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CANARY_S_ASSAULT"
L46_1 = "라이카는 버프로 자신의 공격 능력을 강화하며, 펠리세트와 시너지를 내는 레인저입니다.\n샤레이드의 하수구와 뒷골목에 자리 잡고 사는 생물은 쥐와 바퀴벌레만이 아닙니다. 라이카 역시 어떤 이유에서든 사회를 피해 음지로 숨어 든 그런 부랑자들 중 한 명이었습니다. 펠리세트와 만나지 않았다면, 그녀는 지금도 그 어둡고 습한 곳에 머물고 있을 겁니다.\n거친 말투와 자포자기식의 행동을 일삼기는 하지만, 때때로 엿보이는 날카로운 면모는 그녀가 여느 부랑자들과 달리 삶을 포기하지 않았음을 증명합니다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_C_KNIGHT_AP"
L47_1 = "레베카 카트린느는 자력을 활용하여 메카닉 유닛에게 위협적인 피해를 주는 원거리 스트라이커입니다.\n「델타 세븐 : 패스파인더」의 선봉대를 맡고 있는 그녀는 다른 세계로부터 온 방문자입니다.\n비공식적인 카운터 양성 계획의 피험체였던 그녀는 연구 시설이 폐쇄된 후, 간신히 혼자 살아남았습니다. 카운터로서의 능력은 그다지 뛰어나진 않지만, 전투 센스가 좋은 편이라서 자력을 증폭시키는 배트를 통해 고철을 끌어모으거나 방출하는 등 스타일리시한 방식으로 전투에 활용합니다.\n평소 야구에 열성적인 관심을 보이며, 자신의 세계에서는 자이언츠가 세계 최고의 팀이었다고 주장하지만, 이는 진위여부를 확인할 수 없는 사실이었습니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
