L47_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_CA_KYLE_AP"
L48_1 = "미네르바 카린 웡은 강화 방벽과 대상을 관통하는 레이저로 적의 공세를 차단 및 피해를 입히는 레인저입니다.\n「델타 세븐 : 패스파인더」의 지휘관인 그녀는 상처 입은 세계에 마지막 남은 대원이었습니다.\n그녀의 오른쪽 눈에 깃든 글라우코피스는 지금은 멸망한 세계의 기술로 만들어진 고유 무장입니다. 이 무장은 그녀의 분석 능력을 극도로 끌어올려 줄 뿐만 아니라 로스트 쉽 아이기스와 직접적으로 연결되어 있습니다. 따라서 그녀는 별도의 조작 없이 함선을 자유자재로 통제할 수 있고, 아이기스의 무기고에서 각 전황에 적합한 첨단 장비들을 호출하여 그 성능을 십분 발휘할 수 있게 되었습니다.\n한때, 동료들을 잃고 교차로에서 주저앉을 수밖에 없었던 소녀는, 이제 멸망한 세계의 의지를 이어 자신만의 길을 개척할 힘을 손에 넣었습니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCHOOL_C_STAFF"
L49_1 = "시엘은 창 막야를 휘둘러 적의 공격을 튕겨내고 후열을 습격하는 공격적인 암살자이자 스트라이커입니다.\n성실한 모범생을 꿈꾸지만, 정작 수업 시간에 깨어있는 모습은 보기 힘든 야행성 소녀입니다. 아카데미에 입학할 당시의 그녀는 친구라는 단어도 모를 정도로 사회성이 전무했지만, 지금은 학생들의 도움으로 사소한 일상생활부터 배워나가는 중입니다.\n그녀는 한 도시를 휘어잡고 있는 암살 문파의 수장이지만, 그걸 딱히 숨기려는 노력은 하지 않습니다. 처음엔 진지하게 받아들이는 학생도 있었죠. 하지만 부탁을 거절하지 못하고 거짓말도 할 줄 모르는 순진한 그녀를 진짜 암살자라고 굳게 믿는 사람은 없습니다.\n혹시 낮 동안에 그녀가 화난 듯한 표정을 짓고 있다면, 그건 눈앞에 있는 물체를 좀 더 또렷하게 보기 위한 행동이니 당황하지 마세요."
L47_1[1] = L48_1
L47_1[2] = L49_1
