L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_C_SWORD"
L50_1 = "람다 스파타리는 적의 체력 상황에 따라 더 강력한 피해를 입힐 수 있는 레인저입니다. \n조니 앤 멜로니의 대표 람다 스파타리는 변호인으로서, 정재계의 유력 인사들을 위한 각종 업무들을 수행하고 있습니다. 언뜻 보기엔 주변인들과 척을 지고 살 것 같은 인물이면서, 어째선지 자신의 동생과 동료들에게는 높은 신망을 사고 있습니다. \n항상 냉정한 태도를 유지한 채 사람을 대하는 성격이지만, 사실 그녀의 내면을 지배하고 있는 것은 타오르는 열정입니다.\n그렇기에 매사에 비정한 자들과는 죽이 잘 맞지 않지만, 공동의 목표를 위해서라면 협력을 마다치 않을 것입니다. 공과 사는 구분해야 하니까요."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SCHOOL_CHAIR_RA"
L51_1 = "이디스가 어린 나이에 취미로 만든 발명품 몇 가지는 과학계에 큰 충격을 안겨주었습니다. 퓨처 앳 워는 그녀를 수석 로봇 공학자로서 정식으로 채용하려 했지만, 본인은 탐탁치 않아 했다고 합니다. 일방적인 타협 끝에 현재 그녀는 연구기관이 아닌 카운터 아카데미에 머물며, 퓨처 앳 워는 그녀의 취미활동을 위한 재정적 지원을 약속했습니다. 어쨌거나 사회는 그녀를 퓨처 앳 워의 일원으로 받아들이고 있으니까요."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_C_CHOWON_PR"
L52_1 = "김초원은 폭발물을 설치해 적의 진격을 방해하면서, 다수의 적을 제압하는 데 특화된 디펜더입니다.\n치외법권에서 활동하는 언더그라운드 용병들에게 폭발물은 어디서나 함께해 주는 든든한 우군입니다. 개인 화기로 맞서기 어려운 침식체를 격퇴하거나 두터운 격벽을 뚫고 들어갈 때 특히 안성맞춤이죠.\n그렇기 때문에 적의 손에 들려 있는 폭발물만큼 무서운 것도 없습니다. 하물며 그 적이 거미집에 숨어 사냥감을 매다는 거미라면 말입니다.\n전쟁은 많은 이들을 피폐하게 만듭니다. 그리고 어떤 자들은, 불행하게도 피비린내 나는 욕망을 발견하기도 했습니다."
L50_1[1] = L51_1
L50_1[2] = L52_1
