L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CHARADE_C_CRIMSON"
L3_1 = "오지만디아스는 출격과 동시에 적을 기절시키고 멀리 있는 적을 낚아채는 등, 적진을 무너뜨리는 것이 특기인 스트라이커입니다.\n그녀는 샤레이드 건틀렛 리그의 챔피언입니다. S급 카운터이면서 무패행진을 이어 온 결과, 그녀 한 명에게 할당되는 포인트는 매년 고점을 갱신하고 있습니다.\n그녀는 관리국의 지배력이 확고하지 않은 샤레이드를 대표하는 인물이기도 합니다. 사치스럽고 방탕한 생활을 이어가지만 파파라치들마저 잠잠하다는 지점에서, 오지만디아스와 거대 스폰서들의 연대를 엿볼 수 있습니다."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SECURITY_CA_SERGEANT"
L4_1 = "그리핀 라이더 크리스티나 브레히트는 적을 약화시키며 궁극기 사용시 자신을 강화하는 서포터입니다.\n브레히트 중사는 그로니아 무공훈장의 수훈자로서, 반군과의 내전에서 혁혁한 전공을 세운 바 있습니다. 전선에 있는 병사들에게 크리스 중사와 함께하는 전투는 영광을 향한 도전으로 받아들여졌습니다.\n이제 그녀는 최신예 병기 그리핀 유닛과 함께 전우들에게 희망의 상징이 될 각오를 마쳤습니다. 극초음속으로 조국의 영공을 누비며 평화 그로니아 건설에 헌신할 그녀에게 영광 있기를!\n※이상, 그로니아 정부 선전기관의 공고에서 발췌한 내용입니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_C_BASSOON"
L5_1 = "플라가는 아군을 강화시키는 데 특화된 레인저입니다. 이 강화는 침식체와 엘리시움 필하모닉에게 더욱 강력한 효과를 발휘합니다.\n플라가는 엘리시움 필하모닉 내에서도 기피되는 연주자입니다. 이는 다른 단원들과 달리 내향적인 성향 때문이기도 하고, 죽음을 몰고 다니는 듯한 어두운 분위기 때문이기도 합니다.\n그렇기에 플라가의 연주는 언제나 다른 동료들 대신 비, 그리고 그림자와 어우러집니다. 음산하게 울려 퍼지는 콘트라바순의 뱃고동 같은 음색은 듣는 이에게 죽음을 갈망하게 만드는 마력이 깃들어 있습니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SHARKS_C_CANNON"
L6_1 = "프론트베이 출신의 해적이지만 아가씨스러운 외모를 가진 소녀. 해적의 낭만을 쫓아 바다를 찾은 탈리는 언제나 약탈할 상대를 공격할 준비가 되어 있습니다. 사실 약탈을 하지 못해도 대포만 쏠 수 있다면 괜찮습니다. 해적답게 누구보다 파괴본능이 강하고, 습격을 좋아하고, 폭발을 사랑하기 때문이죠. \n하지만 그녀가 용감한 전사라고 생각하진 마세요. 적들에게 둘러싸이는 순간 무기를 버리고 항복을 외칠 테니까요."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JOO_SHI_YOON_AP_RA"
L7_1 = "세계의 운명이 달린 마지막 결전을 앞두고, 「받은 만큼 일한다」는 모토를 잠시 내려놓은 주시영은 델타 세븐의 정식 대원으로 입대하였습니다.\n그녀에게 배정된 슈트는 멸망한 세계의 기술로 만들어진 것이며 공간 능력자에게 단거리 도약 능력을 부여합니다. 이를 통해 시영은 기예에 가까운 움직임으로 전장을 돌파하거나, 능력을 응용하여 최소한의 움직임으로 적의 공격을 반사하는 기술을 터득하였습니다.\n스스로 밝히지는 않았지만, 프리랜서 용병인 그녀가 결사항전을 택한 계기는 세계를 지키기 위해서라는 거창한 이유가 아닌 그저 친구의 등 뒤를 지켜주고 싶다는 일념일지도 모릅니다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_C_ARMS"
L8_1 = "레노어는 북방합의체 특수작전군 소속 간부입니다. 그녀는 자신의 친부가 연구하던 오라클 프로젝트에 목숨을 건 자원을 했고, 실험체들 중 유일한 성공 케이스가 되었습니다. 실험을 통해 자신이 원하는 미래를 볼 수 있게 된 그녀는 군 내부의 불순분자들을 제거하는 척살자 역할로 큰 공을 세웠습니다.\n예견에 의존한 활동을 하던 레노어에게 실패란 없었고, 그녀의 자만심은 날로 높아졌습니다. 그러다 자신이 계획하는 것들의 뻔한 결과엔 점차 흥미를 잃게 됐죠. \n새로운 자극을 찾던 그녀는 얼마 전 신념 있는 적을 짓밟으며 얻는 희열에 눈을 떴습니다. 어느새부턴가 그녀가 행하는 임무는 국가를 향한 헌신이 아닌 누군가의 몰락을 위한 쾌락주의 범죄로 변질되고 말았습니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SHARKS_C_KNIFE"
L9_1 = "소냐는 프론트베이 샤크스 해적단의 막내지만 가장 많은 일을 책임지고 있습니다. 주로 출항 전에 배를 점검하고, 가계부를 통해 예산을 관리하며, 해상에서는 요리를 맡고, 비상식적인 행동을 하려는 선원이나 선장을 중재하는 역할이죠. \n해적단에서 그녀는 상식인에 속하지만, 어디까지나 무법자입니다. 바다에서 포로로 붙잡히게 된다면 인정을 바라진 마세요. 당신이 해산물 요리를 좋아한다면  특히, 생선의 가치를 중요하게 생각하기 때문에 해산물 요리를 좋아하는 편이라면 그녀와 쉽게 친해질 수 있을 겁니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_CA_ARMOR"
L10_1 = "한때 성역 엘리시온을 수호하던 수호자이자 기사이자 모두가 섬기던 신앙의 주체. 모두가 그녀를 숭배하고, 그 믿음은 곧 힘이 되어 만민을 지킨다. \n그녀는 다가오는 종말의 위협을 계시했고, 엘리시움 필하모닉과 함께 역병의 어둠을 몰아내는 태양문을 세워 종말을 막고자 했다. \n에클레시아는 수많은 악단과 지휘자들을 거느렸다. 하지만 정작 자신은 연주를 하지 않았다. 악기는 마음을 표출하는 수단이오, 모든 이들의 듣는 자로서 그 마음의 뜻을 청취하는 것이 그녀의 본분이었기 때문이다. \n그녀는 음악을 좋아했으나 단 한 번도 자신을 위해 연주하지 않았다. 모두의 마음을 듣기 위해 살았다. 그렇기에 만민은 그녀를 위대한 정적이라 불렀다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_SPEAR_PR"
L11_1 = "줄곧 비밀 임무를 위해 메이드로 위장해왔던 그녀가 본업인 요원으로 돌아왔습니다.\n현재 관리국 정보부에 소속된 그녀는 마크 핀리의 지시 하에 잠입 임무를 수행 중인 것으로 확인되었습니다. 그들은 여러 국가 및 단체와 공조하고 있다는 정보 외엔, 소속된 다른 요원들의 신상과 임무에 관해선 밝혀진 바가 없습니다.\n현재 대외적으로 그녀의 모습이 노출된 상태인데, 다시 플로라 메이드로 돌아갈지는 미지수인 상태입니다.\n그러나 맡은 바 임무에 성실한 그녀는 관리국 요원으로서도, 그리고 한 사람의 메이드로서도 언제나 최선을 다할 것입니다."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BD_C_ROI_PR"
L12_1 = "멸망해 버린 세계의 유산, 프리드웬은 기관의 상징 그 자체이자 신성 침식체와 맞설 수 있는 대 신성 무장입니다.\n오랜 세월 학회와 대적하면서 버넷 가문의 구성원은 하나하나가 연결고리가 되어 방패를 대물림 해왔습니다. 버넷 가문이 몰락하고 로버트 버넷이 그 책무를 저버렸을 때, 많은 기관원은 전설이 막을 내렸다고 생각했습니다.\n하지만 지금, 주인을 잃었던 방패가 다시 한번 버넷의 손에 들어왔습니다.\n대대로 이어진 책무 그리고 스승의 의지를 짊어진 로이 버넷은 더 이상 수틀리면 주먹부터 내지르는 애송이가 아닙니다.\n스스로 결정한 선택의 책임을 지기 위해, 한 걸음씩 앞으로 나아가는 프리드웬의 새로운 전설입니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_CA_SHADOW"
L13_1 = "이브 마이트너는 에크하르트 초월지식 학회로부터 분파된 종교 집단의 숭배 대상입니다.\n그녀의 신자들은 반역자를 자처하며 호수의 파편을 회수하기 위해서라면 수단과 방법을 가리지 않아, 학회 이상의 과격 단체로 급부상하였습니다.\n순수한 아이의 모습을 하고 있지만, 그 본질은 형언할 수 없는 존재로부터 떨어진 독립 개체이며, 모체를 탐식하여 하나가 되어 완전해질 기회를 노리고 있습니다.\n모체로 추정되는 개체와 마찬가지로 그녀 역시 지식의 축적을 위해 탐식 행위를 하지만. 그녀의 경우, 새로운 정보의 탐식을 위해 사냥감을 동요시키거나, 극한의 상태로 만드는 등 잔혹한 성향을 보이는 것으로 확인되었습니다.\n마치 어린아이가 상상하지도 못한 방법으로 개미를 죽여 보는 것처럼 말이죠."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_RAS_MA_DINO"
L14_1 = "마음을 보는 셰퍼드와 거대 화력병기 러처는 언제나 함께 움직입니다. 적어도 러처가 전장에서 적과 아군을 분간해주길 바란다면 말이죠.\n겉으로 보면 셰퍼드는 러처에게 일방적으로 끌려다니는 것처럼 보입니다. 그리고 실제로도 끌려다니죠.\n하지만 둘은 어느 한 쪽이 명령을 내리지 않는 상호의존관계입니다. 공격성에 정도가 없는 러처가 선을 넘지 않도록 셰퍼드가 마음을 어루만져주니까요. 그리고 러처는 그런 따뜻함을 가진 셰퍼드에게 쓸모있는 존재가 되고 싶어합니다. 물론 이성보단 본능에 충실한만큼, 그녀가 던진 막대기를 쫓는 것이 더 중요할 때도 있겠지만요."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_C_SAW"
L15_1 = "국가 배반자로 낙인찍힌 집안에서 태어난 예니카는 햇빛 없는 실험실에서 자랐습니다.\n카운터로 각성하지 못했다면, 영영 그곳을 떠나지 못한 그녀의 남매와 같은 처지가 되었을 지도 모릅니다.\n그녀를 길러준 은사는 말합니다. 진작 폐인이 되었어도 이상하지 않을 그녀의 가혹한 과거사에 비하면, 지금처럼 밝은 모습이 된 것은 기적이라고 말입니다.\n그녀는 전장에서 위험에 빠진 타인을 위해 목숨 걸고 뛰어들며, 그렇게 번 돈의 대부분을 보육원에 적선합니다. 그런 그녀가 관리국의 선택을 받아 양지의 은총을 받게 된 것은 그저 우연이 아닐지도 모르죠."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_C_CRAFTER"
L16_1 = "나오는 옛 신의 자손으로, 교류를 싫어해 불가마에 틀어박혀 사는 소심한 대장장이였습니다. \n세상을 떠받치던 아버지의 권세가 무너지고 그녀의 세계가 꺼지지 않는 불길에 휩싸였을 때, 그녀는 아무런 준비도 없이 모든 책임을 이어받고 살아남은 이들을 이끄는 입장이 됐습니다. \n우연한 계기로 관리국과 조우하게 된 것은 그녀에게 천재일우의 기회였습니다. 덕분에 그녀는 사람들을 이끌 만큼 성장하게 됐고, 죽음을 두려워하는 신이란 불명예를 벗을 수 있었습니다. \n구 관리국이 와해된 뒤로 일선에서 물러나 자신의 대장기술을 이어받을 마땅한 인간을 찾아 떠도는 입장이지만, 세상이 위험에 빠진다면 언제라도 자신의 힘을 보탤 겁니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_CA_CAT"
L17_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n관리국 제4 수색전대 야크샤의 전대장, 앨리스 브레이드우드는 단거리 도약을 통한 가속 능력을 보유한 환상종 카운터입니다.\n정점에 다다른 그녀의 스피드는 관리국에서도 손꼽을 정도이며, 공간마저 도약하기에 누구보다 빨리 최전선에 도착하여 적들을 요격하는 화끈한 전투 스타일을 보여줍니다.\n전직 소방관이었던 앨리스는 관리국에 의해 스카우트된 후, 여러 작전에 기여하여 비교적 단기간에 전대장에 오른 인물입니다.\n규칙에 얽매이기 싫어하고, 화끈한 성격 탓에 지휘부에서는 관리국의 골칫거리라고 평가하기도 하지만 어떤 전장에서도 가장 먼저 뛰어들어 대원들의 목숨을 여러 차례 지켰기 때문에 관리국의 병사들에게는 무척 인기가 좋은 전대장 중 한 명입니다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_C_RABBIT"
L18_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n관리국 제4 수색전대 야크샤의 부전대장, 주디 스위프트는 빙결 조작 능력을 보유한 환상종 카운터입니다.\n그녀는 야크샤 전대를 설립한 초대 전대장과 가족과 같은 관계이며, 동시에 전대장이 부재한 동안 야크샤를 이끌어 온 실질적인 리더입니다. 이면세계의 최전선에서 오랫동안 생존한 베테랑 전대원답게 어떤 상황에서도 여유를 잃지 않으려 노력하지만, 그만큼 전우들의 희생을 직접 목격해왔기 때문에 적에게는 비정하고 냉혹한 모습을 감추지 않습니다.\n조상격이었던 환상종의 능력을 일부나마 재현할 수 있는 것으로 추정되며, 특이사항으로는 그녀가 생성한 얼음 결정이 주위 온도를 급격히 낮추기 때문에 원활한 작전 수행을 위해서는 작전 인원에게 방한용품 지급이 필요하다는 점입니다."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SABOTAGE_CA_SWORD"
L19_1 = "마브카는 북방합의체의 실험으로 탄생한 전투 병기입니다.\n신체의 모든 부위는 전투에 특화되어 있으며, 상당한 화력을 자랑합니다. 그녀의 동력원은 메모리 코어라는 특수한 장치입니다. 조사해 본 결과 인간 시절의 기억이 담겨 있는 것 같지만, 자신의 정체성에 대해 혼란스러워하는 모습을 보여, 그녀의 기억은 대부분 조작되어 있는 것 같습니다.\n자신의 본래 이름, 외모, 친하게 지냈던 친구들과의 기억. 어쩌면… 소년병에 입대했던 동기마저 조작된 것일지도 모릅니다.\n그녀는 친구의 워치를 이어받아 각성하게 되었습니다. 인간이 아닌 자가 카운터로 각성한 사례는 기존에 알려진 카운터의 규칙에 새로운 패러다임을 제시할지도 모릅니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_M_CYBORG"
L20_1 = "드레카바크는 마트료시카 인형이 되기 전에는 착하고 강인한 아이였다고 합니다.\n인형이 된 후에는 메모리 코어의 세뇌 장치가 통하지 않았으며,박사에게 반항하고 심지어 연구원을 살해하는 일까지 저질렀습니다.\n그녀는 언니와 함께 끔찍한 고문을 받아왔으며, 더 이상 경험해 보지 못한 고통이 없다고 말했습니다.\n드레카바크의 잔혹하고 무자비한 성격은 그 과정에서 생겨난 것으로 추측됩니다. 현재 그녀는 마트료시카 인형을 늘려, 가족으로 삼으려는 매우 뒤틀린 성향을 보입니다. 그 북방합의체조차 그녀를 경계하고, 무장까지 일부 해제시켜 놓았을 정도입니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CHAMBER_S_ENGINEER"
L21_1 = "스펜서는 오랫동안 이면세계를 탐사해온 탐험가입니다.\n주로 챔버의 대균열 지역에서 활동하면서 아티펙트를 수입원으로 삼는 그녀는 겉보기엔 돈을 목적으로 위험에 뛰어드는 흔한 보물사냥꾼처럼 보이지만, 과거엔 이터니움 정제액을 개발한 저명한 과학자이기도 했습니다.\n깊은 심도에서 살아남은 대가로 침식증후군을 짊어진 채 치료제에 의존하고 있지만, 금방 쓰러질 것 같은 몸을 하고서도 베테랑조차 꺼려하는 고심도 임무를 해내고 돌아오는 것이 그녀에겐 일상입니다.\n탐사비용을 제외한 수입원 대부분을 정보 수집에 투자하고 있다는 점으로 볼 때, 그녀의 탐사 목적은 단순히 돈이 아닐 가능성이 높습니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ROOT_CA_HUNTRESS"
L22_1 = "모드레드는 빛의 힘을 다루는 성자입니다.\n그녀는 어린 시절, 한 추기경의 눈에 띄어 그 직속 휘하로 거둬질 만큼 성자의 자질이 뛰어났습니다.\n출중한 사격 실력과 불의 앞에 나서고 보는 정의로움은 그녀가 팔라딘이 되길 원하는 교단의 기대에 부응하는 듯 했지만, 그 기대가 배반감으로 바뀌는 건 한순간이었습니다.\n한 차례의 실수로 중죄인이 된 그녀는 처벌을 앞둔 채 탈옥했고, 그 이후 엘리시온에서 그녀를 본 사람은 아무도 없다고 합니다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ROOT_C_DEMON"
L23_1 = "모르가나는 자기 몸집만한 무기를 들고 다니는 괴력의 성자입니다. \n침식의 영향으로 뿔을 갖고 태어난 그녀는 사람들에게 두려움 어린 시선을 받았습니다. 하지만 스스로의 존재를 인정받고 싶었던 그녀는 그늘에 숨는 대신 모두의 인정을 받기 위해 노력했습니다. \n그렇게 모르가나는 그루터기를 이끄는 조사단장이 되었고, 사람들은 뿔이 아닌 그녀의 존재 자체를 바라보게 되었습니다. \n위기 앞에서 늘 앞장서는 그녀의 대범함은 어른보다 어른스럽다는 인상을 주지만, 맛있는 포도의 유혹을 뿌리치지 못하는 모습은 영락없는 어린아이입니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_C_CHIHIRO_PR"
L24_1 = "고르디우스 부전대장, 일류 검술 스승, 하야미 가문의 마지막 후예… 그녀를 부르는 방식엔 여러가지가 있지만 그녀의 검은 고대적부터 한 가지 이름으로 불려왔습니다.\n화선검.\n명부신의 검 중 하나를 모방하여 만들어진 그 검은 눈도 귀도 없지만 심상의 열기만으로 주인의 자격을 가늠한다고 합니다.\n하야미 사나에는 한때 그것의 주인이었으나 가문의 몰락 이후 오랫동안 스스로를 믿지 못했습니다. 긴 세월을 차디찬 속죄의 그늘에서 보내며 검을 멀리 해왔습니다. 그런 그녀가 다시 화선검을 쥐었다는 건 반가운 일입니다.\n그녀의 의지가 뜨겁게 타오르고 있다는 반증일 테니까요."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SIXWING_CA_ACTOR"
L25_1 = "스완 클레어는 샤레이드 출신의 신비주의 여배우입니다.\n매년 영화제마다 상을 휩쓰는 그녀는 천부적인 각본 이해력과 예술적인 연기로 평단에 천의 얼굴을 가진 배우라고 평가받습니다. 한편으로 그녀는 철저하게 사생활을 공개하지 않는 배우로도 유명한데, 이는 그녀를 좇는 파파라치는 얼마 안 가 소리 소문 없이 사라진다는 업계 괴담이 생겨날 정도입니다.\n이러한 신비주의 행보로 인해, 매해 악의적인 스캔들이 터지곤 하지만 그녀는 이런 스캔들에 크게 신경 쓰지 않는 의연한 태도를 보입니다. 스완의 소속사에서 공식적으로 진행한 인터뷰대로 그저 대중 앞에서 항상 아름답고 우아한 백조 같은 모습을 보일 뿐이죠.\n최근 비밀리에 그녀가 육익이라는 단체의 일원이라는 신뢰성 높은 정보를 확보하였습니다만.\n그녀의 진짜 정체가 무엇인지, 어떤 목적을 감추고 있는지는 여전히 명확하지 않습니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_RAS_C_RIBBON"
L26_1 = "크레데레는 사건을 몰고 다니는 트러블메이커입니다. 특이한 사고방식으로 종종 말썽을 일으키지만, 어째서인지 결과만큼은 좋아 주변에서도 뭐라하지 못하는 못 말리는 문제아죠. 막내딸이라며 애지중지 키워진 탓에 형성된 높은 자존감 또한 그녀의 엉뚱한 행동이 골치 아픈 이유 중 하나입니다.\n가방 안에 직접 만든 폭발물을 들고 다니기에 오해하기 쉽지만 실상은 친구를 생각하는 자상한 마음씨를 지닌 소녀입니다. 만약 그녀가 말썽을 일으킨다면, 그녀의 잘잘못을 지적하는 것보다 눈높이에 맞춰 대화를 시도하는 편이 그녀와 신뢰관계를 형성하는데 효과적일 것입니다.\n\n단, 난처한 상황일 때 폭발물을 터트리려는 버릇은 지속적인 주의가 필요합니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCAVENGER_C_COLLECT_RA"
L27_1 = "자칼이 온다. 이면세계를 누비는 해적들이 가장 두려워하는 말입니다. 귀한 노획물을 얻은 날이면 축배를 들기보다 안전한 은신처로 도망치는 것이 해적의 관행입니다. 언더그라운드의 모든 정보를 꿰고 있는 그 여자가 관심을 갖는 순간 그 보물은 자신들 소유가 아니게 될 테니까요. \n자칼은 한 번 가지기로 한 것은 절대 놓치지 않습니다. 세계무기시장의 정상권을 노리던 신흥 군수기업 리퍼 인더스트리가 [기생충]이라 불리는 아티펙트를 입수했단 소문이 돌자 얼마 못 가 궤멸적인 타격을 입고 파산한 사건을 아시나요? 그 사건이 한 사람의 수집욕구 때문에 일어났다는 건 주변의 몇몇 기업 총수들만이 아는 사실입니다. \n수집가의 가장 아끼는 수집품인 [기생충]은 지금까지도 계속해서 그녀의 손을 거치며 비약적으로 진화하고 있습니다. 아마도 최근 스캐빈저의 우두머리를 관찰하며 얻은 경험이 참고가 된 것으로 추정됩니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_VARUNA_CA_CHAKRAM"
L28_1 = "수리야에 대한 기록은 인간의 기억을 포함한 그 어떤 데이터베이스에도 남아있지 않습니다. 따라서 그녀가 소지하고 있는 고유 무장을 통해 정체를 유추해 본 바, 한때 현실로 부상한 특이 침식체들을 섬멸하는 임무를 맡았던 것으로 추측됩니다.\n최근 수리야는 관광 회사, 바루나 투어에서 가이드 일을 하는 것으로 확인되었습니다.가이드치고는 지리나 역사에 대한 지식이 전무하고, 손님에게 불친절하기 일쑤라 최악의 가이드 후보에 이름을 올리는 한편, 수리야 덕분에 침식체의 습격으로부터 목숨을 구한 관광객들의 호평 일색인 리뷰 덕분에 평점은 제법 높은 편입니다.\n지금은 그저 사진을 찍기 위해 가이드를 한 것처럼 보이지만, 그녀의 정확한 목적이 무엇인지 알려진 바는 없습니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_VARUNA_C_WIND"
L29_1 = "아닐라는 모든 것이 수수께끼인 인물입니다. 이름, 소속, 출생지 등 어떤 것도 남아있지 않기 때문입니다. 쉽게 그녀를 신뢰할 수는 없지만, 단 한 가지 확실한 것은 그녀가 세상을 지키기 위해 싸우고 있다는 것입니다.\n오랜 시간 실종되었다가 다시 나타난 아닐라는 현재 바루나 투어라는 관광 회사에서 가이드를 하는 것으로 확인되었습니다. 그녀가 바람을 이용해 관광객을 공중으로 띄워주는 「아닐라 뷰」는 뭇 어린이들과 소수의 성인 남성을 불러 모으는 이유이자, 이번 달 최고의 가이드 상을 받은 비결입니다.\n간혹, 혼잣말을 흥얼거린다거나, 물건에 이름을 붙이고 대화를 하는 경우가 있지만, 혼자 지냈던 시간이 길었던 영향이니 이 모습을 목격한다면 모른 척해주시기를 바랍니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_LOTUS_C_KNUCKLE"
L30_1 = "파티마는 자신만의 정의를 따르며 신의를 무기로 삼습니다. 로터스의 범죄 신디케이트들을 평정한 그녀가 스스로 관리국 아래에 들어간 것 또한 유명무실해진 법을 넘어 불의를 심판할 수 있는 힘을 원했기 때문이죠. \n하지만 그녀는 결코 관리국의 권한을 남용하지 않습니다. 관리국의 수장들만이 올바른 판단을 할 수 있다고 믿으며, 그들의 지시에 따를 뿐이죠. \n물론 그녀도 관리국의 선택이 무조건 옳다고 생각하진 않으며, 경험이 부족한 상관에겐 조언을 아끼지 않는 모습을 보입니다. \n사람들은 파티마의 사나운 인상 때문에 선입견을 갖곤 하지만, 사실 그녀는 매사에 침착하고 진중하며 어린아이에겐 한없이 온정 어린 태도를 보입니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_SA_COMMANDER"
L31_1 = "펠릭스는 대정화전쟁 당시 침식으로 분열된 국가를 북방합의체라는 이름으로 다시 통합한 영웅적인 인물입니다. 비록 그 영웅은 헌신 끝에 스러졌지만, 그의 딸이 아버지의 의지와 이름을 물려받아 합의체를 이끄는 중입니다. \n그녀는 대 침식전에 특화된 군대를 양성하여 그림자를 토벌하고, 침식으로 버려진 땅을 정화해 잃어버린 풍요를 되찾으며 많은 국민들로부터 존경을 얻고 있습니다. 그 성과의 이면에는 인륜을 거스르는 무수한 실험과 희생이 있었지만 그 진실을 아는 이는 극히 일부입니다. \n펠릭스의 군대는 불사 실험으로 만들어진 합성 인간이며, 그들이 운용하는 신예 병기 체르노보그는 기계가 아닌 그림자라는 이야기가 있지만, 이는 음모론으로 취급될 뿐입니다. 파편화된 증언과 소문이 있을 뿐, 감히 그 진실을 증명할 수 있는 사람은 어디에도 없으니까요."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_C_AURA"
L32_1 = "자신을 편력기사라 주장하는 오러는 성유물이 존재한다고 알려진 지브롤터 해협에서 발견되었습니다. 그리고 로빈이라는 소심한 소녀를 자신의 종자로 삼아 온 세계를 누비고 있습니다. 약자와 불의를 두고 보지 못하는 오러는 매 순간 자신의 종자를 궁지로 몰아넣지만, 종자 로빈은 이 모든 난관을 수행의 일환으로 겸허히 받아들입니다. 언젠가 자신도 선생님처럼 용감해질 수 있다고 믿으면서 말이죠. \n*상담 내용에 따르면 오러는 로빈과 마음이 합치할 때 완전한 형태로 변한다고 합니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_VATICAN_C_CINDY_PR"
L33_1 = "신디 루퍼는 성황청의 대침식 전문기관 기적심의회의 일원이며 최근, 정식으로 사제 품계를 수여하여 단독으로 성무를 집행할 수 있는 집행 사제로 승격하였습니다.\n보다 강력해진 그녀의 카운터 능력은 단순한 B급 스플래터 무비의 모방에서 벗어나 새로운 단계에 이르렀습니다. 그녀의 체인소는 이제 스스로 적을 추적하고 완전히 심판할 때까지 결코 멈추지 않습니다.\n고지식한 성황청의 성격상 신디의 승격은 상당히 이례적이며, 내부에서는 지나치게 폭력적인 그녀의 능력이 성황청의 이미지에 해가된다는 주장이 지배적이었으나 출신성분을 고려하였을 때 그녀의 위험한 능력이 다른 세력에게 넘어갈 가능성을 견제한 결과로 추측됩니다.\n한편, 신디 루퍼 본인은 성황청 내부의 사정에는 전혀 관심이 없으며, 자신을 구해주었던 클로디아 넬슨의 안전을 최우선으로 여기는 것으로 보입니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ACADEMY_CA_TWINTAIL"
L34_1 = "지상 최강의 카운터 나이엘 블루스틸.\n아카데미 엘리트, 인류의 영웅, 그녀를 수식하는 단어는 셀 수조차 없습니다.\n수많은 퀘스트를 정복하고 여러 도전자들을 굴복시키는 모습은\n강자의 카리스마를 넘어 고고한 아우라마저 뿜어내고 있습니다.\n수천 가지의 무기를 자유자재로 다루며, 그녀의 비기인\n진 카타스트로피 블레이드는 전례 없는 최강의 무기로 기록되었습니다.\n허나 그녀가 엘리트라 불리는 이유는 단순 무력 때문만은 아닙니다.\n정의로운 인품과 세계를 지키고자 하는 마음은 가히 엘리트라 불릴 재목이라 할 수 있겠습니다.\n※이상의 서술은 「카운터즈 레거시」의 플레이어인 한 학생의 간절한 요청으로 작성되었습니다."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DANMACHI_CA_AIS"
L35_1 = "아이즈 발렌슈타인은 미궁도시 오라리오 최대 파벌이라 일컬어지는 로키 파밀리아의 중추를 짊어진 제1급모험가입니다.\n검희라는 별칭을 가진 그녀는 37계층의 계층 주인을 단독으로 격파하는 등 그 무훈담이 셀 수 없을 정도이며, 신에 버금가는 미모까지 더해 오라리오 내에 그 이름을 떨치고 있습니다.\n몬스터에 대해 강한 증오심을 지니고 있으며, 이러한 감정은 그녀를 강하게 만드는 원동력이기도 합니다.\n백병전에 뛰어난 모습을 보이며, 기술과 임기응변, 바람을 두르는 마법인 에어리얼을 구사하여 싸웁니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DANMACHI_C_BELL_RA"
L36_1 = "벨 크라넬은 단원들로부터 두터운 신임을 받고 있는 헤스티아 파밀리아의 단장입니다.\n그는 어렸을 적 자신을 거두어준 할아버지로부터 영웅의 이야기를 들으며 선망을 키웠습니다. 하나뿐인 가족이 떠나고 약 1년 후, 이성과의 만남을 추구하기 위해 미궁도시 오라리오로 향한 것은 이러한 이유입니다.\n오라리오 입성 후에는 약해 보이는 외견으로 대부분의 파밀리아에게 입단을 거절당했지만, 헤스티아와 만나 그녀의 하나뿐인 권속이 된 그는 아이즈 발렌슈타인을 향한 동경을 통해 마음을 성장의 동력으로 삼는 레어 스킬 동경일도(리아리스 프레제)를 얻고 약진하여 범상치 않은 속도로 성장 중입니다.\n특유의 재빠름과 토끼 같은 외형 덕에 래빗 풋이라는 이명이 붙었으나 전투에서는 침착한 리더십과 강인한 정신력으로 무장한 상급 모험가의 모습을 보입니다.\n이러한 정신력은 위기상황일수록 빛을 발하며, 어떠한 고난에도 물러서지 않는 모습은 가히 영웅적입니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DANMACHI_C_RYU_RA"
L37_1 = "류 리온은 뛰어난 모험가였다는 과거를 지닌 풍요의 여주인의 점원입니다.\n그녀는 과거 소속 파밀리아의 전멸이라는 처절한 과거에서 유일한 생존자가 되었지만, 벨과의 심층 결사 행을 통해 과거의 속박으로부터 해방되었습니다. 정의감이 넘치는 성격을 지니고 있으며, 동료에게 위험이 닥치면 주저 없이 돕고자 합니다.\n차가워 보이는 외모와 덤덤한 어조로 오해하기 쉽지만, 사실은 순수하고 상냥하며 덜렁거리는 면모를 지니고 있습니다. 대표적으로 그녀가 지닌 연애관은 동족인 엘프들조차 고개를 저을 정도로 순결합니다.\n선천적 마법 사용 종족인 엘프답게 뛰어난 마법능력을 지녔을 뿐만 아니라 치유능력과 근접 전투능력까지 가미한 높은 유틸리티를 발휘합니다. 경험과 기교 역시 뛰어난 베테랑이기에, 위험한 단독 임무도 거리낌 없이 수행할 수 있습니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALT_C_SEO_YOON_PR"
L38_1 = "얼마 전 관리국의 정식 태스크포스 자격을 인정 받은 알트 소대의 리더. \nCRF 출력은 평범한 편이지만 본인의 능력에 대한 이해가 높고 응용력이 뛰어납니다. 카운터 능력 외에도 사람의 심리를 파악하고 의도대로 움직이는 처세술에 능합니다. 그런 능력의 대부분을 자기 이익을 위해 이용하는 편이지만, 한 번 신뢰가 쌓인 인물에게 헌신적인 태도를 보인다는 점은 여타 개인주의 성향과는 다른 면모입니다. \n부상 이후, 재활의 일환으로 가벼운 무기를 쓰는 중이라 주장하지만 CRF출력과 개인 기량에는 별다른 이상이 없는 것으로 확인됐습니다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_CA_BIRDCAGE"
L39_1 = "솔로베는 CRF로 식물의 성장을 촉진 시키는 능력의 카운터입니다. \n그 식물은 사용자 의지에 따라 형태나 크기를 달리하여 가시가 솟거나 꽃을 피우게 할 수도 있습니다. 워치에 대응하는 물건은 새장으로, 그 안에 핀 꽃이 사용자의 CRF 상태를 반영합니다. 그 외에 하나의 워치를 더 소지하고 있으나 현재는 작동하지 않는 것으로 보입니다. \n그녀는 사회 활동 경험이 전무하여 기초 상식이 거의 없는 편으로 많은 관심과 지도가 필요합니다. 빨리 어른이 되고 싶다는 의사를 자주 내비치지만, 정작 인형과 만화영화를 무척 좋아해 본인 스스로도 혼란을 겪는 모습이 자주 관찰됩니다. \n그림이 취미라며 심리상담사의 초상화를 그려주었지만 아직 많은 연습이 필요해보입니다."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CORRUPTED_C_MIMIC"
L40_1 = "대상 관찰 결과. 일반적인 침식체와 달리 카운터의 CRF에 반응하는 이레귤러로 판명. 다수의 바이러스가 모여 만들어진 하이브마인드형 침식체. \n활동 시엔 인간 형태를 취하지만, 침식 에너지를 보관하는 기관(뿔과 꼬리로 추정)을 숨기지 못해 의류를 활용하는 것으로 보임. \n인간의 행동을 관찰하는 데 관심을 보이며, 그 원리를 이해하려고 하는 등 높은 지능을 가진 것으로 추정. 특히 범죄와 선악이란 개념에 대해 깊은 흥미를 갖고 있음. 하지만 CRF를 흡수하고 싶어하는 본능 앞에선 딱히 대상의 선함과 악함을 고려하지 않는 듯함. \n시간과 예산이 있다면 인간과의 공생 가능 여부에 대한 실험을 추진할 예정. \n위 내용은 론 리 박사의 연구 보고서에서 발췌됨."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BAR_S_BARTENDER_PR"
L41_1 = "성황청의 그림자, 악마 사냥꾼, 저 자매님 눈빛 무섭지 않아? 등등 여러 별명으로 불리는 바티칸 구마회의 떠오르는 신예 퇴마사. \n침식사태가 벌어진 현장에 다섯 차례 투입되었고 한결 같이 뛰어난 성과를 거두며 뭇 자매들의 경외를 사고 있습니다. 자신이 아끼는 총 외엔 그 누구와도 말을 섞지 않는 차가운 인물이라고 알려져 있지만, 어디까지나 소문일 뿐. \n자매들과 시시콜콜한 이야기를 나누고 싶은 마음은 굴뚝 같지만 어쩌다 한 번 굳어진 이미지 때문에 말을 아끼는 중입니다. 부디 누군가는 자신에게 먼저 말을 걸어주길 바라면서요."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_CA_BLUE"
L42_1 = "루시아 릿지는 심령 현상을 해결하는 퇴마사입니다. \n사람들은 미지의 것에 대한 두려움을 갖고 있습니다. 루시아 릿지는 이를 심령 현상이라 부르며 사람들의 공포심을 자극하죠. 공포가 극대화되면, 그녀는 퇴마라는 명목으로 사람들을 교묘하게 현혹해 성수 강매, 헌금 강요 등 폭리를 취하는 것으로 확인되었습니다. 심지어 사기 행각의 피해자들은 사기를 당했는지조차 인지하지 못한 경우가 대부분이었죠.\n루시아 릿지가 돈을 벌어야 하는 이유는 간단합니다. 바로 병을 치료하기 위해서입니다. 그녀가 걸린 병에 대해서 알려진 바가 없지만, 보름달이 뜨는 날만 되면 모습을 감춘다는 점, 발렌티누스 수도원을 근거지로 둔다는 점에서 평범한 병이 아니라는 추측만 할 뿐입니다."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_C_GOETIA"
L43_1 = "카타리나는 한때, 기도로 모든 것을 이뤄낼 수 있다고 생각했습니다. 타오르는 갈증을 포도 주스로 식히고, 고해성사로 자신의 죄를 빌며 저주가 사라지길 바랐죠. 하지만 곧 자신의 바람은 기도만으로는 이뤄질 수 없다는 사실을 깨달았습니다.\n카타리나는 어릴 적, 저주를 풀기 위해 고향을 떠난 것처럼 또다시 저주를 풀기 위해 성황청을 떠났습니다. 비록 카타리나와 함께하는 이들은 어딘가 수상하고 숨기는 것도 많은 이단이지만, 그녀의 처지를 누구보다 잘 이해하고 있죠. 저주로 인한 피의 갈증을 잠재우는 것은 무척이나 어렵지만, 그녀와 뜻을 같이하는 이들이 함께라면 카타리나는 어떻게든 견뎌낼 수 있을 겁니다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FENRIR_CA_INTERN"
L44_1 = "「1급 관리자에 의해 직접 작성된 내용입니다.」\n세피로트 나무. 현실개변력의 총체. 세계를 만드는 법칙에 관한 가설은 무궁무진하지만, 그 실체가 드러난 적은 역사상 단 한 번도 없었다. 지금까지 관리국이 확인된 단서는 오직 달의 뒷면 어딘가에서 세피라의 흔적이 있었다는 것뿐.\n과정을 막론하고, 노엘이라는 소녀는 세피로트 나무에 의해 직접 탄생한 것으로 추정된다. 소녀는 존재만으로 현실 개변을 발생시키는 힘을 가졌지만, 한편으로는 호기심 많고 정의감을 가진 평범한 소녀라는 점을 참작. 당분간 그녀의 성장을 지켜보기로 하였다.\n어쩌면 클리포트 게임 이후에 나타난 소녀의 존재는 세계 그 자체가 스스로를 복구하려는 항상성을 가지고 있다는 증거일지도 모르기에."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_BETA_S_REPLICA"
L45_1 = "블랙 로즈 분대는 검은 평의회의 기술집약체 클론으로 구성된 전술 메이드들입니다.\n베타트릭스의 크로닝 테크놀로지를 바탕으로 만들어진 이 클론들은 맨션의 주인으로부터 철저한 기술을 학습하는 동시에 뇌파를 공유하는 전술 바이저를 통해, 하우스홀드 네트워크를 구축. 의식을 공유하며, 어떤 상황에서도 대처할 수 있는 전략적 행동이 가능합니다.\n현재, 블랙 로즈 분대는 검은 평의회의 그림자로써 활동하고 있으며, 그녀들의 주요 임무는 요인 암살 및 납치로 추정됩니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CANARY_S_ASSAULT_PR"
L46_1 = "과거, 북방합의체는 달의 뒷면에서 발생하는 모종의 현상을 관측하기 위해, 우주 탐사대 스푸트니크를 조직하였습니다. 그들은 혹독한 우주 환경에서 장시간 임무를 수행할 수 있는 대원들을 양성하기 위해 맨션과 손을 잡았고. 최종적으로 11명의 탐사 대원을 선별하여 우주로 보냈으나, 이들에 대한 공식적인 기록은 전부 말소되었습니다.\n그리고 지금 스스로의 과거와 마주하기 위해, 소중한 친구를 구하기 위해. 스푸트니크 우주 탐사 최후의 생존자 쿠드랴프카는 또다시 우주복을 입기로 하였습니다. 물론, 그 특수한 우주복이 자신의 흑역사를 자극하게 될 줄은 꿈에도 몰랐지만."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ZODIAC_CA_CHARLOTTE"
L47_1 = "에스테로사 드 슈발리에는 별의 가호를 다루는 조디악 나이츠의 단장입니다.\n한때 정의를 잃고 방랑했던 그녀는 인도자의 전승으로 무구 안에 담긴 별빛을 다루는 방법을 깨우쳤고, 이를 통해 자신이 추구하는 이상적인 무구를 형상하였습니다.\n선대 기사들의 의지를 계승한 그녀는 기사가문 출신이 아님에 여전히 전통을 중시하는 원로들에게 많은 견제를 받고 있으나, 전 세대를 비롯한 단원들의 지지로 기사단의 결속을 굳건하게 만든 장본인입니다.\n기사단에 복귀한 이후, 엄격하고 근엄했던 이전과는 달리 종종 소녀스러운 모습을 보여준다는 목격담이 있습니다. 본인은 이러한 모습이 기사단의 사기에 영향을 끼치는 것은 아닌지 우려하고 있으나, 단원들은 그녀가 느끼는 부담감이 줄어들었다는 사실에 안도하고 있습니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ZODIAC_C_HAMMER"
L48_1 = "메데이아는 데이비스 가문에 속한 전 세대 양자리의 기사입니다. 과거 줄리아 레온하르트와 함께 블루시프트의 전위를 담당했던 그녀는 전임 기사단장이 종적을 감춘 이후 자진하여 일선에서 물러났습니다. 분가 소속인 양한솔을 데려와 그가 기사단에 입단할 수 있도록 교육한 것도 자신의 후계 때문이며, 언젠가 그가 뛰어난 기사로 성장해 가문의 모든 업무를 도맡아주기를 고대하고 있습니다.\n귀여운 외형과는 달리 계산적인 속내를 지니고 있으며, 평소에는 청순가련한 아가씨를 연기하며 귀찮은 업무로부터 등을 돌리고 있는 상황입니다. 다만, 이러한 연기가 그녀를 인격자처럼 보이게 해 자신의 의도와는 다른 귀찮은 일을 떠맡고는 합니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CANARY_S_SHIELD_PR"
L49_1 = "과거, 대정화 전쟁 당시 퓨처 앳 워가 수집했다고 전해지는 콜드케이스 88번 망원 렌즈. 이 아티팩트는 지구의 물리 법칙을 무시하고 에너지의 벡터를 변환할 수 있는 장치로, 관리국 연구원들은 일찍부터 이 아티팩트가 원래는 어떤 장치의 부품이라는 것을 파악하고 있었습니다.\n그로부터 오랜 시간이 흐른 뒤, 샤레이드 스캔들로 한때 세상을 떠들썩하게 만들었던 88번은 사건의 관계자였던 한 소녀에 의해 퓨처 앳 워로 돌아와 비로소 원래 모습을 되찾을 수 있었습니다.\n그리고 지금 또 한 번 역경을 넘어 별에 닿기 위해, 소중한 친구를 되찾기 위해. 샤레이드 리그 챔피언 루이즈 로랑생은 완전해진 망원경을 들었습니다. 복수가 삶에 전부였던 자신에게 그보다 더 값진 승리를 안겨주었던 모든 이들을 기억하면서."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ZODIAC_C_ARROW"
L50_1 = "카란티시르 데 레탈리아는 개인의 영달을 추구하는 레드시프트의 단장입니다. 과거 기사단의 일원으로서 기사도를 숭앙했던 그는 블루시프트의 전임 기사단장에 대한 열등감과 기사단 내부에서 일어난 사건으로 뒤틀린 정의관을 지니게 되었습니다. 별의 무구의 본질을 깨닫고 다른 이들보다 앞서 별빛에 관한 연구를 시작한 것 역시 강함이 모든 것을 통제할 수 있을 것이라는 사상 때문이며, 이러한 사상은 총명했던 그를 잔혹한 성격으로 변하게 했습니다.\n단장이라는 직책을 맡고 있으나 모든 레드시프트 단원들의 신임을 얻고 있는 것은 아닙니다. 하지만 실력이 우선되는 레드시프트 파벌에서 그를 단장으로 인정하지 않는 기사는 없습니다."
L48_1[1] = L49_1
L48_1[2] = L50_1
