L50_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_CA_CLOUD"
L51_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n용의 피가 흐르는 검사는 짐승이라 불리는 악을 벨 수 있다. 하지만 교활한 짐승은 나무처럼 베어지길 기다리지 않기에, 맞서 싸우는 법을 알아야 했다. \n그런 면에서 연화는 재능이 있었다. 심상에 내재된 또 다른 자신과 교류하는 법을 타고났기 때문이었다. 그녀는 관리국의 옛 기수들이 창안해 낸 검술을 금방 재현해 냈고, 어린 시절부터 바라밀 명도에 통달했다. \n유일한 결점은 그녀가 감정에 쉽게 휘둘리는 사람이라는 것이었다. 심상 속 수많은 인격들의 영향을 받은 탓일지도 몰랐다. \n하지만 그런 우려가 무색하게도 그녀는 자격을 인정받아 삼군문 별동대의 일원이 되었다. 마치 그것이 자신의 운명이라는 것처럼."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ATELIER_C_TIMEBLADE"
L52_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n챔버에서 1년 만에 역사에 남을 온갖 발명품을 만들어낸 과학자입니다. 이후 바이크 하나만 가지고 돌연 챔버를 떠나 외딴 터에 공방을 세우고 몸이 불편한 사람들을 위한 보조 기구를 만드는 활동을 다년간 지속해 왔습니다. 그런 선의에 기반한 활동 때문에, 그가 타임머신을 만들고 있다는 소문이 처음 퍼졌을 때도 사람들은 그것을 농담이라 치부했습니다. \n하지만 과거 행적을 조사한 결과, 그가 관리국 소속의 학자였다는 근거를 입수할 수 있었습니다. 소문과의 관계성으로 유추해 볼 때, 그는 저희가 추적 중이던 □□와 동일 인물로 추정됩니다. \n처분에 대한 지시를 기다리겠습니다."
