L1_1 = {}
L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ATELIER_C_JWIBUL"
L3_1 = "안드레아 베스카는 몸이 불편한 아이들을 위한 발명품을 만드는 공방의 주인입니다. \n덧붙이자면 노스텔지어 공방은 보육원에 생활보조 기구를 납품하는 일 외에도 바이크 커스텀, 화장품 연구, 창작 요리, 의류 디자인 등 다양한 업무를 취급합니다. 화려하고 예쁜 것을 만들 수만 있다면 그녀는 넘치는 창의력을 어디에나 쏟아낼 준비가 되어있죠. \n자신의 카운터 능력도 예외는 아닙니다. CRF에 화학 혼합물을 합친 결과, 아이들이 무서워하던 폭발 능력은 알록달록한 불꽃놀이로 바뀌었습니다. 그 불꽃이 침식체의 갑피도 녹일 만큼 뜨거운 열기를 품고 있다는 건 영업 비밀이지만요."
