L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GAMECIRCLE_C_STAR_PR"
L4_1 = "관리 실패로 인해, 관리국의 실체가 드러나며 세상은 많은 것들이 바뀌었고. 달라진 환경에 발 빠르게 적응하며, 세계 각지에 나타난 유적과 유물을 탐험하는 이들. 사람들은 이들을 트레저 헌터라고 부릅니다.\n괴짜들이 많기로 유명한 이 업계에서 그녀의 얼굴이 알려지기 시작한 것은 비교적 최근입니다. 하지만 목격자들의 증언에 따르면, 쾌활한 겉모습과는 달리 그녀의 신출귀몰한 행적과 기상천외한 수법은 어쩌면 그녀가 상당히 노련한 실력자일지도 모른다는 소문이 무성합니다.\n최근 그녀가 관리국 카운터 아카데미에서 체육 담당 교사로 근무하고 있는 점을 확인하였습니다. 지시하신 대로 비밀 회선을 통해 접촉을 준비하겠습니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DREAM_C_WRITER"
L5_1 = "<color=#FF0000>메인스트림14 이전에 해당 내용을 접하면 정보오염을 유발할 수 있습니다.</color>\n패러독스는 사람의 모습을 하고 있지만 섭리를 부정하는 짐승에 가깝다. 사람이라면 마땅히 가져야 할 것이 산산조각 나버렸으니, 그것이 그녀가 세월의 흐름과 죽음에 얽매이지 않는 까닭이다. \n오염 예방을 위해 장기간 현실과 격리된 족자에서 살았으며 좌도방 견우대사로부터 가르침을 받았다. \n삼군문의 존재를 자각한 뒤로 속세를 멀리하며 대중매체만 향유하다가 자신이 인과율에 개입하게 될 것을 염려해 감옥 신세를 지게 됐다. \n속세의 경험을 토대로 옥중에서 드라마 원고를 집필했으나 그 유명세와 달리 정작 작가의 정체를 아는 이는 거의 없다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ZODIAC_C_SCISSORS"
L6_1 = "거해궁, 게자리의 기사 아셀라 프로체니카는 비교적 최근에 생존이 확인된 레드 시프트의 일원입니다.\n과거, 조디악 나이츠 내부에서 일어난 사건으로 대부분의 전력을 상실한 레드 시프트 측은 새로운 단장을 중심으로 다시금 기사단을 재결성하였습니다. 그것이 설령 반역이라고 불리는 행위일지라도, 그들에게 있어 중요한 것은 허울뿐인 가문과 권위가 아닌, 세상의 질서를 바로잡을 힘의 논리였기 때문입니다. 동시에 그들의 존재가 곧 별빛이 그들을 인정했다는 뜻이기도 합니다.\n아셀라 또한 다른 레드 시프트의 일원들과 마찬가지로 알려진 개인 정보는 그리 많지 않습니다. 하지만 열두 가문 소속이 아닌, 하물며 기사도와는 거리가 먼 그녀가 별의 무구를 다룰 수 있다는 것은 명백한 사실입니다. 다시 말해, 그녀의 거대한 가위가 결국에는 가짜에 지나지 않은 물건이라고 할지라도, 그 코어가 되는 별빛은 틀림없이 그녀의 자격을 인정하고 있다는 뜻입니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ESPR_CA_KNIGHT"
L7_1 = "에크하르트 초월지식 학회로부터 분파된 신흥 종교 집단, 얄다바오트의 자녀들. 호수의 기사는 지식의 호수를 섬기는 이들의 교주를 칭하는 이명입니다.\n학회에서 있었던 대대적인 숙청 사건 이후, 반역자를 자처한 이들은 호수의 파편을 회수하기 위해 세계 각지의 비밀 격리 시설을 습격, 단기간에 세력을 확장하였습니다. 목적을 위해서라면 학회 이상으로 수단과 방법을 가리지 않아, 현재에는 모든 관리국에서 수배령이 떨어진 상태입니다.\n그들의 수장인 호수의 기사에 관해서는 신원미상의 남성이라는 점 외에는 알려진 정보가 없습니다. 다만, 그가 구 관리국 카멜롯 전대와 프리드웬 기관에 관한 최고 기밀을 이미 파악하고 있던 점. 그리고 그 스스로 호수의 기사를 칭하고 있는 점으로 미루어, 그의 정체가 ■■ 가문과 유관한 인물로 추정됩니다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FUTURE_M_TITAN_PR"
L8_1 = "주피터 플랜은 이상론이었을 뿐, 실현 가능성 따위는 없는 페이퍼 플랜이었습니다. 세르게이 체르노프 박사는 여러 현실적인 제약으로 포기했지만, 훗날 다가올 미래를 위해 이를 간직하고 있었죠. 그리고 이는 주피터 플랜의 제안자, 르네 말루프에게 다시 이어져 히페리온 플랜 역시 빛을 보게 되었습니다.\n히페리온 플랜의 헬리오스 시스템은 이터니움 드라이브 가동으로 발생하는 반중력장을 극대화해 육중한 몸체가 지형의 제약을 완벽히 극복했습니다, 새로 부착된 아이테르 입자포와 페르세스 미사일은 눈앞의 적에게 전략 포격을 시행할 수 있게 되었죠. 타이탄은 이제 전장 어디서든 나타나는 대륙간 전략 공중요새가 되어 위험에 빠진 인류를 수호할 준비를 마쳤습니다. 주피터 플랜의 최초 제안자, 르네 말루프는 히페리온을 개량한 뒤 연구 노트에 다음과 같은 글귀를 남겼습니다. \n─「당신의 의지를 이어, 아이들이 전쟁을 모르는 시대에서 살아가길.」"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ADMIN_C_RAT"
L9_1 = "퓨처 앳 워가 다른 경쟁사보다 기술적인 우위를 점할 수 있었던 비결 중 하나는 뛰어난 연구원들과 콜드 케이스 덕분이었습니다. 고도의 과학 기술을 보유했던 이면세계의 유물, 콜드케이스의 분석을 맡았던 연구원이 바로, 과거 구 관리국 출신 공학자인 닥터 메이시였습니다. 퓨처 앳 워 프로젝트가 실패하지 않았다면, 그녀는 언젠가 세상에 새로운 혁신을 가져다 주었을지도 모릅니다. 닥터 메이시가 어떤 경위로 퓨처 앳 워에 들어오게 되었으며, 어째서 껍데기만 남은 조직에 현재까지 남아있었는지에 대해 밝혀진 바는 없습니다. 하지만 그녀는 여전히 세계를 위해 움직이고 있습니다. 자신이 믿고 따랐던, 대의를 위해 희생되었던 전우들을 가슴 속에 묻어둔 채로."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FRONTBAY_C_HARPOON"
L10_1 = "키이라 보니는 「프론트 베이 최악의 범죄자」라고 불린 악명 높은 해적입니다. 자유를 사랑하고 속박을 싫어하는 그녀는 해적들을 선동해 총 56 차례나 도시를 전복 시키려 한 죄목으로 CRF 제어 구속구를 차는 형벌을 받았죠. 그녀가 이런 테러 행위를 벌이는 이유는 프론트 베이 사람들에겐 잘 알려져 있습니다. 바로 자유를 억압하는 관리국으로부터 도시를 해방하고 현 시대의 대해적이라는 이름을 이어받기 위해서입니다. 정말 어리석은 짓이지 않나요? 대해적이라는 칭호가 어떤 책임과 고통을 가져오는지 알지도 못하고──!@#$@# \n\n *해당 보고서는 프론트 베이 비서관에 의해 작성되었으며, 부적절한 내용이 포함되어 있을 수 있습니다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FENRIR_CA_HILDE_PR"
L11_1 = "당신의 힐데, 그 아이는 최고의 전사였어. 그래서 날개를 달아주고, 전사들의 운명을 인도하는 발키리로 다시 태어나게 했지. 프레이야라는 새로운 이름도 지어줬어. 신이 내린 힘과 숭고한 뜻이 주는 긍지. 그녀는 한동안 다른 발키리들과 함께 자기 역할을 훌륭히 해냈어. 발키리의 인도를 받는 전사의 말로가 ■■이 되는 것임을 깨닫기 전까지는.\n진실을 알게 된 그녀는 자신이 갖고 있던 긍지에 깊은 회의를 느꼈을 거야. 사랑하는 날개를 스스로 뜯어내고, 자신을 따르던 전사들의 부름도 외면했지. 태양과 이어진 결속을 끊어내고 어둠 속에서 당신이란 달을 쫓기 시작한 것도 그때부터였어. 하지만 난 그녀를 배반자라고 생각하지 않아.\n당신도 알잖아? 운명이란 건 결국 처음 정해진대로 흘러갈 수 밖에 없는 거니까."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_G1_C_TAOIST"
L12_1 = "민하는 우도방이라는 독특한 심신수련법을 거친 카운터 중 한 명입니다. 그녀는 스승 태유대사를 아버지처럼 따랐으나, 그의 갑작스런 죽음 이후 그라운드 원의 공인카운터라는 무거운 직책을 이어 받게 됐습니다. 하지만 책임감보단 복수심이 앞섰던 그녀는 직책을 무시하고 그라운드 원을 떠나 스승을 살해한 자를 찾아 온 세상을 떠도는 중입니다.\n그런 그녀의 주변 평판은 복수귀치고 꽤 긍정적인 편입니다. 침식재난 때마다 많은 사람들을 구하고 유유히 사라졌다는 일화가 세상 곳곳에 남아있죠.\n여기엔 그녀 스승의 독특한 수련법이 영향을 준 것으로 보입니다. 그 가르침 때문에 곤궁에 처한 사람을 보면 무시하지 못하고, 감사를 받을 땐 희열을 느끼는 마음을 타고나버린 것이죠.\n민하는 이런 자신의 성격에 번거로움을 느끼지만, 당장 내일도 누군가 자신을 필요로 한다면 복수는 접어두고 도움을 줄 것입니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ANAPILIS_CA_SCYTHE"
L13_1 = "아나필리스는 그녀의 세계에서 전승되던 일곱 개 낙원 중 하나의 이름이었다. 하지만 그녀가 종말 이후의 흔적 위를 거닐며 알게 된 사실은, 저마다 바라보는 방식과 이름만 달랐을 뿐 낙원은 처음부터 하나였다는 것이다.\n황금나무의 힘으로 세계를 다시금 꽃피워낸 그녀는 흩어져있던 모두의 믿음을 하나로 모았다. 그 결집은 철학적 담론이나 지고한 설득에 의한 것이 아니었다. 그들은 복수라는, 숭고함과는 정반대에 있는 인간의 가장 원초적인 감정을 따르며 하나의 낙원을 받아들였다.\n그녀는, 그렇게 낙원이 되었다."
L11_1[1] = L12_1
L11_1[2] = L13_1
