L46_1 = "SI_COLLECTION_UNIT_INTRO_OPR_LEE_SUYEON"
L47_1 = "이수연은 코핀 컴퍼니의 창설자이며, 새로운 사장이 부임한 지금은 부사장직을 맡고 있습니다.\n블랙 기업으로 통하던 코핀 컴퍼니는 성장세를 타기 시작한 뒤로 경이로울 만큼 높은 무사고율이 주목 받았는데, 그 요인 중 하나로 경영인이면서 현장에 대해 넓은 식견을 지닌 부사장의 존재가 재조명되었습니다.\n당사자는 매번 사고를 치는 사원들 탓에 언제 터질지 모를 폭탄을 짊어진 심정이라고 성토하지만 말입니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_COLLECTION_UNIT_INTRO_OPR_OLIVIA_PARK"
L48_1 = "카운터 연구와 침식 생물학의 권위자 올리비에 박은 매년 학계를 놀라게 할 만한 발표로 학계의 존경을 받고 있습니다.\n침식 생물학이란 새로운 학문이 짧은 시간 동안 지금 같은 수준에 도달할 수 있었던 데엔 그녀의 천재성이 큰 역할을 했습니다.\n하지만 그러한 학문적 성취의 이면에 직원들을 서슴없이 이용하는 실험 정신과 수많은 조교들의 희생이 있다는 사실을 아는 사람은 드뭅니다."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_COLLECTION_UNIT_INTRO_OPR_ANASTASIA"
L49_1 = "아나스타샤는 올리비에 박 교수의 조교 출신으로, 생명학 전공 중 기계공학으로 진로를 바꾼 인물입니다.\n학생 시절 코핀 컴퍼니로부터 연구용 이터니움 소자를 학자금 대출로 지원 받은 일 때문에, 현재 코핀 컴퍼니에 취업하여 채무를 변재 중입니다.\n관리국 공인 D급 카운터로, 회사 사정상 지원되지 않는 장비들 대신 무거운 부품을 옮기거나 근력 원심분리를 하는 일에 자신의 카운터 능력을 유용하게 쓰고 있습니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_COLLECTION_UNIT_INTRO_OPR_CHLOE"
L50_1 = "오퍼레이터 교육기관 출신인 클로에는 자신의 본업보다 인터넷으로 배운 근본없는 오컬트에 더 심취해 있습니다.\n자칭 특기는 점술로, 급여 대부분을 수정구 등 수상쩍은 오컬트 물품 구매에 쓰고 있습니다. 점을 본 직원들에 따르면 저렴한 모양새와 달리 점괘의 적중률은 꽤 높다고 합니다.\n입사 동기인 레나 맥켄지와는 동문으로, 본인은 어리석은 불신자를 교화하는 중이라고 하지만 주위에선 그녀가 사람 구실이라도 하는 건 레나 양 덕분이란 평이 대세입니다."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_COLLECTION_UNIT_INTRO_OPR_LENA"
L51_1 = "레나는 오퍼레이터 교육기관의 모든 교육과정을 모범적으로 수료한 우수 교육생입니다. 훌륭한 오퍼레이터가 되겠다는 일념으로 단기간에 큰 성과를 거뒀기 때문에, 교육기관에선 첫 수업마다 그녀의 사례를 들어 학생들의 의욕을 고취시킨다고 합니다.\n사실 그녀가 공무원 시험 준비를 그만두고 오퍼레이터가 된 계기는 인기 드라마 「유혹의 함교」의 여주인공 프레데리카처럼 되고 싶었기 때문입니다. 다만 그녀와 달리 맥주 사랑은 여전합니다."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_COLLECTION_UNIT_INTRO_OPR_JANG_WEI"
L52_1 = "경리 사무직인 장 웨이는 회계 능력은 뛰어나지만 사람 복이 없어서 늘 수상한 범죄 조직과 엮이다가 존 메이슨 용병 사무소에 정착하게 되었습니다.\n출근하면 대부분의 시간을 화장이나 인터넷 쇼핑에 써서 근무 태도를 지적 받기 일쑤지만, 이는 그만큼 현재 직장의 재정 상태가 투명하다는 방증이기도 합니다. 그간의 경험을 돌이켜 보면, 많이 빼돌려야 할수록 그녀도 바빠졌기 때문입니다."
L50_1[1] = L51_1
L50_1[2] = L52_1
