L2_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MARK_FINRI"
L3_1 = "마크 핀리는 젊은 시절부터 전 세계를 누비고 다닌 정보부 요원입니다. 특히 위험한 이면세계에서도 성공적인 공작 활동을 펼침으로써 상부의 신임을 얻은 바 있습니다.\n지금은 관리국 연합 정보실에서 활동 중이라고 알려져 있지만, 그의 경력을 감안하면 어디까지 진실인지는 불분명합니다."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_OPR_LEE_YOONJUNG"
L4_1 = "올리비에 박 교수의 연구실 소속 조교인 이윤정은 오늘도 논문을 위해 안락한 수면을 포기하고 카페인을 섭취하며 살아갑니다.\n연구실에서 살아남기 위해 일반인이라면 건강에 무리가 올 정도로 카페인을 섭취함에도, 선천적인 체질 덕분에 큰 문제가 없다고 합니다.\n혹사로 생긴 다크 서클과 침침한 아우라는 보는 사람까지 피곤하게 만들지만, 대학생 때는 밝고 외향적인 성격의 인기인이었다고 전해집니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_OPR_NAHIRIN"
L5_1 = "나희린은 초기 차원 함선 설계자인 부친의 영향을 받아 업계에 취직한 차원 함선 애호가입니다.\n하지만 현실은 작은 태스크포스의 격납고에서 관리 명목으로 잡일을 도맡고 있을 뿐입니다.\n그래도 그녀는 출격하는 함선을 가까이에서 볼 수 있다는 이유만으로도 만족 중이라고 합니다.\n언젠가 자신이 설계한 초현실적인 디자인의 차원 함선을 만들고야 말겠다는 꿈을 품고서 말입니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_OPR_REPLACER_COMMANDAR"
L6_1 = "리플레이서 신디케이트의 뒤틀린 사상에 동조한 자들 중에는 군인 출신의 장교들도 다수 있습니다.\n이들은 정규 군사 조직이 개량해온 체계적인 전략 • 전술에 기반하여 조직원들을 훈련시킴으로써, 리플레이서 신디케이트가 세계를 위협할 만한 조직으로 성장하는 데 공헌하였습니다.\n그들 중 일부는 전투 중에 투항을 택하기도 했지만, 대부분 자신들이 선택 받은 인류라는 그릇된 믿음에서 벗어나지 못하고 있습니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_COLLECTION_UNIT_INTRO_OPR_ALICIA"
L7_1 = "라임은 퓨처 앳 워가 개발했던 보급형 소프트웨어의 후속 버전입니다.\n실용성만을 중시했던 이전 버전과 달리 인공지능 비서라는 타이틀을 달고 고유한 감정 표현과 상호작용 기능이 추가된 소프트웨어입니다.\n이후 출시된 알파트릭스의 제품에 비하면 성능상으로는 뒤처지는 편이나, 이전 버전에서 다져 놓은 신뢰성과 오랜 세월 쌓인 여러 가지 애드온 덕분에 지금도 판매가 이루어지는 모델입니다. "
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_COLLECTION_UNIT_INTRO_OPR_ACADEMY_FRESHMAN"
L8_1 = "오퍼레이터 교육기관은 현장 실습의 일환으로 성적이 우수한 상급생들을 선발해 제휴를 맺은 태스크포스에 파견합니다.\n계약 기간이 끝나면 교육생은 교육기관으로 돌아가서 커리큘럼을 이수하지만, 현장에서 두각을 드러낸 교육생은 업체에서 곧바로 정식 채용하는 사례도 있습니다.\n교육생들은 자신도 그런 사례가 될 수 있다는 기대를 품고, 오늘도 누구보다 최선을 다합니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_OPR_AUTOMATA"
L9_1 = "보급형 오토마타는 퓨처 앳 워에서 군 인력 부족을 해소하기 위해 만든 보급형 소프트웨어로, 차원 함선의 기초적인 운용을 지원합니다. 본래는 군사용이었지만 지금은 민간에도 공개된 상태입니다.\n초기 모델은 그래픽을 제공하지 않는 건조한 형태였지만, 소녀형 캐릭터를 추가하는 애드온이 폭발적인 반응을 얻자 공식 기능에 포함하였습니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_OPR_KIMHANA"
L10_1 = "관리부장 김하나는 특유의 근면성실함과 붙임성으로 사고뭉치인 직원들을 아우르면서 코핀 컴퍼니의 조직 유지에 크게 기여하고 있습니다.\n고교 졸업 이후 코핀 컴퍼니에 입사해 현재까지 재직 중으로, 늘 화사한 미소를 통해 자칫 칙칙해질 수 있는 회사 분위기를 밝게 만들어 왔습니다.\n하지만 정작 본인은 소개팅 경력이 늘어만 가는데도 진전 없는 이성 문제가 고민이라고 합니다. 사내에는 그녀의 무시무시한 술버릇이 원인이란 추측이 정설처럼 퍼져 있습니다.  "
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_OPR_REPLACER_KING"
L11_1 = "리플레이서 킹은 리플레이서 신디케이트를 세운 장본인으로서, 리플레이서 인자를 활용하는 여러 방안을 연구진에게 제안한 바 있습니다. 그리고 그 방안 중에는 자신의 계획을 실현하면서 생길 여러 문제들을 군사적으로 제압하기 위한 것들도 포함되어 있었습니다.\n리플레이서 융합체를 활용하는 군사 교리는 조직에 합류한 장교들의 도움으로 빠르게 보급되었지만, 그 교리를 가장 잘 활용할 수 있는 인물은 처음 고안해 낸 리플레이서 킹 자신일 것입니다."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_OPR_RAS_TOWER"
L12_1 = "미래전략실의 책임자인 시그마는 단 하루도 일과를 거른 적 없는 모범사원입니다.\n미래전략실의 하루 일과는 다음과 같습니다. 동화책 읽기, 재밌는 상상하기, 아빠가 부르면 달려가기.\n하지만 시그마의 면모는 오퍼레이터가 되었을 때 진정한 빛을 발하죠!\n세계 최고의 무면허 무사고율을 자랑하는 함선 조종능력과 초등학생도 이해할 수 있는 1차원적인 지휘전술은 명실상부한 회사의 자랑입니다.\n그러니 웬 꼬마 목소리가 함내에 울려퍼지더라도 당황하지 마시길."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_COLLECTION_UNIT_INTRO_OPR_OLD_ALICIA"
L13_1 = "모네카는 이면세계로부터 인양된 구 관리국의 함선에서 추출한 전대 지원형 제어 시스템입니다.\n감정표현 레벨을 항상 최고조로 설정해 놓는 이 모델은 전술 지원뿐만 아니라 기갑 병기에 탑재되어 활약한 사례도 많습니다.\n복원을 마친 모네카는 신속한 진군을 위해 만반의 준비를 갖춘 상태입니다. 솜사탕처럼 푹신푹신한 미소에는 치명적인 매력이 숨겨져 있습니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MASTER"
L14_1 = "맨션 마스터란 「맨션」이라는 암살 조직의 수장을 부르는 호칭입니다. 당대의 맨션 마스터는 치명적인 독극물을 제조 • 유통한 혐의로 관리국 연합 정보실의 추적을 받고 있습니다.\n식물에 박식한 이 귀부인은 식물독으로 휘하 메이드들이 두려움을 모르게 만들거나 적들의 오감을 마비시킵니다. 그녀가 머무는 저택의 정원은 누구나 놀랄 만큼 아름답지만, 활짝 핀 꽃들 아래에 무엇이 묻혀 있을지는 상상하지 않는 편이 좋습니다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_OPR_SERINA_SUMMER"
L15_1 = "견습 아르바이트생 세리나 크루가 해변 노점으로 출장을 왔습니다.\n세리나 크루는 튜브부터 잠수함까지 없는 게 없는 해변 노점에서도 엉뚱한 매력으로 손님을 맞이합니다. 덤으로 수박 화채를 만들어 주기도 하고, 모처럼 입은 수영복을 자랑하겠다며 밖에서 손님인 척하기도 하죠. 이번 출장을 잘 끝내면 정식 아르바이트생이 될 거라 굳게 믿고 있답니다.\n중간중간 사라져도 놀라지 마세요! 잠시 해변을 걸으며 점장이 되는 미래를 상상하는 중이니까요."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_OPR_GRAFFITI"
L16_1 = "레이첼 도즈는 제 6 난민지구의 칙칙한 길거리를 알록달록하게 칠하고 다니는 장본인입니다.\n레이첼이 스프레이를 들고 지나간 담벼락에는 늘 멋진 그래피티가 남겨집니다. 그 실력은 난민지구의 자경단들은 물론이고 위험한 갱단들 사이에서도 호평이 자자하죠.\n최근 겪은 사건의 후유증이 아직 완전히 가시지 않았음에도, 타고난 예술적인 충동은 변함없습니다. 고용주 겸 친구를 데리고 다니면서 자신의 작품을 자랑하는 모습에서는 여전히 생생한 활력이 느껴집니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MOMO"
L17_1 = "모모는 흉폭한 드래곤 인형 뿜뿌미와 아직 채 네 명을 채우지 못한 사천왕을 거느린 위대한 마왕님(자칭)입니다. 모모는 너무 위대한 나머지 언제나 외세로부터 자신의 자리를 위협 당하고 있습니다. 주로 떨어지는 화분이나 길가의 물웅덩이, 그녀의 달콤한 간식을 노리는 비둘기나 너구리 같은 존재들 말이죠. \n물론 마지막에 이기는 것은 모모입니다! 그녀의 곁에는 그레모리처럼 충직한 하수인들이 있으니까요. 모모는 하수인들에게 어떤 명령이든 내릴 수 있습니다! 하지만 하수인들의 기분이 별로 좋지 않을 때는 적당히 눈치를 보는 편입니다. 마왕다운 처세술이랄까요?"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MOTHER"
L18_1 = "모에나는 작은 어촌에 사는 씩씩한 여인이자, 모네의 팔불출 엄마입니다.\n마을 일이라면 앞장서서 해결하고, 딸을 지키기 위해서라면 물불 안 가리고 뛰어드는 멋진 엄마이기도 하죠. 배운 게 없다며 모네에게 미안해하지만, 모네는 그런 엄마를 누구보다도 자랑스러워합니다.\n한편, 그녀의 천연 동안 미모는 도시 사람들도 부러워할 정도입니다. 그 미모의 비결은 바로 대대로 전해져 온 코코넛 크림이라고 하는데요, 바다처럼 넓은 마음씨를 가진 그녀는 손님에게 코코넛 크림을 흔쾌히 나눠 주기도 합니다. 모네가 자랑할 만하죠?"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_OPR_REPLACER_LOOK"
L19_1 = "리플레이서 룩은 리플레이서 신디케이트가 보관했던, 인간을 기반으로 만들어진 일종의 바이오 컴퓨터입니다.\n주요 기능은 대규모 시스템으로 수행하던 공간 좌표 계산과 제한적인 간섭이며, 이외에도 다양한 역할을 수행 가능한 것으로 추정 중입니다. 리플레이서 신디케이트에게 유용한 전력이 되었을 텐데도 테라사이드 전역에서 목격되지 않은 이유는 아직 추론의 영역에 남겨져 있습니다.\n한편으로 그 성능을 발휘하기 위해서인지 두뇌를 제외한 신체기능은 같은 연령대에 비해 발육 및 효율이 뒤떨어지며, 당사자는 특수한 영양 공급이 필요하다는 구실로 매번 특식을 요구하곤 합니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_OPR_VILLETTA"
L20_1 = "비렛타 누는 사립 애쉬포드 학원의 수영부 고문이자, 체육 담당 선생님입니다.\n하지만 그녀의 진짜 정체는 브리타니아군의 순혈파 군인으로 공적을 올려 출세하려는 야심가입니다.\n모종의 이유로 기억을 잃은 그녀는 제로가 일으킨 블랙리벨리온 당시의 기억을 되찾았습니다. 그후, 제로의 정체가 를르슈라는 것을 떠올린 그녀는 그 사실을 상층부에 보고하여 공적을 인정받고, 기밀정보국에 배속되었습니다.\n그녀의 임무는 애쉬포드 학원에서 를르슈를 감시하며, 그의 공범자인 C.C.를 포획하는 것입니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_OPR_DAIN"
L21_1 = "미리네가 마스터 소드를 찾기 위한 여정에서 만난 첫 번째 친구!\n뛰어난 관찰력과 방대한 지식 그리고 동물과 대화하는 능력으로 언제나 미리네를 서포트해요. 상냥한 성격과 온화한 말투를 가진 다인이는 누구보다 귀여운 것을 좋아하지만, 때때로 이 때문에 다른 동료들을 곤혹에 빠트리기도 한다고요.\n※이상의 서술은 「카운터즈 사가」에 동봉된 설정집에서 발췌하였습니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_OPR_VIVIEN"
L22_1 = "노르드나빅 출신 장교. 수도 출신의 뛰어난 기술자로 한때 왕실 최고기술자가 될 것이라 촉망받았으나 현재는 변방의 수비대에서 일개 기술교관을 맡고 있다. 속내를 잘 드러내지 않는 성격과 매서운 인상 탓에 좀처럼 대하기 힘든 상관이란 인식이 있다. 하지만 골동품이나 다름없던 수비대 병사들의 장비와 생활시설이 늘 새것처럼 작동하는 이유는 그녀의 세심한 배려 덕분일 것이다.\n여담으로 혼자 작업을 할 때 콧노래를 흥얼거린다는 소문이 있다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_COLLECTION_UNIT_INTRO_OPR_SYSOP"
L23_1 = "뒷세계의 거물들의 연합인 검은 평의회의 의장. 악명 높은 악인들을 여럿 거느리고 있지만 정작 자신의 정체는 알려진 바가 없어 여러 추측만이 무성하다. \n제멋대로인 범죄자들이 한 수장만을 섬길 리 없다고 생각하는 사람들은 평의회라는 존재 자체를 도시전설 쯤으로 여기기도 한다. \n하지만 시솝은 실제로 존재한다. \n사람들의 추측에 맹점이 있다면, 그는 악인을 다스리거나 통제하려고 하지 않는단 것이다. 단지 인과율을 계산하고, 바라는 결과를 위해 그 과정을 조정하는 것이 그의 방식일 뿐이다. \n그러니 검은 평의회에 주인은 없다. 원하는 것을 얻으려는 자들과, 그들을 위한 조언자가 있을 뿐."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MITCH"
L24_1 = "샤레이드 건틀렛 리그를 중계하며, 자극적인 컨셉으로 최근 일부 시청자들로부터 열렬한 지지를 받는 스트리머입니다.\n편파적인 중계와 겉핥기식 지식으로 건틀렛 위키의 사건 사고 항목을 매주 갱신하는 사고뭉치지만, 빠른 텐션과 호소력 짙은 보이스는 그녀만의 세일즈 포인트!\n지금은 삼류 소속사에 속한 스트리머이지만, 예전에는 개인 방송을 했던 경험이 있으며 미치 본인은 이를 흑역사 취급하고 있습니다. 그러나 그녀의 과거를 기억하는 소수 팬은 언젠가 다시 한번 베티 미치의 진심 어린 방송을 보게 될 날을 기대하고 있습니다."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_OPR_CANARY_STAFF"
L25_1 = "모두가 주목받고 싶어 하는 건틀렛 무대.\n직접 경기를 뛰는 선수들에 비해, 얼굴 없는 선수인 스태프는 그다지 인기 있는 포지션이 아닙니다. 하지만 아무리 뛰어난 선수라고 해도 후방지원 없이 제 실력을 발휘할 수 없죠.\n말레나 스키너 역시 매년 리그 TOP 10에 들 정도로 강한 팀에서 활동하던 스태프였습니다.\n그런 그녀가 갑자기 그동안의 커리어를 버리고, 신생팀에 들어왔는지는 아무도 모르지만, 한 가지는 확실합니다.\n그녀가 스태프로 있는 한, 카나리아 스쿼드는 팀의 잠재력을 최대한 발휘하게 될 것입니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_COLLECTION_UNIT_INTRO_OPR_SHASHA"
L26_1 = "시린그라드 마을의 활기찬 소녀 사샤 가가리나는 물건을 고칠 수 있는 능력으로 마을 사람들을 도우며 살고 있습니다.\n재료만 있다면 새로운 물건을 만드는 것도 가능하고,\n생활용품부터 각종 무기까지 만들어낼 정도로 다재다능합니다.\n항상 싱글벙글한 미소로 사람들에게 밝은 모습만을 보여주지만, 과거 북방합의체에서 받았던 실험 부작용에 매일 고통받고 있습니다.\n그럼에도 남들 앞에서 나약한 모습을 보이려 하지 않는 이유는 아마 과거의 기억을 잊기 위한 몸부림일지도 모릅니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_OPR_ROOT_DRUID"
L27_1 = "멀린은 모종의 예언에 대비하여 거대한 그루터기를 보살펴왔습니다. \n그루터기의 주민들은 수천 년의 역사와 지식을 간직한 멀린을 스승이자 지도자로 섬겼고, 그녀는 그런 기대에 부응해 사람들에게 많은 가르침을 주었습니다. \n멀린은 특히 헌신적 사랑을 중요히 여겨 아이들을 직접 교육할 정도였는데, 불륜에 매우 엄격한 그루터기의 규칙에서도 그 가치관을 엿볼 수 있습니다. \n멀린은 넓은 포도 농원을 가꾸며 직접 포도주를 빚는 것을 취미로 삼습니다. 술을 좋아하는 그녀는 좋은 일이 생기면 항상 술과 함께 기념했고, 그루터기에 결혼식이 있는 날은 항상 그녀가 베푸는 술로 축제가 벌어집니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_COLLECTION_UNIT_INTRO_OPR_SPEAKER"
L28_1 = "유피는 복잡한 가정사로 보육원에 들어온 아가씨입니다. 나이에 걸맞지 않은 어른스러움으로 일찍이 보육원장을 도와 아이들을 돌봤고, 일을 시작한 이후에도 보육원에 돈을 보내는 착한 심성을 지닌 인물입니다.\n아이들에게 헌신적이기에 툴툴대면서도 할 건 다 해주는 착한 언니지만, 감정이 고양되거나 분위기에 휩쓸리면 상황에 불을 지피는 어린아이와 같은 면모도 있습니다. 단적으로 말하면 트러블메이커와는 최악의 상성일지도 모릅니다.\n\n\n\n"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_COLLECTION_UNIT_INTRO_OPR_ASHA"
L29_1 = "아샤는 로터스 관광지를 모두 섭렵한 바루나 투어의 대표입니다.\n온갖 범죄에 노출된 로터스를 관광하는 것은 불가능합니다. 하지만 아샤는 강력한 카운터를 가이드로 고용해 로터스에 자리 잡은 전대미문의 수완가로 이름을 알렸습니다. 로터스에서 유일하게 안전을 보장하는 「이래도 안 살 거야?」패키지는 100%에 가까운 생환율을 자랑합니다. 이는 패키지의 비싼 가격에도 불구하고 경호와 관광을 모두 챙기려는 자들이 울며 겨자 먹기로 바루나 투어를 선택하는 이유입니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_COLLECTION_UNIT_INTRO_OPR_DAIN_PR"
L30_1 = "모험가들의 여정을 돕는 아름다운 성직자!\n노련한 실력과 방대한 지식, 그리고 온화한 성품으로\n언제나 어린 뉴비들을 서포트합니다.\n때로는 상냥하게, 때로는 엄하게 파티를 관리하는 모습으로\n동료들에게 절대적인 신뢰를 받고 있습니다.\n그녀의 곁에는 언제나 사랑스러운 마리모들이 함께합니다.\n통통 튀는 귀여움으로 자칫 방심할 수도 있겠지만,\n위험하다고 판단되면, 즉시 무서운 괴수로 돌변하여 주인을 지킬 것입니다.\n※이상의 서술은 「카운터즈 레거시」의 플레이어들과의 인터뷰를 토대로 작성되었습니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_COLLECTION_UNIT_INTRO_OPR_BOOK"
L31_1 = "성황청은 아주 오래전부터 집요하게 기적을 추구해 왔습니다. 비밀 서고의 담당 사서인 비블리데 루체가 관리하는 서고 역시 기적에 관한 수많은 단서가 잠들어 있다고 전해지죠.\n하지만 작고 사소한 우연부터 상식적으로 이해할 수 없는 초자연적 현상까지. 기적에 관한 해석은 저마다 다르기 마련입니다.\n그러니 어쩌면 종교적 신념을 저버릴 정도로, 그녀가 감추고 싶어 했던 산타복 차림을 볼 수 있는 것 또한 어느 성탄절의 기적이라고 할 수 있지 않을까요?"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_OPR_HESTIA"
L32_1 = "헤스티아는 3대 처녀신 중 하나이며, 불꽃을 주관하는 화로의 여신입니다.\n벨과의 만남으로 본격적인 파밀리아 활동을 시작한 그녀는 게으르고 벨을 향한 집착이 심한 여신이지만, 아이를 소중히 여기는 상냥한 신격자인 덕인지 주변의 신들과 권속들로부터 두터운 신뢰를 얻고 있습니다. 소속 단원들을 가족처럼 대하는 선신이기도 하며, 귀여운 외모와 애교로 인해 주변으로부터 마스코트 캐릭터마냥 귀여움을 받고 있습니다.\n다만 이런 장점에도 불구하고 벨의 헤스티아 나이프를 마련하기 위해 진 빚의 변제는 아직 한참 남아 있기에, 변함없이 감자 크로켓 판매점의 아르바이트에 열과 성을 다하는 나날을 보내고 있습니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_OPR_AGNES"
L33_1 = "아그네스는 현 학회장을 도와 학회의 변화를 이끈 자 중 하나입니다.\n복수를 마친 뒤 수도원의 숙원을 내던진 그녀는 이제 자신이 가진 것에 눈을 돌리기 시작했습니다. 바로 발렌티누스 수도원의 명물인 에그타르트와 맥주, 그리고 지켜야 할 사람들이죠. 아그네스는 잠시 수녀복을 벗어두고 그녀만의 작은 숙원에 집중하고자 합니다.\n그녀는 여전히 침입자에게 냉혹하고, 자비 없는 파수꾼일지 모르지만, 소중한 사람들에겐 친절하게 에그타르트를 대접해 주는 수도원장일 뿐이니까요."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_OPR_RAT"
L34_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n쥐스틴 메이시는 관리국 제4 수색전대 야크샤의 담당 엔지니어 겸 공학자입니다.\n무척 어린 나이로 관리국에 재능을 인정받은 쥐스틴은 최연소로 병기개발국에 스카우트되었습니다. 그러나 공방이 아닌 현장에서 대침식전에 기여하고 싶었던 그녀는 라이오넬 전대장의 제의로 환상종 동포들이 있는 야크샤 전대로 이적하게 되었습니다.\n비록, 너무 일찍 재능을 인정받은 쥐스틴은 쉽게 남을 깔보고 금방 우쭐해지는 성격이지만, 그럼에도 야크샤 전대원들은 그녀를 귀염둥이 막내 대원이라고 생각합니다. 초콜렛 바른 해바라기씨를 무척 좋아하기 때문에 야크샤 전대는 쥐스틴에게 장비를 맡길 때면, 꼭 해바라기 씨를 뇌물로 바치는 풍습이 있습니다."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_OPR_GRACE"
L35_1 = "그레이스는 버밍엄 백작가의 명맥을 이은 아르카데나 제국의 별의 인도자입니다. 그녀는 수많은 고유무장을 만들어 제국의 구원에 일조한 명가 출신이라는 뒷배경과, 어릴 때부터 남달랐던 재능으로 제국의 참모로 활약하였습니다. 뛰어난 인품과 노력가인 덕에 신민들과 부하들에게 큰 신임을 얻고 있으나, 악의 없는 돌발행동은 그녀가 제국 내에서 요주의 인물인 이유입니다.\n특히, 플라멩코를 격정적으로 추는 버릇이 있기에 제국 무도회에서는 엄중한 감시가 필요합니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_OPR_LEEJISOO"
L36_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n대균열 발생 당시 대규모 오염에 휘말린 인물로 추정됩니다. 대개의 버려진 자들이 그렇듯 펠릭스의 접선책이 그녀를 만났습니다. 이후의 행적에 대해선 정확히 알 수 없으나 최근 노스텔지어 공방의 일에 협력하고 있는 모습이 확인되었습니다. \n상처가 없음에도 눈을 가린 채 생활하는 것 또한 여전합니다. \n손을 대는 기계마다 고장이 나는 탓에 공방의 주인과 종종 트러블이 있는 듯합니다. 냉소적이고 고집이 세지만 둘의 관계가 오래 유지되는 것으로 보아선 겉으로 보이는 것과 달리 협조적인 면도 있는 것 같습니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_COLLECTION_UNIT_INTRO_OPR_NATALIA"
L37_1 = "나탈리아 리소바는 살을 에는 혹한 지대의 북방합의체 출신이지만, 따뜻한 심성을 가진 천진난만한 소녀입니다. 비록 입보다 의욕이 앞서 자주 말을 더듬지만, 오히려 주변인들에게 귀여움 받기도 합니다.\n기계와 공명하는 능력을 가진 나탈리아는 그녀가 직접 제작한 로봇 여우, 폭실이와 항상 함께하며, 최첨단 기능이 탑재된 폭실이는 아직 어린 나탈리아가 해결하지 못하는 대부분의 문제를 늠름하게 해결합니다.\n최근 북방합의체의 총참모장 펠릭스와 공식 석상에 동행하는 모습이 여러 번 목격되었기에, 일각에서는 어린 아이의 이미지를 정치 수단으로 사용한다는 비난 여론이 있었지만, 이에 관해 펠릭스 측은 어떤 입장도 밝히지 않았습니다.\n그저 언제나처럼, 어린 소녀에게 모호한 미소를 지을 뿐."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_OPR_DOGABI"
L38_1 = "「1급 관리자에 의해 복원된 내용입니다.」\n용혈인들로 구성된 조직, 삼군문 별동대를 이끄는 관리국의 옛 기수. 검사들의 훈련 지도를 맡고 있으며 인연을 점치는 주술적인 방식을 통해 인재를 모집한다. 한때는 제일삼검이라고도 불리며 칭송받았으나, 그 명성과 달리 그가 검을 뽑는 것을 보았다는 사람은 없다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_OPR_CREW"
L39_1 = "메리 크루는 프론트 베이의 명문가, 크루 가문의 안주인입니다.\n그녀는 동부 해경 사령관의 내조에 힘쓰는 아내이자, 세 자매의 엄격한 어머니로 알려져 있죠. 또한, 손에 물 한 번 안 묻혔을 것 같은 외모과는 달리 여러 고된 일에 나서 솔선수범하는 모습을 여러번 보여주어 노블레스 오블리주를 실천하는 귀부인으로도 유명합니다. 하지만 이런 그녀를 질투하는 사람들은 있기 마련, 메리 크루가 사실은 악명 높은 에이버리 해적단의 선원이었다는 소문이 퍼져 있습니다. 크루 가문은 이에 대해 낭설이라며 일축했지만, 사람들은 이를 그저 흥미로운 가십거리로 여기는 모양입니다."
L37_1[1] = L38_1
